import {
    useEffect,
    useState,
} from "react";

import { GraphCanvas } from "./graph/GraphCanvas";

import {
    configureNotion,
    validateNotionSettings,
} from "./notion/notionApi";

import {
    createPlotPage,
    deletePlotPage,
    loadPlot,
    updatePlotLabel,
    updatePlotLinkMasterId,
    updateRelation,
    updatePlotLayoutPreference,
} from "./notion/loadPlot";

import {
    goToBookmark,
    goToHeading,
} from "./onlyoffice/OnlyOfficeDocument";

import {
    createPlotGraphBookmark,
    deletePlotGraphBookmark,
    getPlotGraphBookmarkNames,
    subscribeActivePlotGraphBookmarks,
    subscribeDocumentHeadingPosition,
    subscribeDocumentTextSelection,
    subscribeManuscript,
    getPlotGraphDocumentSettings,
    savePlotGraphDocumentSettings,
} from "./onlyoffice/OnlyOfficeAdapter";

import type {
    LayoutPreference,
    TreeNode,
} from "./model/types";

const BOOKMARK_LINK_PREFIX =
    "onlyoffice:bookmark:";

function cloneTree(
    node: TreeNode
): TreeNode {
    return {
        ...node,
        layoutPreference:
            node.layoutPreference === undefined
                ? undefined
                : {
                    ...node.layoutPreference,
                },
        children: node.children.map(
            cloneTree
        ),
    };
}

function findNode(
    root: TreeNode,
    id: string,
): TreeNode | undefined {
    if (root.id === id) {
        return root;
    }

    for (const child of root.children) {
        const result = findNode(child, id);

        if (result) {
            return result;
        }
    }

    return undefined;
}

function getBookmarkName(
    root: TreeNode,
    nodeId: string,
): string | undefined {
    const node = findNode(root, nodeId);

    const linkMasterId = node?.linkMasterId;

    if (
        !linkMasterId?.startsWith(
            BOOKMARK_LINK_PREFIX,
        )
    ) {
        return undefined;
    }

    return linkMasterId.slice(
        BOOKMARK_LINK_PREFIX.length,
    );
}

function App() {
    const [plot, setPlot] =
        useState<TreeNode | null>(null);

    const [manuscript, setManuscript] =
        useState<TreeNode | null>(null);

    /*const [error, setError] =
        useState<string | null>(null);*/

    const [
        validBookmarkNames,
        setValidBookmarkNames,
    ] = useState<ReadonlySet<string>>(
        () => new Set(),
    );

    const [
        activeBookmarkNames,
        setActiveBookmarkNames,
    ] = useState<ReadonlySet<string>>(
        () => new Set(),
    );

    const [
        activeDocumentHeadingId,
        setActiveDocumentHeadingId,
    ] = useState<string | null>(null);

    const [
        hasTextSelection,
        setHasTextSelection,
    ] = useState(false);

    function refreshBookmarkNames(): void {
        getPlotGraphBookmarkNames(
            setValidBookmarkNames,
        );
    }

      const [
        notionSetup,
        setNotionSetup,
    ] = useState<{
        notionDataSourceId: string;
        notionApiKey: string;
    } | null>(null);

    const [
        notionSetupError,
        setNotionSetupError,
    ] = useState<string | null>(null);

    const [
        isSavingNotionSetup,
        setIsSavingNotionSetup,
    ] = useState(false);

    useEffect(() => {
        let cancelled = false;

        getPlotGraphDocumentSettings(
            async (savedSettings) => {
                if (!savedSettings) {
                    if (!cancelled) {
                        setNotionSetup({
                            notionDataSourceId: "",
                            notionApiKey: "",
                        });
                    }

                    return;
                }

                try {
                    const settings =
                        await validateNotionSettings(
                            savedSettings,
                        );

                    if (cancelled) {
                        return;
                    }

                    configureNotion(settings);

                    const loadedPlot =
                        await loadPlot();

                    if (!cancelled) {
                        setPlot(loadedPlot);
                    }
                } catch {
                    if (!cancelled) {
                        setNotionSetup({
                            notionDataSourceId:
                                savedSettings
                                    .notionDataSourceId,
                            notionApiKey: "",
                        });

                        setNotionSetupError(
                            "Den gemte Notion-forbindelse virker ikke længere. Indtast data source ID og API-nøgle igen.",
                        );
                    }
                }
            },
        );

        return () => {
            cancelled = true;
        };
    }, []);

    useEffect(() => {
        let hasLoadedBookmarks = false;

        let refreshTimer: number | null =
            null;

        const unsubscribe =
            subscribeManuscript((root) => {
                setManuscript(root);

                if (hasLoadedBookmarks) {
                    return;
                }

                hasLoadedBookmarks = true;

                refreshTimer = window.setTimeout(
                    refreshBookmarkNames,
                    0,
                );
            });

        return () => {
            unsubscribe();

            if (refreshTimer !== null) {
                window.clearTimeout(refreshTimer);
            }
        };
    }, []);

    useEffect(() => {
        return subscribeDocumentHeadingPosition(
            setActiveDocumentHeadingId,
        );
    }, []);

    useEffect(() => {
        return subscribeActivePlotGraphBookmarks(
            setActiveBookmarkNames,
        );
    }, []);

    useEffect(() => {
        return subscribeDocumentTextSelection(
            setHasTextSelection,
        );
    }, []);

    function movePlotNode(
        nodeId: string,
        parentId: string | null,
    ): void {
        setPlot((previous) => {
            if (!previous) {
                return previous;
            }

            const root = cloneTree(previous);

            let movedNode: TreeNode | undefined;

            function removeNode(
                parent: TreeNode,
            ): void {
                const index =
                    parent.children.findIndex(
                        (child) =>
                            child.id === nodeId,
                    );

                if (index !== -1) {
                    movedNode =
                        parent.children.splice(
                            index,
                            1,
                        )[0];

                    return;
                }

                for (const child of parent.children) {
                    if (movedNode) {
                        return;
                    }

                    removeNode(child);
                }
            }

            removeNode(root);

            if (!movedNode) {
                return previous;
            }

            if (parentId === null) {
                root.children.push(movedNode);
                return root;
            }

            const newParent = findNode(
                root,
                parentId,
            );

            if (!newParent) {
                return previous;
            }

            newParent.children.push(movedNode);

            return root;
        });
    }

 async function setPlotNodeLayoutPreferences(
    updates: Array<{
        nodeId: string;
        layoutPreference: LayoutPreference;
    }>
): Promise<void> {
    if (
        !plot ||
        updates.length === 0
    ) {
        return;
    }

    const root =
        cloneTree(plot);

    const persistedUpdates: Array<{
        nodeId: string;
        layoutPreference: LayoutPreference;
    }> = [];

    for (const update of updates) {
        const node =
            findNode(
                root,
                update.nodeId
            );

        if (!node) {
            continue;
        }

        node.layoutPreference = {
            ...node.layoutPreference,
            ...update.layoutPreference,
        };

        if (!update.nodeId.startsWith("new-")) {
            persistedUpdates.push({
                nodeId: update.nodeId,
                layoutPreference: {
                    ...node.layoutPreference,
                },
            });
        }
    }

    setPlot(root);

    try {
        await Promise.all(
            persistedUpdates.map(
                update =>
                    updatePlotLayoutPreference(
                        update.nodeId,
                        update.layoutPreference
                    )
            )
        );
    } catch (layoutError) {
        console.error(
            "Kunne ikke gemme PlotGraph-layout:",
            layoutError
        );

        setPlot(await loadPlot());
    }
}
    async function renamePlotNode(
        nodeId: string,
        label: string,
    ): Promise<void> {
        setPlot((previous) => {
            if (!previous) {
                return previous;
            }

            const root = cloneTree(previous);

            const target = findNode(root, nodeId);

            if (!target) {
                return previous;
            }

            target.label = label;

            return root;
        });

        if (nodeId.startsWith("new-")) {
            return;
        }

        try {
            await updatePlotLabel(nodeId, label);
        } catch (renameError) {
            console.error(
                "Kunne ikke gemme plotpunktets navn i Notion:",
                renameError,
            );

            setPlot(await loadPlot());
        }
    }

    function createPlotNode(
        parentId: string,
        sourceId: string,
        direction: "outgoing" | "incoming",
    ): string {
        const newId =
            `new-${crypto.randomUUID()}`;

        setPlot((previous) => {
            if (!previous) {
                return previous;
            }

            const root = cloneTree(previous);

            const parent = findNode(root, parentId);

            if (!parent) {
                return previous;
            }

            const newNode: TreeNode = {
                id: newId,
                label: "",
                role: "node",
                children: [],
                prerequisites:
                    direction === "outgoing"
                        ? [sourceId]
                        : [],
            };

            parent.children.push(newNode);

            if (direction === "incoming") {
                const source = findNode(
                    root,
                    sourceId,
                );

                source?.prerequisites.push(newId);
            }

            return root;
        });

        return newId;
    }

    async function persistNewPlotNode(
        nodeId: string,
        label: string,
    ): Promise<void> {
        if (!plot) {
            return;
        }

        const rootPlot = plot;

        let parentId: string | null = null;
        let sourceId: string | null = null;

        let direction:
            | "outgoing"
            | "incoming"
            | null = null;

        function findNodeReferencing(
            node: TreeNode,
            id: string,
        ): string | null {
            if (node.prerequisites.includes(id)) {
                return node.id;
            }

            for (const child of node.children) {
                const result =
                    findNodeReferencing(child, id);

                if (result) {
                    return result;
                }
            }

            return null;
        }

        function findContext(
            node: TreeNode,
        ): boolean {
            for (const child of node.children) {
                if (child.id === nodeId) {
                    parentId = node.id;

                    if (
                        child.prerequisites.length === 1
                    ) {
                        sourceId =
                            child.prerequisites[0];

                        direction = "outgoing";
                    } else {
                        sourceId =
                            findNodeReferencing(
                                rootPlot,
                                nodeId,
                            );

                        direction = sourceId
                            ? "incoming"
                            : null;
                    }

                    return true;
                }

                if (findContext(child)) {
                    return true;
                }
            }

            return false;
        }

        findContext(rootPlot);

        if (
            !parentId ||
            !sourceId ||
            !direction
        ) {
            return;
        }

        const result = await createPlotPage(
            parentId,
            label,
        );

        if (direction === "outgoing") {
            await updateRelation(
                result.id,
                [sourceId],
            );
        } else {
            await updateRelation(
                sourceId,
                [result.id],
            );
        }

        setPlot((previous) => {
            if (!previous) {
                return previous;
            }

            const root = cloneTree(previous);

            function replaceNodeIds(
                node: TreeNode,
            ): void {
                if (node.id === nodeId) {
                    node.id = result.id;
                    node.label = label;
                    node.properties = {
                        ...(node.properties ?? {}),
                        notionUrl: result.url,
                    };
                }

                node.prerequisites =
                    node.prerequisites.map((id) =>
                        id === nodeId
                            ? result.id
                            : id,
                    );

                for (const child of node.children) {
                    replaceNodeIds(child);
                }
            }

            replaceNodeIds(root);

            return root;
        });
    }

    function cancelPlotNode(
        nodeId: string,
    ): void {
        setPlot((previous) => {
            if (!previous) {
                return previous;
            }

            const root = cloneTree(previous);

            function removeNode(
                parent: TreeNode,
            ): boolean {
                const index =
                    parent.children.findIndex(
                        (child) =>
                            child.id === nodeId,
                    );

                if (index === -1) {
                    return parent.children.some(
                        removeNode,
                    );
                }

                parent.children.splice(index, 1);
                return true;
            }

            removeNode(root);

            return root;
        });
    }

    async function linkPlotGroup(
        plotNodeId: string,
        linkMasterId: string,
    ): Promise<boolean> {
        if (!plot) {
            return false;
        }

        const root = cloneTree(plot);

        const plotNode = findNode(
            root,
            plotNodeId,
        );

        if (!plotNode) {
            return false;
        }

        const previousLinkMasterId =
            plotNode.linkMasterId;

        plotNode.linkMasterId =
            linkMasterId || undefined;

        setPlot(root);

        try {
            await updatePlotLinkMasterId(
                plotNodeId,
                linkMasterId,
            );

            return true;
        } catch (linkError) {
            console.error(
                "Kunne ikke gemme linkMasterId i Notion:",
                linkError,
            );

            plotNode.linkMasterId =
                previousLinkMasterId;

            setPlot(await loadPlot());

            return false;
        }
    }

    async function addPlotRelation(
        sourceId: string,
        targetId: string,
    ): Promise<void> {
        if (!plot) {
            return;
        }

        const root = cloneTree(plot);

        const target = findNode(root, targetId);

        if (
            !target ||
            target.prerequisites.includes(sourceId)
        ) {
            return;
        }

        target.prerequisites.push(sourceId);

        setPlot(root);

        try {
            await updateRelation(
                targetId,
                target.prerequisites,
            );
        } catch (relationError) {
            console.error(
                "Kunne ikke oprette relation i Notion:",
                relationError,
            );

            setPlot(await loadPlot());
        }
    }

    async function removePlotRelation(
        sourceId: string,
        targetId: string,
    ): Promise<void> {
        if (!plot) {
            return;
        }

        const root = cloneTree(plot);

        const target = findNode(root, targetId);

        if (!target) {
            return;
        }

        const prerequisites =
            target.prerequisites.filter(
                (prerequisiteId) =>
                    prerequisiteId !== sourceId,
            );

        if (
            prerequisites.length ===
            target.prerequisites.length
        ) {
            return;
        }

        target.prerequisites = prerequisites;

        setPlot(root);

        try {
            await updateRelation(
                targetId,
                prerequisites,
            );
        } catch (relationError) {
            console.error(
                "Kunne ikke slette relation i Notion:",
                relationError,
            );

            setPlot(await loadPlot());
        }
    }

    function handleCreateBookmarkLink(
        plotNodeId: string,
    ): void {
        if (!plot) {
            return;
        }

        const previousBookmarkName =
            getBookmarkName(plot, plotNodeId);

        createPlotGraphBookmark(
            async (bookmarkName) => {
                if (!bookmarkName) {
                    console.warn(
                        "Ingen tekst var markeret, så bookmarket blev ikke oprettet.",
                    );

                    return;
                }

                const saved = await linkPlotGroup(
                    plotNodeId,
                    `${BOOKMARK_LINK_PREFIX}${bookmarkName}`,
                );

                if (!saved) {
                    deletePlotGraphBookmark(
                        bookmarkName,
                        () => refreshBookmarkNames(),
                    );

                    return;
                }

                if (
                    previousBookmarkName &&
                    previousBookmarkName !== bookmarkName
                ) {
                    deletePlotGraphBookmark(
                        previousBookmarkName,
                        (deleted) => {
                            if (!deleted) {
                                console.warn(
                                    "Det tidligere bookmark kunne ikke slettes.",
                                );
                            }
                        },
                    );
                }

                refreshBookmarkNames();
            },
        );
    }

    function handleUnlinkBookmark(
        plotNodeId: string,
    ): void {
        if (!plot) {
            return;
        }

        const bookmarkName = getBookmarkName(
            plot,
            plotNodeId,
        );

        if (!bookmarkName) {
            return;
        }

        void (async () => {
            const saved = await linkPlotGroup(
                plotNodeId,
                "",
            );

            if (!saved) {
                return;
            }

            deletePlotGraphBookmark(
                bookmarkName,
                (deleted) => {
                    if (!deleted) {
                        console.warn(
                            "Plottet er frigjort, men bookmarket kunne ikke slettes.",
                        );
                    }

                    refreshBookmarkNames();
                },
            );
        })();
    }

        function canDeletePlotNode(
        nodeId: string
    ): boolean {
        if (!plot) {
            return false;
        }

        const target = findNode(
            plot,
            nodeId
        );

        if (
            !target ||
            target.role !== "node" ||
            target.children.length > 0 ||
            target.prerequisites.length > 0 ||
            target.linkMasterId
        ) {
            return false;
        }

        function hasDependent(
            node: TreeNode
        ): boolean {
            if (
                node.id !== nodeId &&
                node.prerequisites.includes(nodeId)
            ) {
                return true;
            }

            return node.children.some(
                hasDependent
            );
        }

        return !hasDependent(plot);
    }

 async function deletePlotNode(
    nodeId: string
): Promise<void> {
    if (!canDeletePlotNode(nodeId)) {
        return;
    }

    try {
        await deletePlotPage(nodeId);

        setPlot(previous =>
            previous
                ? removeNodeFromTree(
                    previous,
                    nodeId
                )
                : previous
        );

        void loadPlot()
            .then(setPlot)
            .catch(error => {
                console.error(
                    "Kunne ikke genindlæse plottet efter sletning:",
                    error
                );
            });
    } catch (deleteError) {
        console.error(
            "Kunne ikke slette plotpunkt:",
            deleteError
        );

        setPlot(await loadPlot());
    }
}

    async function saveNotionSetup(
        notionDataSourceId: string,
        notionApiKey: string,
    ): Promise<void> {
        setIsSavingNotionSetup(true);
        setNotionSetupError(null);

        try {
            const settings =
                await validateNotionSettings({
                    notionDataSourceId,
                    notionApiKey,
                });

            await new Promise<void>(
                (resolve, reject) => {
                    savePlotGraphDocumentSettings(
                        settings,
                        (saved) => {
                            if (saved) {
                                resolve();
                                return;
                            }

                            reject(
                                new Error(
                                    "Kunne ikke gemme PlotGraph-indstillinger i dokumentet.",
                                ),
                            );
                        },
                    );
                },
            );

            configureNotion(settings);

            const loadedPlot =
                await loadPlot();

            setPlot(loadedPlot);
            setNotionSetup(null);
        } catch (setupError) {
            setNotionSetupError(
                setupError instanceof Error
                    ? setupError.message
                    : "Kunne ikke oprette forbindelsen til Notion.",
            );
        } finally {
            setIsSavingNotionSetup(false);
        }
    }
    if (notionSetup) {
        return (
            <NotionSetupScreen
                initialDataSourceId={
                    notionSetup.notionDataSourceId
                }
                initialApiKey={
                    notionSetup.notionApiKey
                }
                error={notionSetupError}
                isSaving={isSavingNotionSetup}
                onSave={saveNotionSetup}
            />
        );
    }

   /* if (error) {
        return <div>Fejl: {error}</div>;
    }*/

    if (!plot || !manuscript) {
        return <div>Henter struktur…</div>;
    }

    return (
        <GraphCanvas
            plot={plot}
            manuscript={manuscript}
            activeDocumentHeadingId={
                activeDocumentHeadingId
            }
            activeBookmarkNames={activeBookmarkNames}
            hasTextSelection={hasTextSelection}
            reloadPlot={() =>
                loadPlot().then(setPlot)
            }
            movePlotNode={movePlotNode}
             setPlotNodeLayoutPreferences={
                setPlotNodeLayoutPreferences
            }
            renamePlotNode={renamePlotNode}
            createPlotNode={createPlotNode}
            persistNewPlotNode={persistNewPlotNode}
            cancelPlotNode={cancelPlotNode}
            addPlotRelation={addPlotRelation}
            removePlotRelation={removePlotRelation}
            linkPlotGroup={linkPlotGroup}
            navigateToParagraph={goToHeading}
            navigateToBookmark={goToBookmark}
            onCreateBookmarkLink={
                handleCreateBookmarkLink
            }
            onUnlinkBookmark={
                handleUnlinkBookmark
            }
             canDeletePlotNode={
                canDeletePlotNode
            }
            deletePlotNode={
                deletePlotNode
            }
            validBookmarkNames={validBookmarkNames}
        />
    );
}

function removeNodeFromTree(
    root: TreeNode,
    nodeId: string
): TreeNode {
    return {
        ...root,
        children: root.children
            .filter(
                child => child.id !== nodeId
            )
            .map(
                child =>
                    removeNodeFromTree(
                        child,
                        nodeId
                    )
            ),
    };
}

interface NotionSetupScreenProps {
    initialDataSourceId: string;
    initialApiKey: string;
    error: string | null;
    isSaving: boolean;

    onSave: (
        notionDataSourceId: string,
        notionApiKey: string,
    ) => Promise<void>;
}

function NotionSetupScreen(
    props: NotionSetupScreenProps,
) {
    const [
        notionDataSourceId,
        setNotionDataSourceId,
    ] = useState(
        props.initialDataSourceId,
    );

    const [
        notionApiKey,
        setNotionApiKey,
    ] = useState(
        props.initialApiKey,
    );

    return (
        <main
            style={{
                maxWidth: 520,
                padding: 24,
            }}
        >
            <h2>Forbind PlotGraph med Notion</h2>

            <p>
                Indstillingerne gemmes som skjulte
                PlotGraph-metadata i dette dokument.
            </p>

            <form
                onSubmit={(event) => {
                    event.preventDefault();

                    void props.onSave(
                        notionDataSourceId,
                        notionApiKey,
                    );
                }}
            >
                <label
                    style={{
                        display: "block",
                        marginBottom: 16,
                    }}
                >
                    Notion data source ID

                    <input
                        type="text"
                        required
                        value={notionDataSourceId}
                        onChange={(event) => {
                            setNotionDataSourceId(
                                event.target.value,
                            );
                        }}
                        style={{
                            boxSizing: "border-box",
                            display: "block",
                            marginTop: 6,
                            width: "100%",
                        }}
                    />
                </label>

                <label
                    style={{
                        display: "block",
                        marginBottom: 16,
                    }}
                >
                    Notion API-nøgle

                    <input
                        type="password"
                        required
                        autoComplete="off"
                        value={notionApiKey}
                        onChange={(event) => {
                            setNotionApiKey(
                                event.target.value,
                            );
                        }}
                        style={{
                            boxSizing: "border-box",
                            display: "block",
                            marginTop: 6,
                            width: "100%",
                        }}
                    />
                </label>

                {props.error && (
                    <p
                        style={{
                            color: "#b42318",
                        }}
                    >
                        {props.error}
                    </p>
                )}

                <button
                    type="submit"
                    disabled={props.isSaving}
                >
                    {props.isSaving
                        ? "Forbinder…"
                        : "Gem og forbind"}
                </button>
            </form>
        </main>
    );
}

export default App;