import * as d3 from "d3";

import {
    movePage,
} from "../notion/loadPlot";

import type {
    LayoutPreference,
} from "../model/types";

import type {
    SimulationNode,
} from "./GraphCanvas.helpers";

import type {
    Layout,
    LayoutGroup,
    LayoutTreeNode,
} from "./layout";

export interface GraphNodeDraggingCallbacks {
    movePlotNode: (
        nodeId: string,
        parentId: string | null,
    ) => void;

    setPlotNodeLayoutPreferences: (
        updates: Array<{
            nodeId: string;
            layoutPreference: LayoutPreference;
        }>,
    ) => Promise<void>;

    reloadPlot: () => Promise<void>;
}

interface DropTarget {
    node: LayoutTreeNode["node"];
    depth: number;
    distance: number;
    group: LayoutGroup | undefined;
}

export function enableGraphNodeDragging(
    nodeGroups: d3.Selection<
        SVGGElement,
        SimulationNode,
        SVGGElement,
        unknown
    >,
    simulation: d3.Simulation<
        SimulationNode,
        undefined
    >,
    layout: Layout,
    _groups: {
        expanded: Set<string>;
    },
    callbacks: GraphNodeDraggingCallbacks,
): void {
    void _groups;

    let dragMoved = false;

    const savedPins = new Map<
        SimulationNode,
        {
            fx: number | null | undefined;
            fy: number | null | undefined;
        }
    >();

    function freezeOtherNodes(
        draggedNode: SimulationNode,
    ): void {
        savedPins.clear();

        nodeGroups.each(candidate => {
            if (candidate === draggedNode) {
                return;
            }

            savedPins.set(
                candidate,
                {
                    fx: candidate.fx,
                    fy: candidate.fy,
                },
            );

            candidate.fx = candidate.x;
            candidate.fy = candidate.y;
        });
    }

    function restoreOtherNodes(): void {
        for (const [
            node,
            previous,
        ] of savedPins) {
            node.fx = previous.fx;
            node.fy = previous.fy;
        }

        savedPins.clear();
    }

    function headerY(
        treeNode: LayoutTreeNode,
    ): number | undefined {
        const expandedGroup =
            layout.groups.find(
                group =>
                    group.side === "plot" &&
                    group.node.id ===
                        treeNode.node.id,
            );

        if (expandedGroup) {
            return expandedGroup.y + 25;
        }

        const aggregate =
            layout.nodes.find(
                node =>
                    node.node.side === "plot" &&
                    node.node.type === "aggregate" &&
                    node.node.source.id ===
                        treeNode.node.id,
            );

        return aggregate?.y;
    }

    function contains(
        group: LayoutGroup,
        x: number,
        y: number,
    ): boolean {
        return (
            x >= group.x &&
            x <= group.x + group.width &&
            y >= group.y &&
            y <= group.y + group.height
        );
    }

    function findDropTarget(
        x: number,
        y: number,
    ): DropTarget | undefined {
        const containingTargets =
            layout.groups
                .filter(
                    group =>
                        group.side === "plot" &&
                        contains(group, x, y),
                )
                .map(group => ({
                    node: group.node,
                    depth: group.depth,
                    distance: 0,
                    group,
                }));

        const headerTargets =
            layout.tree
                .filter(
                    treeNode =>
                        treeNode.side === "plot",
                )
                .map(treeNode => {
                    const yPosition =
                        headerY(treeNode);

                    if (yPosition === undefined) {
                        return undefined;
                    }

                    const distance =
                        Math.abs(y - yPosition);

                    if (distance > 18) {
                        return undefined;
                    }

                    return {
                        node: treeNode.node,
                        depth: treeNode.depth,
                        distance,
                        group: layout.groups.find(
                            group =>
                                group.side === "plot" &&
                                group.node.id ===
                                    treeNode.node.id,
                        ),
                    };
                })
                .filter(
                    (
                        target,
                    ): target is DropTarget =>
                        target !== undefined,
                );

        return [
            ...containingTargets,
            ...headerTargets,
        ].sort(
            (left, right) =>
                right.depth - left.depth ||
                left.distance - right.distance,
        )[0];
    }

    function clampRank(
        value: number,
    ): number {
        return Math.max(
            0,
            Math.min(1, value),
        );
    }

    function getDroppedLayoutPreference(
        node: SimulationNode,
        target: DropTarget | undefined,
        x: number,
        y: number,
    ): LayoutPreference {
        const sceneId =
            target?.node.id ??
            node.node.localSceneId;

        const sceneNodes =
            layout.nodes.filter(
                candidate =>
                    candidate.node.side === "plot" &&
                    candidate.node.type === "node" &&
                    candidate.node.localSceneId ===
                        sceneId,
            );

        const top =
            sceneNodes.length > 0
                ? Math.min(
                    ...sceneNodes.map(
                        candidate =>
                            candidate.y -
                            candidate.height / 2,
                    ),
                )
                : target?.group?.y ?? y;

        const bottom =
            sceneNodes.length > 0
                ? Math.max(
                    ...sceneNodes.map(
                        candidate =>
                            candidate.y +
                            candidate.height / 2,
                    ),
                )
                : (
                    target?.group
                        ? target.group.y +
                            target.group.height
                        : y + 1
                );

        /*
         * Den vandrette rang bruger hele
         * layoutets arbejdsbredde — ikke
         * labelbredden eller den lokale scene.
         * Ellers rammer rank 1 for tidligt.
         */
        const horizontalLeft = 28;
        const horizontalRight =
            Math.max(
                horizontalLeft + 1,
                layout.width - 28,
            );

        return {
            horizontalRank: clampRank(
                (x - horizontalLeft) /
                (
                    horizontalRight -
                    horizontalLeft
                ),
            ),
            verticalRank: clampRank(
                (y - top) /
                Math.max(1, bottom - top),
            ),
        };
    }

    nodeGroups.call(
        d3
            .drag<
                SVGGElement,
                SimulationNode
            >()
            .on(
                "start",
                (
                    event,
                    node,
                ) => {
                    if (
                        node.node.side !== "plot" ||
                        node.node.type !== "node"
                    ) {
                        return;
                    }

                    event.sourceEvent?.stopPropagation();

                    dragMoved = false;

                    freezeOtherNodes(node);

                    if (!event.active) {
                        simulation
                            .alphaTarget(0.3)
                            .restart();
                    }

                    node.fx = node.x;
                    node.fy = node.y;
                },
            )
            .on(
                "drag",
                (
                    event,
                    node,
                ) => {
                    if (
                        node.node.side !== "plot" ||
                        node.node.type !== "node"
                    ) {
                        return;
                    }

                    if (
                        Math.abs(
                            event.x - node.x,
                        ) > 2 ||
                        Math.abs(
                            event.y - node.y,
                        ) > 2
                    ) {
                        dragMoved = true;
                    }

                    node.fx = event.x;
                    node.fy = event.y;
                },
            )
            .on(
                "end",
                async (
                    event,
                    node,
                ) => {
                    if (
                        node.node.side !== "plot" ||
                        node.node.type !== "node"
                    ) {
                        return;
                    }

                    if (!event.active) {
                        simulation
                            .alphaTarget(0)
                            .alpha(0);
                    }

                    node.fx = null;
                    node.fy = null;

                    restoreOtherNodes();

                    if (!dragMoved) {
                        return;
                    }

                    const target =
                        findDropTarget(
                            event.x,
                            event.y,
                        );

                    const parentId =
                        target?.node.id ?? null;

                    const currentParentId =
                        node.node.localSceneId ?? null;

                    const layoutPreference =
                        getDroppedLayoutPreference(
                            node,
                            target,
                            event.x,
                            event.y,
                        );

                    try {
                        /*
                         * En flytning i samme scene
                         * er stadig en reel handling:
                         * den skal gemme brugerens
                         * nye vandrette/lodrette rang.
                         */
                        if (
                            parentId !==
                            currentParentId
                        ) {
                            callbacks.movePlotNode(
                                node.node.source.id,
                                parentId,
                            );

                            await movePage(
                                node.node.source.id,
                                parentId,
                            );
                        }

                        await callbacks.setPlotNodeLayoutPreferences(
                            [
                                {
                                    nodeId:
                                        node.node.source.id,
                                    layoutPreference,
                                },
                            ],
                        );
                    } catch (error) {
                        console.error(
                            "Kunne ikke gemme plotpunktets placering:",
                            error,
                        );

                        await callbacks.reloadPlot();
                    }
                },
            ),
    );
}