import type { TreeNode } from "../model/types";

import {
    getRuntimePlotTree,
} from "./structure";

type Side = "manuscript" | "plot";

export interface FocusVisibility {
    plotNodeIds: Set<string>;
    manuscriptGroupIds: Set<string>;
    plotGroupIds: Set<string>;

    showsGroup(
        side: Side,
        id: string
    ): boolean;

    showsPlotNode(
        id: string
    ): boolean;
}

export function createFocusVisibility(
    manuscriptRoot: TreeNode,
    causalPlotNodeIds: ReadonlySet<string>,
    activeDocumentHeadingId: string | null
): FocusVisibility {
    const plotRoot =
        getRuntimePlotTree(manuscriptRoot);

    const plotNodeIds =
        new Set<string>();

    const plotGroupIds =
        new Set<string>();

    const manuscriptGroupIds =
        new Set<string>();

    if (!plotRoot) {
        return visibility(
            plotNodeIds,
            manuscriptGroupIds,
            plotGroupIds
        );
    }

    function collectVisiblePlot(
        node: TreeNode
    ): boolean {
        if (node.role === "node") {
            const included =
                causalPlotNodeIds.has(node.id);

            if (included) {
                plotNodeIds.add(node.id);
            }

            return included;
        }

        let hasVisibleDescendant = false;

        for (const child of node.children) {
            if (collectVisiblePlot(child)) {
                hasVisibleDescendant = true;
            }
        }

        if (hasVisibleDescendant) {
            plotGroupIds.add(node.id);
        }

        return hasVisibleDescendant;
    }

    collectVisiblePlot(plotRoot);

    const activeManuscriptPath =
        activeDocumentHeadingId
            ? findPath(
                manuscriptRoot,
                activeDocumentHeadingId
            ) ?? []
            : [];

    const activeManuscriptIds =
        new Set(
            activeManuscriptPath.map(
                node => node.id
            )
        );

    function collectVisibleManuscript(
        node: TreeNode
    ): boolean {
        if (node.role === "node") {
            return false;
        }

        const linkedPlotGroupVisible =
            node.link?.role === "container" &&
            plotGroupIds.has(node.link.id);

        const activePathVisible =
            activeManuscriptIds.has(node.id);

        let hasVisibleDescendant = false;

        for (const child of node.children) {
            if (collectVisibleManuscript(child)) {
                hasVisibleDescendant = true;
            }
        }

        const included =
            linkedPlotGroupVisible ||
            activePathVisible ||
            hasVisibleDescendant;

        if (included) {
            manuscriptGroupIds.add(node.id);
        }

        return included;
    }

    collectVisibleManuscript(
        manuscriptRoot
    );

    return visibility(
        plotNodeIds,
        manuscriptGroupIds,
        plotGroupIds
    );
}

function visibility(
    plotNodeIds: Set<string>,
    manuscriptGroupIds: Set<string>,
    plotGroupIds: Set<string>
): FocusVisibility {
    return {
        plotNodeIds,
        manuscriptGroupIds,
        plotGroupIds,

        showsGroup(
            side: Side,
            id: string
        ): boolean {
            return (
                side === "manuscript"
                    ? manuscriptGroupIds
                    : plotGroupIds
            ).has(id);
        },

        showsPlotNode(
            id: string
        ): boolean {
            return plotNodeIds.has(id);
        },
    };
}

function findPath(
    node: TreeNode,
    targetId: string
): TreeNode[] | undefined {
    if (node.id === targetId) {
        return [node];
    }

    for (const child of node.children) {
        const childPath =
            findPath(child, targetId);

        if (childPath) {
            return [
                node,
                ...childPath,
            ];
        }
    }

    return undefined;
}