import type { PresentationModel } from "./presentation";
import type { Layout } from "./layout";

import {
    containsNode,
    countCrossedGroups,
} from "./GraphCanvas.helpers";

import type {
    SimulationEdge,
    SimulationNode,
    StoredNodePosition,
} from "./GraphCanvas.helpers";


export function createGraphSimulationData(
    layout: Layout,
    presentation: PresentationModel,
    availableWidth: number,
    nodePositions: Map<
        string,
        StoredNodePosition
    >
): {
    simulationNodes: SimulationNode[];
    edges: SimulationEdge[];
} {
    void availableWidth;

    const simulationNodes: SimulationNode[] =
        layout.nodes.map(layoutNode => {
            const previous =
                nodePositions.get(
                    layoutNode.node.id
                );

            const layoutIsUnchanged =
                previous !== undefined &&
                Math.abs(
                    previous.layoutX -
                        layoutNode.x
                ) < 0.01 &&
                Math.abs(
                    previous.layoutY -
                        layoutNode.y
                ) < 0.01;

            const simulationNode: SimulationNode = {
                ...layoutNode,
                x: layoutIsUnchanged
                    ? previous.x
                    : layoutNode.x,
                y: layoutIsUnchanged
                    ? previous.y
                    : layoutNode.y,
                baseX: layoutNode.x,
                baseY: layoutNode.y,
                fx: null,
                fy: null,
            };           

            return simulationNode;
        });

    const simulationNodeById =
        new Map(
            simulationNodes.map(node => [
                node.node.id,
                node,
            ])
        );

    const edges: SimulationEdge[] = [];

    for (const edge of presentation.edges) {
        const sourceNode =
            simulationNodeById.get(
                edge.source
            );

        const targetNode =
            simulationNodeById.get(
                edge.target
            );

        if (!sourceNode || !targetNode) {
            continue;
        }

        if (
            sourceNode.node.type === "aggregate" &&
            targetNode.node.type === "aggregate"
        ) {
            continue;
        }

        const sourceGroup =
            layout.groups.find(group =>
                containsNode(
                    group.node,
                    sourceNode.node.source.id
                )
            );

        const targetGroup =
            layout.groups.find(group =>
                containsNode(
                    group.node,
                    targetNode.node.source.id
                )
            );

        const simulationEdge: SimulationEdge = {
            ...edge,
            sourceNode,
            targetNode,
            internal:
                sourceGroup?.node.id ===
                targetGroup?.node.id,
        };

        simulationEdge.crossedGroups =
            countCrossedGroups(
                simulationEdge,
                layout.groups,
                sourceGroup?.node.id,
                targetGroup?.node.id
            );

        edges.push(simulationEdge);
    }

    return {
        simulationNodes,
        edges,
    };
}