import * as d3 from "d3";

import type { TreeNode } from "../model/types";

import {
    isLegalRelation,
} from "./interaction/relationEditor";

import type {
    SimulationNode,
} from "./GraphCanvas.helpers";

import type {
    Layout,
} from "./layout";

interface GraphQuicklinksCallbacks {
    addPlotRelation(
        sourceId: string,
        targetId: string
    ): void;

    createPlotNode(
        parentId: string,
        sourceId: string,
        direction: "outgoing" | "incoming"
    ): string;

    setEditingNodeId(
        nodeId: string
    ): void;
}

export interface GraphQuicklinks {
    start(
        node: SimulationNode,
        direction: "outgoing" | "incoming"
    ): void;

    drag(
        x: number,
        y: number
    ): void;

    end(
        dropX: number,
        dropY: number
    ): Promise<void>;
}

export function createGraphQuicklinks(
    structure: TreeNode,
    simulationNodes: SimulationNode[],
    nodeGroups: d3.Selection<
        SVGGElement,
        SimulationNode,
        SVGGElement,
        unknown
    >,
    quicklinkLayer: d3.Selection<
        SVGGElement,
        unknown,
        null,
        undefined
    >,
    layout: Layout,
    neighborhoodNodeId: string | null,
    causalNeighborhood: {
        upstream: Set<string>;
        downstream: Set<string>;
    },
    callbacks: GraphQuicklinksCallbacks
): GraphQuicklinks {
    let quicklinkDrag:
        | {
            direction:
                | "outgoing"
                | "incoming";
            sourceId: string;
            illegalTargetIds: Set<string>;
        }
        | null = null;

    let quicklinkLine:
        | d3.Selection<
            SVGLineElement,
            unknown,
            null,
            undefined
        >
        | null = null;

    function start(
        node: SimulationNode,
        direction:
            | "outgoing"
            | "incoming"
    ): void {
        if (
            node.node.side !== "plot" ||
            node.node.type === "aggregate"
        ) {
            return;
        }

        const illegalTargetIds =
            new Set<string>();

        for (const candidate of simulationNodes) {
            if (
                candidate.node.side !== "plot" ||
                candidate.node.type === "aggregate"
            ) {
                continue;
            }

            const candidateId =
                candidate.node.source.id;

            if (
                candidateId ===
                node.node.source.id
            ) {
                illegalTargetIds.add(candidateId);
                continue;
            }

            const sourceId =
                direction === "outgoing"
                    ? node.node.source.id
                    : candidateId;

            const targetId =
                direction === "outgoing"
                    ? candidateId
                    : node.node.source.id;

            if (
                !isLegalRelation(
                    structure,
                    sourceId,
                    targetId
                )
            ) {
                illegalTargetIds.add(candidateId);
            }
        }

        quicklinkDrag = {
            direction,
            sourceId: node.node.source.id,
            illegalTargetIds,
        };

        nodeGroups
            .filter(
                candidate =>
                    candidate.node.side === "plot" &&
                    candidate.node.type !==
                        "aggregate"
            )
            .attr(
                "opacity",
                candidate =>
                    illegalTargetIds.has(
                        candidate.node.source.id
                    )
                        ? 0.15
                        : 1
            );

        quicklinkLine =
            quicklinkLayer
                .append("line")
                .attr("x1", node.x)
                .attr("y1", node.y)
                .attr("x2", node.x)
                .attr("y2", node.y)
                .attr("stroke", "#d33")
                .attr("stroke-width", 2)
                .attr("stroke-dasharray", "5 4")
                .attr(
                    "pointer-events",
                    "none"
                );
    }

    function drag(
        x: number,
        y: number
    ): void {
        if (!quicklinkLine) {
            return;
        }

        quicklinkLine
            .attr("x2", x)
            .attr("y2", y);
    }

    async function end(
        dropX: number,
        dropY: number
    ): Promise<void> {
        if (!quicklinkDrag) {
            return;
        }

        const drag = quicklinkDrag;

        quicklinkDrag = null;

        nodeGroups.attr(
            "opacity",
            node => {
                if (!neighborhoodNodeId) {
                    return 1;
                }

                const id =
                    node.node.source.id;

                if (
                    id === neighborhoodNodeId ||
                    causalNeighborhood.upstream.has(id) ||
                    causalNeighborhood.downstream.has(id)
                ) {
                    return 1;
                }

                return 0.15;
            }
        );

        quicklinkLine?.remove();
        quicklinkLine = null;

        const target =
            simulationNodes.find(
                node =>
                    node.node.side === "plot" &&
                    node.node.type !==
                        "aggregate" &&
                    node.node.source.id !==
                        drag.sourceId &&
                    Math.hypot(
                        node.x - dropX,
                        node.y - dropY
                    ) < 18
            );

        if (
            target &&
            !drag.illegalTargetIds.has(
                target.node.source.id
            )
        ) {
            if (drag.direction === "outgoing") {
                callbacks.addPlotRelation(
                    drag.sourceId,
                    target.node.source.id
                );
            } else {
                callbacks.addPlotRelation(
                    target.node.source.id,
                    drag.sourceId
                );
            }

            return;
        }

               const targetGroup =
            layout.groups
                .filter(
                    group =>
                        group.side === "plot" &&
                        dropX >= group.x &&
                        dropX <=
                            group.x +
                                group.width &&
                        dropY >= group.y &&
                        dropY <=
                            group.y +
                                group.height
                )
                .sort(
                    (left, right) =>
                        right.depth - left.depth
                )[0];

        if (!targetGroup) {
            return;
        }

        const newNodeId =
            callbacks.createPlotNode(
                targetGroup.node.id,
                drag.sourceId,
                drag.direction
            );

        callbacks.setEditingNodeId(newNodeId);
    }

    return {
        start,
        drag,
        end,
    };
}