import * as d3 from "d3";

import type { TreeNode } from "../model/types";

import type {
    SimulationEdge,
    SimulationNode,
} from "./GraphCanvas.helpers";

import {
    enableRelationSelection,
} from "./interaction/relationEditor";

interface GraphEdgesOptions {
    causalFocusNodeIds: ReadonlySet<string>;
    causalNeighborhood: {
        upstream: Set<string>;
        downstream: Set<string>;
    };
    selectedRelation: {
        sourceId: string;
        targetId: string;
    } | null;
}

interface CausalMembership {
    selected: boolean;
    upstream: boolean;
    downstream: boolean;
}

export interface GraphEdges {
    edgePaths: d3.Selection<
        SVGPathElement,
        SimulationEdge,
        SVGGElement,
        unknown
    >;

    edgeHitPaths: d3.Selection<
        SVGPathElement,
        SimulationEdge,
        SVGGElement,
        unknown
    >;
}

export function renderGraphEdges(
    d3Layer: d3.Selection<
        SVGGElement,
        unknown,
        null,
        undefined
    >,
    edges: SimulationEdge[],
    options: GraphEdgesOptions,
    onSelectRelation: (
        sourceId: string,
        targetId: string
    ) => void
): GraphEdges {
    const {
    causalFocusNodeIds,
    causalNeighborhood,
    selectedRelation,
} = options;

    const edgeLayer =
        d3Layer
            .append("g")
            .attr(
                "class",
                "edges"
            );

    const edgePaths =
        edgeLayer
            .selectAll<
                SVGPathElement,
                SimulationEdge
            >("path")
            .data(edges)
            .join("path")
            .attr(
                "fill",
                "none"
            )
            .attr(
                "stroke",
                "#777"
            )
            .attr(
                "stroke-width",
                1.5
            )
            .attr(
    "opacity",
    edge => {
        if (causalFocusNodeIds.size === 0) {
            return edge.internal
                ? 1
                : Math.max(
                    0.15,
                    1 -
                        (edge.crossedGroups ?? 0) *
                            0.08
                );
        }

        return isCausalEdge(
            edge,
            causalFocusNodeIds,
            causalNeighborhood
        )
            ? 1
            : 0.08;
    }
)
            .attr(
                "stroke",
                edge => {
                    if (!selectedRelation) {
                        return "#777";
                    }

                    const sourceId =
                        edge.sourceNode
                            ?.node.source.id;

                    const targetId =
                        edge.targetNode
                            ?.node.source.id;

                    if (
                        sourceId ===
                            selectedRelation.sourceId &&
                        targetId ===
                            selectedRelation.targetId
                    ) {
                        return "#d33";
                    }

                    return "#777";
                }
            )
            .attr(
                "stroke-width",
                edge => {
                    if (!selectedRelation) {
                        return 1.5;
                    }

                    const sourceId =
                        edge.sourceNode
                            ?.node.source.id;

                    const targetId =
                        edge.targetNode
                            ?.node.source.id;

                    if (
                        sourceId ===
                            selectedRelation.sourceId &&
                        targetId ===
                            selectedRelation.targetId
                    ) {
                        return 3;
                    }

                    return 1.5;
                }
            )
            .attr(
                "marker-end",
                "url(#arrowhead)"
            );

    const edgeHitPaths =
        edgeLayer
            .selectAll<
                SVGPathElement,
                SimulationEdge
            >(
                "path.edge-hit"
            )
            .data(edges)
            .join("path")
            .attr(
                "class",
                "edge-hit"
            )
            .attr(
                "fill",
                "none"
            )
            .attr(
                "stroke",
                "transparent"
            )
            .attr(
                "stroke-width",
                14
            );

    enableRelationSelection(
        edgeHitPaths,
        onSelectRelation
    );

    return {
        edgePaths,
        edgeHitPaths,
    };
}

export function isCausalEdge(
    edge: SimulationEdge,
    focusIds: ReadonlySet<string>,
    causalNeighborhood: {
        upstream: Set<string>;
        downstream: Set<string>;
    }
): boolean {
    const source = getCausalMembership(
        edge.sourceNode,
        focusIds,
        causalNeighborhood
    );

    const target = getCausalMembership(
        edge.targetNode,
        focusIds,
        causalNeighborhood
    );

    return (
        (
            source.upstream &&
            (
                target.upstream ||
                target.selected
            )
        ) ||
        (
            source.selected &&
            (
                target.selected ||
                target.downstream
            )
        ) ||
        (
            source.downstream &&
            target.downstream
        )
    );
}

function getCausalMembership(
    node: SimulationNode | undefined,
    focusIds: ReadonlySet<string>,
    causalNeighborhood: {
        upstream: Set<string>;
        downstream: Set<string>;
    }
): CausalMembership {
    if (!node) {
        return {
            selected: false,
            upstream: false,
            downstream: false,
        };
    }

    return {
        selected: containsNode(
            node.node.source,
            id => focusIds.has(id)
        ),

        upstream: containsNode(
            node.node.source,
            id =>
                causalNeighborhood.upstream.has(id)
        ),

        downstream: containsNode(
            node.node.source,
            id =>
                causalNeighborhood.downstream.has(id)
        ),
    };
}

function containsNode(
    node: TreeNode,
    predicate: (id: string) => boolean
): boolean {
    if (predicate(node.id)) {
        return true;
    }

    return node.children.some(
        child =>
            containsNode(
                child,
                predicate
            )
    );
}