import type { TreeNode } from "../model/types";

import {
    getRuntimePlotTree,
} from "./structure";

export interface CausalNeighborhood {
    upstream: Set<string>;
    downstream: Set<string>;
}

export function getCausalNeighborhood(
    root: TreeNode,
    selectedId: string
): CausalNeighborhood {
    return getCombinedCausalNeighborhood(
        root,
        [selectedId]
    );
}

export function getCombinedCausalNeighborhood(
    root: TreeNode,
    selectedIds: Iterable<string>
): CausalNeighborhood {
    const nodes =
        getAllSemanticNodes(
            root,
            getRuntimePlotTree(root)
        );

    const byId =
        new Map<string, TreeNode>();

    const focusIds = new Set(selectedIds);

    for (const node of nodes) {
        byId.set(node.id, node);
    }

    for (const id of focusIds) {
        if (!byId.has(id)) {
            focusIds.delete(id);
        }
    }

    const downstreamById =
        new Map<string, string[]>();

    for (const node of nodes) {
        for (
            const prerequisiteId of
            node.prerequisites
        ) {
            const dependents =
                downstreamById.get(
                    prerequisiteId
                ) ?? [];

            dependents.push(node.id);

            downstreamById.set(
                prerequisiteId,
                dependents
            );
        }
    }

    const upstream =
        new Set<string>();

    const downstream =
        new Set<string>();

    function visitUpstream(
        id: string
    ): void {
        const node = byId.get(id);

        if (!node) {
            return;
        }

        for (
            const prerequisiteId of
            node.prerequisites
        ) {
            if (
                focusIds.has(prerequisiteId) ||
                upstream.has(prerequisiteId)
            ) {
                continue;
            }

            upstream.add(prerequisiteId);

            visitUpstream(prerequisiteId);
        }
    }

    function visitDownstream(
        id: string
    ): void {
        const dependents =
            downstreamById.get(id) ?? [];

        for (
            const dependentId of
            dependents
        ) {
            if (
                focusIds.has(dependentId) ||
                downstream.has(dependentId)
            ) {
                continue;
            }

            downstream.add(dependentId);

            visitDownstream(dependentId);
        }
    }

    for (const id of focusIds) {
        visitUpstream(id);
        visitDownstream(id);
    }

    return {
        upstream,
        downstream,
    };
}

function getAllSemanticNodes(
    manuscriptRoot: TreeNode,
    plotRoot: TreeNode | undefined
): TreeNode[] {
    const result: TreeNode[] = [];
    const visitedIds = new Set<string>();

    function visit(
        node: TreeNode
    ): void {
        if (visitedIds.has(node.id)) {
            return;
        }

        visitedIds.add(node.id);
        result.push(node);

        for (const child of node.children) {
            visit(child);
        }
    }

    visit(manuscriptRoot);

    if (plotRoot) {
        visit(plotRoot);
    }

    return result;
}