import * as d3 from "d3";
import "./RadialMenuD3.css";

export interface RadialMenuItem {
    id: string;
    label: string;
    icon: string;
    interactive?: boolean;
    draggable?: boolean;
    children?: RadialMenuItem[];

    preferredAngle?: number;

    toggle?: boolean;
    active?: boolean;
    activeIcon?: string;
}

export interface RadialMenuCallbacks {
    onSelect: (
        item: RadialMenuItem
    ) => void;

    onToggle?: (
        item: RadialMenuItem,
        active: boolean
    ) => void;

    onDragStart?: (
        item: RadialMenuItem,
        x: number,
        y: number
    ) => void;

    onDrag?: (
        item: RadialMenuItem,
        x: number,
        y: number
    ) => void;

    onDragEnd?: (
        item: RadialMenuItem,
        x: number,
        y: number
    ) => void;
}

export interface RadialMenuOptions
    extends RadialMenuCallbacks {
    x: number;
    y: number;

    center: RadialMenuItem;
    secondary: RadialMenuItem[];

    renderIcon: (
        group: d3.Selection<
            SVGGElement,
            unknown,
            null,
            undefined
        >,
        icon: string,
        size: number
    ) => void;
}

type MenuState =
    | "idle"
    | "preview"
    | "expanded";

interface DragState {
    item: RadialMenuItem;
    startX: number;
    startY: number;
    active: boolean;
}

interface SecondaryLayoutItem {
    item: RadialMenuItem;
    angle: number;
}

const TWO_PI = Math.PI * 2;

const INNER_RADIUS = 15;
const OUTER_RADIUS = 30;
const MENU_ITEM_RADIUS = 12;
const DRAG_THRESHOLD = 4;

const PROXIMITY_RADIUS =
    OUTER_RADIUS + 8;

const SECONDARY_ACTIVATION_RADIUS = 24;

const TERTIARY_OUTER_RADIUS =
    OUTER_RADIUS + MENU_ITEM_RADIUS;

function preferredAngleToRadians(
    degrees: number
) {
    return (
        (degrees * Math.PI) / 180 -
        Math.PI / 2
    );
}

function normalizeRadians(
    angle: number
) {
    let result = angle;

    while (result <= -Math.PI) {
        result += TWO_PI;
    }

    while (result > Math.PI) {
        result -= TWO_PI;
    }

    return result;
}

function angularDistance(
    a: number,
    b: number
) {
    return Math.abs(
        normalizeRadians(a - b)
    );
}

function assignPreferredItems(
    items: RadialMenuItem[],
    slotAngles: number[]
) {
    const preferred = items.filter(
        item =>
            item.preferredAngle !==
            undefined
    );

    if (!preferred.length) {
        return new Map<string, number>();
    }

    const preferredAngles =
        preferred.map(item => ({
            item,
            angle:
                preferredAngleToRadians(
                    item.preferredAngle!
                ),
        }));

    const assignments =
        new Map<string, number>();

    if (
        preferred.length <= 8 &&
        slotAngles.length <= 12
    ) {
        let bestCost = Infinity;
        let bestAssignment:
            | number[]
            | null = null;

        function search(
            index: number,
            used: Set<number>,
            current: number[],
            cost: number
        ) {
            if (
                index ===
                preferredAngles.length
            ) {
                if (
                    cost <
                    bestCost
                ) {
                    bestCost = cost;
                    bestAssignment =
                        [...current];
                }

                return;
            }

            if (cost >= bestCost) {
                return;
            }

            const target =
                preferredAngles[
                    index
                ].angle;

            for (
                let slot = 0;
                slot <
                slotAngles.length;
                slot++
            ) {
                if (used.has(slot)) {
                    continue;
                }

                const distance =
                    angularDistance(
                        target,
                        slotAngles[slot]
                    );

                used.add(slot);
                current.push(slot);

                search(
                    index + 1,
                    used,
                    current,
                    cost + distance
                );

                current.pop();
                used.delete(slot);
            }
        }

        search(
            0,
            new Set<number>(),
            [],
            0
        );

        if (bestAssignment) {
            preferredAngles.forEach(
                (entry, index) => {
                    assignments.set(
                        entry.item.id,
                        bestAssignment![index]
                    );
                }
            );

            return assignments;
        }
    }

    const remaining =
        new Set(
            slotAngles.map(
                (_, index) => index
            )
        );

    const sorted =
        [...preferredAngles].sort(
            (a, b) => {
                const aBest =
                    Math.min(
                        ...slotAngles.map(
                            angle =>
                                angularDistance(
                                    a.angle,
                                    angle
                                )
                        )
                    );

                const bBest =
                    Math.min(
                        ...slotAngles.map(
                            angle =>
                                angularDistance(
                                    b.angle,
                                    angle
                                )
                        )
                    );

                return (
                    aBest -
                    bBest
                );
            }
        );

    for (const entry of sorted) {
        let bestSlot:
            | number
            | null = null;

        let bestDistance =
            Infinity;

        for (const slot of remaining) {
            const distance =
                angularDistance(
                    entry.angle,
                    slotAngles[slot]
                );

            if (
                distance <
                bestDistance
            ) {
                bestDistance = distance;
                bestSlot = slot;
            }
        }

        if (bestSlot !== null) {
            assignments.set(
                entry.item.id,
                bestSlot
            );

            remaining.delete(
                bestSlot
            );
        }
    }

    return assignments;
}

function calculateSecondaryLayout(
    secondary: RadialMenuItem[]
): SecondaryLayoutItem[] {
    if (!secondary.length) {
        return [];
    }

    const count = secondary.length;

    const sectorAngle =
        TWO_PI / count;

    const baseAngles =
        secondary.map(
            (_, index) =>
                -Math.PI / 2 +
                index * sectorAngle
        );

    const preferred =
        secondary.filter(
            item =>
                item.preferredAngle !==
                undefined
        );

    if (!preferred.length) {
        return secondary.map(
            (item, index) => ({
                item,
                angle: baseAngles[index],
            })
        );
    }

    const candidateRotations =
        new Set<number>();

    candidateRotations.add(0);

    for (const item of preferred) {
        const target =
            preferredAngleToRadians(
                item.preferredAngle!
            );

        for (
            let slot = 0;
            slot < count;
            slot++
        ) {
            candidateRotations.add(
                normalizeRadians(
                    target -
                        baseAngles[slot]
                )
            );
        }
    }

    let bestRotation = 0;
    let bestCost = Infinity;
    let bestAssignment:
        | Map<string, number>
        | null = null;

    for (const rotation of candidateRotations) {
        const slotAngles =
            baseAngles.map(
                angle =>
                    normalizeRadians(
                        angle +
                            rotation
                    )
            );

        const assignment =
            assignPreferredItems(
                secondary,
                slotAngles
            );

        let cost = 0;

        for (const item of preferred) {
            const slot =
                assignment.get(
                    item.id
                );

            if (
                slot ===
                undefined
            ) {
                continue;
            }

            const target =
                preferredAngleToRadians(
                    item.preferredAngle!
                );

            cost +=
                angularDistance(
                    target,
                    slotAngles[slot]
                );
        }

        if (cost < bestCost) {
            bestCost = cost;
            bestRotation = rotation;
            bestAssignment =
                assignment;
        }
    }

    const slotAngles =
        baseAngles.map(
            angle =>
                normalizeRadians(
                    angle +
                        bestRotation
                )
        );

    const result:
        Array<
            SecondaryLayoutItem | null
        > = Array(count).fill(null);

    if (bestAssignment) {
        for (const [
            itemId,
            slot,
        ] of bestAssignment) {
            const item =
                secondary.find(
                    candidate =>
                        candidate.id ===
                        itemId
                );

            if (item) {
                result[slot] = {
                    item,
                    angle:
                        slotAngles[slot],
                };
            }
        }
    }

    const remainingItems =
        secondary.filter(
            item =>
                !bestAssignment?.has(
                    item.id
                )
        );

    const remainingSlots =
        slotAngles
            .map(
                (_, index) => index
            )
            .filter(
                index =>
                    result[index] ===
                    null
            );

    remainingItems.forEach(
        (item, index) => {
            const slot =
                remainingSlots[index];

            result[slot] = {
                item,
                angle:
                    slotAngles[slot],
            };
        }
    );

    return result.filter(
        (
            entry
        ): entry is SecondaryLayoutItem =>
            entry !== null
    );
}

export function createRadialMenu(
    parent: d3.Selection<
        SVGGElement,
        unknown,
        null,
        undefined
    >,
    options: RadialMenuOptions
) {
    let {
        x,
        y,
        center,
        secondary,
        renderIcon,
    } = options;

    let callbacks: RadialMenuCallbacks = {
        onSelect: options.onSelect,
        onToggle: options.onToggle,
        onDragStart: options.onDragStart,
        onDrag: options.onDrag,
        onDragEnd: options.onDragEnd,
    };

    let menuState: MenuState = "idle";

    let activeSecondary:
        | RadialMenuItem
        | null = null;

    let dragState:
        | DragState
        | null = null;

    /*
     * Transient center UI state.
     *
     * This must live outside render(), because render()
     * rebuilds the entire SVG subtree whenever external
     * state changes.
     */
    let centerHovered = false;

    const root =
        parent
            .append("g")
            .attr(
                "class",
                "radial-menu"
            );

    function polarPoint(
        radius: number,
        angle: number
    ) {
        return {
            x:
                x +
                Math.cos(angle) *
                    radius,
            y:
                y +
                Math.sin(angle) *
                    radius,
        };
    }

    function getPointerPosition(
        event: PointerEvent
    ) {
        const svg =
            (
                event
                    .currentTarget as
                    SVGElement
            ).ownerSVGElement;

        if (!svg) {
            return null;
        }

        const matrix =
            svg.getScreenCTM();

        if (!matrix) {
            return null;
        }

        const point =
            new DOMPoint(
                event.clientX,
                event.clientY
            ).matrixTransform(
                matrix.inverse()
            );

        return {
            x: point.x,
            y: point.y,
        };
    }

    function getMenuCenterInSvg() {
        const parentNode =
            parent.node();

        const svg =
            parentNode?.ownerSVGElement;

        const parentMatrix =
            parentNode?.getScreenCTM();

        const svgMatrix =
            svg?.getScreenCTM();

        if (
            !parentMatrix ||
            !svgMatrix
        ) {
            return { x, y };
        }

        const point =
            new DOMPoint(x, y)
                .matrixTransform(
                    parentMatrix
                )
                .matrixTransform(
                    svgMatrix.inverse()
                );

        return {
            x: point.x,
            y: point.y,
        };
    }
    function beginInteraction(
        item: RadialMenuItem,
        event: PointerEvent
    ) {
        if (!item.interactive) {
            return;
        }

        /*
         * The relation-creation handles live inside a draggable
         * graph node. Keep their pointer interaction local so D3
         * moves only the quicklink endpoint. The center remains a
         * node drag handle.
         */
        if (
            item.id ===
                "create-prerequisite" ||
            item.id ===
                "create-consequence"
        ) {
            event.stopPropagation();
            event.preventDefault();
        }

        const pointer =
            getPointerPosition(event);

        if (!pointer) {
            return;
        }

        dragState = {
            item,
            startX: pointer.x,
            startY: pointer.y,
            active: false,
        };

        (
            event.currentTarget as
                Element
        ).setPointerCapture?.(
            event.pointerId
        );
    }

    function updateDrag(
        event: PointerEvent
    ) {
        if (!dragState) {
            return false;
        }

        const pointer =
            getPointerPosition(event);

        if (!pointer) {
            return false;
        }

        const dx =
            pointer.x -
            dragState.startX;

        const dy =
            pointer.y -
            dragState.startY;

        const distance =
            Math.sqrt(
                dx * dx +
                    dy * dy
            );

        if (
            !dragState.active &&
            dragState.item.draggable &&
            distance >=
                DRAG_THRESHOLD
        ) {
            dragState.active = true;

            callbacks.onDragStart?.(
                dragState.item,
                pointer.x,
                pointer.y
            );
        }

        if (dragState.active) {
            callbacks.onDrag?.(
                dragState.item,
                pointer.x,
                pointer.y
            );

            return true;
        }

        return false;
    }

    function endInteraction(
        event: PointerEvent
    ) {
        if (!dragState) {
            return;
        }

        const state = dragState;

        const pointer =
            getPointerPosition(event);

        dragState = null;

        if (state.active) {
            if (pointer) {
                callbacks.onDragEnd?.(
                    state.item,
                    pointer.x,
                    pointer.y
                );
            }

            return;
        }

        if (!state.item.interactive) {
            return;
        }

        if (state.item.toggle) {
            callbacks.onToggle?.(
                state.item,
                !state.item.active
            );

            return;
        }

        callbacks.onSelect(
            state.item
        );
    }

    function getSecondaryAtAngle(
        angle: number,
        layout: SecondaryLayoutItem[]
    ) {
        let bestItem:
            | RadialMenuItem
            | null = null;

        let bestDistance =
            Infinity;

        const sectorAngle =
            TWO_PI /
            Math.max(
                secondary.length,
                1
            );

        for (const entry of layout) {
            const distance =
                angularDistance(
                    angle,
                    entry.angle
                );

            if (
                distance <
                bestDistance
            ) {
                bestDistance =
                    distance;

                bestItem =
                    entry.item;
            }
        }

        if (
            bestDistance >
            sectorAngle / 2
        ) {
            return null;
        }

        return bestItem;
    }

    function getSecondaryAngle(
        item: RadialMenuItem,
        layout: SecondaryLayoutItem[]
    ) {
        return (
            layout.find(
                entry =>
                    entry.item.id ===
                    item.id
            )?.angle ??
            -Math.PI / 2
        );
    }

    function donutPath(
        startAngle: number,
        endAngle: number
    ) {
        const outerStart =
            polarPoint(
                OUTER_RADIUS,
                startAngle
            );

        const outerEnd =
            polarPoint(
                OUTER_RADIUS,
                endAngle
            );

        const innerEnd =
            polarPoint(
                INNER_RADIUS,
                endAngle
            );

        const innerStart =
            polarPoint(
                INNER_RADIUS,
                startAngle
            );

        const largeArc =
            endAngle -
                startAngle >
            Math.PI
                ? 1
                : 0;

        return [
            `M ${outerStart.x} ${outerStart.y}`,
            `A ${OUTER_RADIUS} ${OUTER_RADIUS} 0 ${largeArc} 1 ${outerEnd.x} ${outerEnd.y}`,
            `L ${innerEnd.x} ${innerEnd.y}`,
            `A ${INNER_RADIUS} ${INNER_RADIUS} 0 ${largeArc} 0 ${innerStart.x} ${innerStart.y}`,
            "Z",
        ].join(" ");
    }

    function renderTertiaryMenu(
        parentItem: RadialMenuItem,
        parentAngle: number
    ) {
        const children =
            parentItem.children ?? [];

        if (!children.length) {
            return;
        }

        const tertiaryLayer =
            root
                .append("g")
                .attr(
                    "class",
                    "radial-menu-tertiary"
                );

        const minItemAngle =
            2 *
            Math.asin(
                MENU_ITEM_RADIUS /
                    OUTER_RADIUS
            );

        children.forEach(
            (child, index) => {
                const step =
                    Math.floor(
                        index / 2
                    ) + 1;

                const direction =
                    index % 2 === 0
                        ? -1
                        : 1;

                const angle =
                    parentAngle +
                    direction *
                        step *
                        minItemAngle;

                const position =
                    polarPoint(
                        OUTER_RADIUS,
                        angle
                    );

                const itemGroup =
    tertiaryLayer
        .append("g")
        .attr(
            "class",
            `radial-menu-item radial-menu-item--tertiary${
                child.interactive
                    ? ""
                    : " radial-menu-item--disabled"
            }`
        )
        .attr(
            "transform",
            `translate(${position.x},${position.y})`
        )
        .style(
            "cursor",
            child.interactive
                ? child.draggable
                    ? "grab"
                    : "pointer"
                : "default"
        )
        .style(
            "opacity",
            child.interactive
                ? 1
                : 0.28
        );

                itemGroup
                    .append("circle")
                    .attr(
                        "r",
                        MENU_ITEM_RADIUS +
                            4
                    )
                    .attr(
                        "fill",
                        "transparent"
                    )
                    .style(
                        "pointer-events",
                        "all"
                    );

                itemGroup
                    .append("circle")
                    .attr(
                        "class",
                        child.active
                            ? "radial-menu-button radial-menu-button--active"
                            : "radial-menu-button"
                    )
                    .attr(
                        "r",
                        MENU_ITEM_RADIUS
                    )
                    .style(
                        "pointer-events",
                        "none"
                    );

                                itemGroup
                    .on(
                        "pointerdown",
                        event => {
                            event.stopPropagation();

                            beginInteraction(
                                child,
                                event
                            );
                        }
                    )
                    .on(
                        "pointermove",
                        event => {
                            event.stopPropagation();

                            updateDrag(event);
                        }
                    )
                    .on(
                        "pointerup",
                        event => {
                            event.stopPropagation();

                            endInteraction(event);
                        }
                    )
                    .on(
                        "click",
                        event => {
                            event.stopPropagation();
                        }
                    );

                                    itemGroup
                    .on(
                        "pointerdown",
                        event => {
                            event.stopPropagation();

                            beginInteraction(
                                child,
                                event
                            );
                        }
                    )
                    .on(
                        "pointermove",
                        event => {
                            event.stopPropagation();

                            updateDrag(event);
                        }
                    )
                    .on(
                        "pointerup",
                        event => {
                            event.stopPropagation();

                            endInteraction(event);
                        }
                    )
                    .on(
                        "click",
                        event => {
                            event.stopPropagation();
                        }
                    );

                const iconGroup =
                    itemGroup
                        .append("g")
                        .attr(
                            "transform",
                            "translate(-7,-7)"
                        )
                        .style(
                            "pointer-events",
                            "none"
                        );

                renderIcon(
                    iconGroup,
                    child.active &&
                        child.activeIcon
                        ? child.activeIcon
                        : child.icon,
                    14
                );

                itemGroup
                    .on(
                        "pointerdown",
                        event => {
                            event.stopPropagation();

                            beginInteraction(
                                child,
                                event
                            );
                        }
                    )
                    .on(
                        "pointermove",
                        event => {
                            event.stopPropagation();

                            updateDrag(
                                event
                            );
                        }
                    )
                    .on(
                        "pointerup",
                        event => {
                            event.stopPropagation();

                            endInteraction(
                                event
                            );
                        }
                    );
            }
        );
    }

    function render() {
        root.selectAll("*").remove();

        const layout =
            calculateSecondaryLayout(
                secondary
            );

        const secondaryCount =
            Math.max(
                secondary.length,
                1
            );

        const sectorAngle =
            TWO_PI /
            secondaryCount;

        const minItemAngle =
            2 *
            Math.asin(
                MENU_ITEM_RADIUS /
                    OUTER_RADIUS
            );

        /*
         * Root interaction layer.
         */
        root
            .on(
                "pointermove",
                event => {
                    if (
                        dragState?.active
                    ) {
                        updateDrag(
                            event
                        );
                        return;
                    }

                    const pointer =
                        getPointerPosition(
                            event
                        );

                    if (!pointer) {
                        return;
                    }

                    const center =
                        getMenuCenterInSvg();

                    const dx =
                        pointer.x - center.x;

                    const dy =
                        pointer.y - center.y;

                    const radius =
                        Math.sqrt(
                            dx * dx +
                                dy * dy
                        );

                    const angle =
                        Math.atan2(
                            dy,
                            dx
                        );

                    if (
                        menuState ===
                            "expanded" &&
                        activeSecondary
                    ) {
                        const parentAngle =
                            getSecondaryAngle(
                                activeSecondary,
                                layout
                            );

                        const children =
                            activeSecondary.children ??
                            [];

                        const stepCount =
                            Math.ceil(
                                children.length /
                                    2
                            );

                        const branchHalfAngle =
                            stepCount *
                                minItemAngle +
                            minItemAngle;

                        const angular =
                            Math.abs(
                                normalizeRadians(
                                    angle -
                                        parentAngle
                                )
                            );

                        const insideBranch =
                            radius >= 24 &&
                            radius <=
                                TERTIARY_OUTER_RADIUS +
                                    8 &&
                            angular <=
                                branchHalfAngle;

                        if (
                            insideBranch
                        ) {
                            return;
                        }

                        if (
                            radius <=
                            PROXIMITY_RADIUS
                        ) {
                            menuState =
                                "preview";

                            activeSecondary =
                                null;

                            render();

                            return;
                        }

                        menuState = "idle";
                        activeSecondary =
                            null;

                        render();

                        return;
                    }

                    if (
                        radius >
                        PROXIMITY_RADIUS
                    ) {
                        if (
                            menuState !==
                            "idle"
                        ) {
                            menuState =
                                "idle";

                            activeSecondary =
                                null;

                            render();
                        }

                        return;
                    }

                    if (
                        menuState ===
                        "idle"
                    ) {
                        menuState =
                            "preview";

                        render();
                    }

                    if (
                        menuState ===
                            "preview" &&
                        radius >=
                            SECONDARY_ACTIVATION_RADIUS
                    ) {
                        const item =
                            getSecondaryAtAngle(
                                angle,
                                layout
                            );

                        if (
                            item?.interactive &&
                            (item.children
                                ?.length ??
                                0) > 0
                        ) {
                            activeSecondary =
                                item;

                            menuState =
                                "expanded";

                            render();
                        }
                    }
                }
            )
            .on(
                "pointerup",
                event => {
                    endInteraction(
                        event
                    );
                }
            )
          .on(
    "pointerleave",
    () => {
        if (dragState?.active) {
            return;
        }

        menuState = "idle";
        activeSecondary = null;
        dragState = null;

        render();
    }
);

        /*
         * Proximity hitbox.
         */
        root
            .append("circle")
            .attr("cx", x)
            .attr("cy", y)
            .attr(
                "r",
                PROXIMITY_RADIUS
            )
            .attr(
                "fill",
                "transparent"
            )
            .style(
                "pointer-events",
                "all"
            );

        /*
         * Center interaction.
         */
        const centerGroup =
            root
                .append("g")
                .attr(
                    "class",
                    "radial-menu-center"
                )
                .style(
                    "cursor",
                    center.interactive
                        ? center.draggable
                            ? "grab"
                            : "pointer"
                        : "default"
                );

        centerGroup
            .append("circle")
            .attr("cx", x)
            .attr("cy", y)
            .attr(
                "r",
                PROXIMITY_RADIUS
            )
            .attr(
                "fill",
                "transparent"
            )
            .style(
                "pointer-events",
                "all"
            );

        function renderCenterIcon(
            icon: string
        ) {
            centerGroup
                .selectAll(
                    ".radial-menu-center-icon"
                )
                .remove();

            const centerIcon =
                centerGroup
                    .append("g")
                    .attr(
                        "class",
                        "radial-menu-center-icon"
                    )
                    .attr(
                        "transform",
                        `translate(${x - 10},${y - 10})`
                    )
                    .style(
                        "pointer-events",
                        "none"
                    );

            renderIcon(
                centerIcon,
                icon,
                20
            );
        }

        /*
         * The center icon is visible when either:
         *
         * - the external state says the center is active, or
         * - the pointer is currently hovering the center.
         *
         * centerHovered deliberately survives render(),
         * because render() is also called after external state
         * updates.
         */
        if (
            center.active ||
            centerHovered
        ) {
            renderCenterIcon(
                center.active &&
                    center.activeIcon
                    ? center.activeIcon
                    : center.icon
            );
        }

        centerGroup
            .on(
                "pointerenter",
                () => {
                    centerHovered = true;

                    if (
                        !dragState?.active &&
                        center.interactive
                    ) {
                        renderCenterIcon(
                            center.active &&
                                center.activeIcon
                                ? center.activeIcon
                                : center.icon
                        );
                    }
                }
            )
            .on(
                "pointerleave",
                () => {
                    centerHovered = false;

                    /*
                     * Only remove the icon if the external
                     * active state is also false.
                     */
                    if (
                        !dragState?.active &&
                        !center.active
                    ) {
                        centerGroup
                            .selectAll(
                                ".radial-menu-center-icon"
                            )
                            .remove();
                    }
                }
            )
            .on(
                "pointerdown",
                event => {
                    beginInteraction(
                        center,
                        event
                    );
                }
            )
            .on(
                "pointermove",
                event => {
                    const wasDragging =
                        dragState?.active ??
                        false;

                    const isDragging =
                        updateDrag(event);

                    if (
                        !wasDragging &&
                        isDragging
                    ) {
                        renderCenterIcon(
                            center.draggable
                                ? "move"
                                : center.active
                                  ? center.activeIcon ??
                                    center.icon
                                  : center.icon
                        );

                        centerGroup.style(
                            "cursor",
                            "grabbing"
                        );
                    }
                }
            )
            .on(
                "pointerup",
                event => {
                    const wasDragging =
                        dragState?.active ??
                        false;

                    endInteraction(event);

                    if (!wasDragging) {
                        /*
                         * After a toggle, React may immediately
                         * update center.active and trigger render().
                         * If the current render still has the old
                         * value, do not manufacture an empty icon.
                         */
                        if (
                            center.active ||
                            centerHovered
                        ) {
                            renderCenterIcon(
                                center.active &&
                                    center.activeIcon
                                    ? center.activeIcon
                                    : center.icon
                            );
                        } else {
                            centerGroup
                                .selectAll(
                                    ".radial-menu-center-icon"
                                )
                                .remove();
                        }
                    }

                    centerGroup.style(
                        "cursor",
                        center.interactive
                            ? center.draggable
                                ? "grab"
                                : "pointer"
                            : "default"
                    );
                }
            );

        /*
         * Secondary buttons.
         */
        if (
            menuState !== "idle"
        ) {
            for (const entry of layout) {
                const item =
                    entry.item;

                if (
                    menuState ===
                        "expanded" &&
                    activeSecondary &&
                    item.id !==
                        activeSecondary.id
                ) {
                    continue;
                }

                const middleAngle =
                    entry.angle;

                const startAngle =
                    middleAngle -
                    sectorAngle / 2;

                const endAngle =
                    middleAngle +
                    sectorAngle / 2;

                const position =
                    polarPoint(
                        OUTER_RADIUS,
                        middleAngle
                    );

                const isActive =
                    activeSecondary?.id ===
                    item.id;

               const itemGroup =
    root
        .append("g")
        .attr(
            "class",
            `radial-menu-item radial-menu-item--secondary${
                isActive
                    ? " radial-menu-item--expanded"
                    : ""
            }${
                item.interactive
                    ? ""
                    : " radial-menu-item--disabled"
            }`
        )
        .style(
            "cursor",
            item.interactive
                ? item.draggable
                    ? "grab"
                    : "pointer"
                : "default"
        )
        .style(
            "opacity",
            item.interactive
                ? 1
                : 0.28
        );

                itemGroup
                    .append("path")
                    .attr(
                        "d",
                        donutPath(
                            startAngle,
                            endAngle
                        )
                    )
                    .attr(
                        "fill",
                        "transparent"
                    )
                    .attr(
                        "stroke",
                        "none"
                    )
                    .style(
                        "pointer-events",
                        "none"
                    );

                if (item.icon) {
                    itemGroup
                        .append("circle")
                        .attr(
                            "cx",
                            position.x
                        )
                        .attr(
                            "cy",
                            position.y
                        )
                        .attr(
                            "r",
                            MENU_ITEM_RADIUS +
                                4
                        )
                        .attr(
                            "fill",
                            "transparent"
                        )
                        .style(
                            "pointer-events",
                            "all"
                        );

                    itemGroup
                        .append("circle")
                        .attr(
                            "class",
                            item.active
                                ? "radial-menu-button radial-menu-button--active"
                                : "radial-menu-button"
                        )
                        .attr(
                            "cx",
                            position.x
                        )
                        .attr(
                            "cy",
                            position.y
                        )
                        .attr(
                            "r",
                            MENU_ITEM_RADIUS
                        )
                        .style(
                            "pointer-events",
                            "none"
                        );

                    const iconGroup =
                        itemGroup
                            .append("g")
                            .attr(
                                "transform",
                                `translate(${position.x - 7},${position.y - 7})`
                            )
                            .style(
                                "pointer-events",
                                "none"
                            );

                    renderIcon(
                        iconGroup,
                        item.active &&
                            item.activeIcon
                            ? item.activeIcon
                            : item.icon,
                        14
                    );
                }

                itemGroup
                    .on(
                        "pointerdown",
                        event => {
                            beginInteraction(
                                item,
                                event
                            );
                        }
                    )
                    .on(
                        "pointermove",
                        event => {
                            updateDrag(
                                event
                            );
                        }
                    )
                    .on(
                        "pointerup",
                        event => {
                            endInteraction(
                                event
                            );
                        }
                    );

                if (isActive) {
                    renderTertiaryMenu(
                        item,
                        middleAngle
                    );
                }
            }
        }
    }

    function update(
        nextOptions: Partial<RadialMenuOptions>
    ) {
        if (
            nextOptions.x !==
            undefined
        ) {
            x = nextOptions.x;
        }

        if (
            nextOptions.y !==
            undefined
        ) {
            y = nextOptions.y;
        }

        if (
            nextOptions.center
        ) {
            center =
                nextOptions.center;
        }

        if (
            nextOptions.secondary
        ) {
            secondary =
                nextOptions.secondary;
        }

        callbacks = {
            onSelect:
                nextOptions.onSelect ??
                callbacks.onSelect,

            onToggle:
                nextOptions.onToggle ??
                callbacks.onToggle,

            onDragStart:
                nextOptions.onDragStart ??
                callbacks.onDragStart,

            onDrag:
                nextOptions.onDrag ??
                callbacks.onDrag,

            onDragEnd:
                nextOptions.onDragEnd ??
                callbacks.onDragEnd,
        };

        render();
    }

    function destroy() {
        root.remove();
    }

    render();

    return {
        update,
        destroy,
        selection: root,
    };
}