import type { Selection } from "d3";
import type { TreeNode } from "../../model/types";
import { getCausalNeighborhood } from "../causal";
import {
    getRuntimePlotTree,
} from "../structure";

export interface RelationEditorEdge {
    sourceNode?: {
        node: {
            source: {
                id: string;
            };
        };
    };

    targetNode?: {
        node: {
            source: {
                id: string;
            };
        };
    };
}

export function isLegalRelation(
    root: TreeNode,
    sourceId: string,
    targetId: string
): boolean {
    if (sourceId === targetId) {
        return false;
    }

    /*
     * Kausale relationer findes kun i plottræet.
     * Hvis kaldet kommer fra den sammensatte
     * manus-rode, henter vi derfor runtime-plottet.
     * Modtager vi allerede plotroden, bruges den.
     */
    const plotRoot =
        getRuntimePlotTree(root) ?? root;

    const target = findNode(
        plotRoot,
        targetId
    );

    if (!target) {
        return false;
    }

    if (
        target.prerequisites.includes(
            sourceId
        )
    ) {
        return false;
    }

    const neighborhood =
        getCausalNeighborhood(
            plotRoot,
            sourceId
        );

    /*
     * target → ... → source findes allerede:
     * source → target ville lukke en kausal cyklus.
     */
    return !neighborhood.upstream.has(
        targetId
    );
}

function findNode(
    node: TreeNode,
    id: string
): TreeNode | undefined {
    if (node.id === id) {
        return node;
    }

    for (const child of node.children) {
        const result =
            findNode(child, id);

        if (result) {
            return result;
        }
    }

    return undefined;
}

export function enableRelationSelection<
    GElement extends SVGPathElement,
    Edge extends RelationEditorEdge,
>(
    edgePaths: Selection<
        GElement,
        Edge,
        SVGGElement,
        unknown
    >,
    onSelect: (
        sourceId: string,
        targetId: string
    ) => void
): void {
    edgePaths
        .style(
            "cursor",
            "pointer"
        )
        .on(
            "click",
            (event, edge) => {
                event.stopPropagation();

                const sourceId =
                    edge.sourceNode
                        ?.node.source.id;

                const targetId =
                    edge.targetNode
                        ?.node.source.id;

                if (
                    !sourceId ||
                    !targetId
                ) {
                    return;
                }

                onSelect(
                    sourceId,
                    targetId
                );
            }
        );
}