import * as d3 from "d3";

import {
    edgePath,
} from "./GraphCanvas.helpers";

import type {
    SimulationEdge,
    SimulationNode,
    StoredNodePosition,
} from "./GraphCanvas.helpers";

export function createGraphSimulation(
    simulationNodes: SimulationNode[],
    edges: SimulationEdge[],
    nodeGroups: d3.Selection<
        SVGGElement,
        SimulationNode,
        SVGGElement,
        unknown
    >,
    edgePaths: d3.Selection<
        SVGPathElement,
        SimulationEdge,
        SVGGElement,
        unknown
    >,
    edgeHitPaths: d3.Selection<
        SVGPathElement,
        SimulationEdge,
        SVGGElement,
        unknown
    >,
    availableWidth: number,
    structureChanged: boolean,
    nodePositionsRef: React.MutableRefObject<
        Map<string, StoredNodePosition>
    >,
    onTick?: () => void,
): d3.Simulation<SimulationNode, undefined> {
    /*
     * Kanterne bruges ved rendering, men ikke
     * som en D3-force: forceLink trak ellers
     * uafhængige forløb sammen mod midten.
     */
    void edges;
    void availableWidth;

    return d3
        .forceSimulation(simulationNodes)
        .force(
            "y",
            d3
                .forceY<SimulationNode>(
                    node => node.baseY,
                )
                .strength(0.15),
        )
        .alpha(
            structureChanged
                ? 1
                : 0,
        )
        .alphaDecay(0.025)
        .on("tick", () => {
            for (const node of simulationNodes) {
                if (
                    node.fx === null ||
                    node.fx === undefined
                ) {
                    if (
                        node.node.type ===
                        "aggregate"
                    ) {
                        node.y = node.baseY;
                    } else {
                        node.y = Math.max(
                            node.baseY -
                                node.height * 0.2,
                            Math.min(
                                node.baseY +
                                    node.height * 0.2,
                                node.y,
                            ),
                        );
                    }
                }

                nodePositionsRef.current.set(
                    node.node.id,
                    {
                        x: node.x,
                        y: node.y,
                        layoutX: node.baseX,
                        layoutY: node.baseY,
                    },
                );
            }

            nodeGroups.attr(
                "transform",
                node =>
                    `translate(${node.x},${node.y})`,
            );

            edgePaths.attr(
                "d",
                edgePath,
            );

            edgeHitPaths.attr(
                "d",
                edgePath,
            );

            onTick?.();
        });
}