import {
    useEffect,
    useMemo,
    useRef,
    useState,
} from "react";

import * as d3 from "d3";

import type { TreeNode } from "../model/types";
import type { RadialMenuItem } from "../components/RadialMenuD3";

import { mergeStructure } from "./structure";
import { createPresentationModel } from "./presentation";
import { createLayout } from "./layout";
import { getCombinedCausalNeighborhood } from "./causal";

import {
    createFocusVisibility,
} from "./focus";

import {
    nodeRadius,
    type StoredNodePosition,
} from "./GraphCanvas.helpers";

import {
    createGraphSimulationData,
} from "./GraphSimulationData";

import {
    createGraphSimulation,
} from "./GraphSimulation";

import type { GraphSelection } from "./selection";

import {
    renderGraphEdges,
} from "./GraphEdges";

import {
    createGraphQuicklinks,
} from "./GraphQuicklinks";

import {
    enableGraphNodeDragging,
} from "./GraphNodeDragging";

import {
    renderGraphGroups,
    useGraphGroups,
} from "./GraphGroups";

import {
    renderGraphRadialMenus,
    destroyGraphRadialMenus,
} from "./GraphRadialMenu";

import {
    applyNodeOpacity,
    createNodeGroups,
    enableAggregateSelection,
    renderAggregateCounts,
    renderNodeCircles,
    renderNodeLabels,
    renderNodeSelectionRing,
} from "./GraphNodes";

import {
    createGraphQuickNav,
} from "./GraphQuickNav";

interface GraphCanvasProps {
    plot: TreeNode;
    manuscript: TreeNode;
    activeBookmarkNames: ReadonlySet<string>;
    reloadPlot: () => Promise<void>;

    movePlotNode: (
        nodeId: string,
        parentId: string | null
    ) => void;

            setPlotNodeLayoutPreferences: (
    updates: Array<{
        nodeId: string;
        layoutPreference: {
            horizontalRank?: number;
            verticalRank?: number;
        };
    }>
) => Promise<void>;

    renamePlotNode: (
        nodeId: string,
        label: string
    ) => void;

    createPlotNode: (
        parentId: string,
        sourceId: string,
        direction: "outgoing" | "incoming"
    ) => string;

    persistNewPlotNode: (
        nodeId: string,
        label: string
    ) => Promise<void>;

    cancelPlotNode: (
        nodeId: string
    ) => void;

    addPlotRelation: (
        sourceId: string,
        targetId: string
    ) => void;

    removePlotRelation: (
        sourceId: string,
        targetId: string
    ) => void;

    linkPlotGroup: (
        plotNodeId: string,
        manuscriptNodeId: string
    ) => void;
    
    navigateToParagraph: (
        paraId: string
    ) => void;
    onCreateBookmarkLink: (
        plotNodeId: string
    ) => void;
    onUnlinkBookmark: (
    plotNodeId: string
) => void;
    navigateToBookmark: (
        bookmarkName: string
) => void;
    canDeletePlotNode: (
        nodeId: string
    ) => boolean;

    deletePlotNode: (
        nodeId: string
    ) => Promise<void>;
validBookmarkNames: ReadonlySet<string>;
activeDocumentHeadingId: string | null;
hasTextSelection: boolean;
}

export function GraphCanvas({
    plot,
    manuscript,
    reloadPlot,
       movePlotNode,
    setPlotNodeLayoutPreferences,
    renamePlotNode,
    createPlotNode,
    persistNewPlotNode,
    cancelPlotNode,
    addPlotRelation,
    removePlotRelation,
    linkPlotGroup,
    navigateToParagraph,
    onCreateBookmarkLink,
    onUnlinkBookmark,
    navigateToBookmark,
    hasTextSelection,
    validBookmarkNames,
    activeBookmarkNames,
    activeDocumentHeadingId,
    canDeletePlotNode,
    deletePlotNode,
}: GraphCanvasProps) {
    const structure = useMemo(
    () =>
        mergeStructure(
            plot,
            manuscript
        ),
    [
        plot,
        manuscript,
    ]
);

    const svgRef =
        useRef<SVGSVGElement | null>(null);

    const d3LayerRef =
        useRef<SVGGElement | null>(null);

    const canvasRef =
        useRef<HTMLDivElement>(null);

   const nodePositionsRef =
    useRef<
        Map<string, StoredNodePosition>
    >(new Map());

    const simulationStructureRef =
        useRef<string | null>(null);

    const groups = useGraphGroups();

    const latestLayoutRef =
    useRef<
        ReturnType<typeof createLayout>
        | null
    >(null);

    const revealedDocumentHeadingRef =
    useRef<string | null>(null);

const pendingDocumentHeadingScrollRef =
    useRef<string | null>(null);

   

const [
    focusMode,
    setFocusMode,
] = useState(false);

useEffect(() => {
    if (!activeDocumentHeadingId) {
        revealedDocumentHeadingRef.current = null;
        pendingDocumentHeadingScrollRef.current =
            null;

        return;
    }

    /*
     * En almindelig render — fx fordi en
     * plotknude markeres — må ikke genstarte
     * dokumentfølgningens scroll-request.
     */
    if (
        revealedDocumentHeadingRef.current ===
        activeDocumentHeadingId
    ) {
        return;
    }

    revealedDocumentHeadingRef.current =
        activeDocumentHeadingId;

    pendingDocumentHeadingScrollRef.current =
        activeDocumentHeadingId;

    groups.expandPath(
        structure,
        activeDocumentHeadingId
    );
}, [
    activeDocumentHeadingId,
    groups.expandPath,
    structure,
]);


    const [selection, setSelection] =
        useState<GraphSelection>(null);

    const [editingNodeId, setEditingNodeId] =
        useState<string | null>(null);

    const [canvasWidth, setCanvasWidth] =
        useState(540);

    const [graphHeight, setGraphHeight] =
        useState(540);

    const [
        causalNeighborhoodLocked,
        setCausalNeighborhoodLocked,
    ] = useState(false);

    const [
        causalNeighborhoodLockNodeId,
        setCausalNeighborhoodLockNodeId,
    ] = useState<string | null>(null);

    /*
     * Canvas resize
     */

    useEffect(() => {
        const element =
            canvasRef.current;

        if (!element) {
            return;
        }

        const observer =
            new ResizeObserver(
                entries => {
                    const width =
                        entries[0]
                            ?.contentRect.width;

                    if (width) {
                        setCanvasWidth(width);
                    }
                }
            );

        observer.observe(element);

        return () => {
            observer.disconnect();
        };
    }, []);

    /*
     * Delete selected relation
     */

    useEffect(() => {
        function handleKeyDown(
            event: KeyboardEvent
        ) {
            if (
                event.key !== "Delete" ||
                selection?.type !== "relation"
            ) {
                return;
            }

            removePlotRelation(
                selection.sourceId,
                selection.targetId
            );

            setSelection(null);
        }

        window.addEventListener(
            "keydown",
            handleKeyDown
        );

        return () => {
            window.removeEventListener(
                "keydown",
                handleKeyDown
            );
        };
    }, [
        selection,
        removePlotRelation,
    ]);

    /*
     * Main D3 graph
     */

    useEffect(() => {
        if (
            !svgRef.current ||
            !d3LayerRef.current
        ) {
            return;
        }

        const svg =
            d3.select(svgRef.current);

        const d3Layer =
            d3.select(d3LayerRef.current);

        /*
         * D3 owns only its own layer.
         */

        d3Layer
            .selectAll("*")
            .remove();

        /*
         * Background click
         */

        svg.on(
            "click",
            event => {
                if (
                    event.target !==
                    event.currentTarget
                ) {
                    return;
                }

                setSelection(null);
            }
        );

        /*
         * Presentation
         */

                /*
         * Causal neighborhood
         */    

const selectedRelation =
    selection?.type === "relation"
        ? selection
        : null;

const manualNeighborhoodNodeId =
    causalNeighborhoodLocked
        ? causalNeighborhoodLockNodeId
        : selection?.type === "node"
            ? selection.id
            : null;

/*
 * Fokustilstand følger dokumentets scene,
 * ikke en midlertidig markering med musen.
 */
const documentScenePlotPointIds =
    focusMode
        ? getActiveScenePlotPointIds(
            structure,
            activeDocumentHeadingId
        )
        : new Set<string>();

const documentSceneNeighborhood =
    documentScenePlotPointIds.size > 0
        ? getCombinedCausalNeighborhood(
            structure,
            documentScenePlotPointIds
        )
        : {
            upstream: new Set<string>(),
            downstream: new Set<string>(),
        };

const focusPlotNodeIds =
    new Set<string>([
        ...documentScenePlotPointIds,
        ...documentSceneNeighborhood.upstream,
        ...documentSceneNeighborhood.downstream,
    ]);

const focusVisibility =
    focusMode &&
    focusPlotNodeIds.size > 0
        ? createFocusVisibility(
            structure,
            focusPlotNodeIds,
            activeDocumentHeadingId
        )
        : undefined;

/*
 * En manuel markering styrer fortsat
 * fremhævning og quicknav, men ikke hvilke
 * grupper fokustilstanden viser.
 */
const causalFocusNodeIds =
    manualNeighborhoodNodeId
        ? new Set([
            manualNeighborhoodNodeId,
        ])
        : documentScenePlotPointIds;

const causalNeighborhood =
    causalFocusNodeIds.size > 0
        ? getCombinedCausalNeighborhood(
            structure,
            causalFocusNodeIds
        )
        : {
            upstream: new Set<string>(),
            downstream: new Set<string>(),
        };

const presentation =
    createPresentationModel(
        structure,
        groups.expanded,
        focusVisibility
    );

        const availableWidth =
            Math.max(
                canvasWidth,
                530
            );

        const layout =
            createLayout(
                structure,
                presentation,
                availableWidth
            );

        latestLayoutRef.current = layout;

        setGraphHeight(
            layout.height
        );

        const headingIdToScrollTo =
            pendingDocumentHeadingScrollRef.current;

        if (headingIdToScrollTo) {
            window.requestAnimationFrame(() => {
                window.requestAnimationFrame(() => {
                    const latestLayout =
                        latestLayoutRef.current;

                    const canvas =
                        canvasRef.current;

                    if (!latestLayout || !canvas) {
                        return;
                    }

                    if (
                        pendingDocumentHeadingScrollRef.current !==
                        headingIdToScrollTo
                    ) {
                        return;
                    }

                    const activeGroup =
                        latestLayout.groups.find(
                            group =>
                                group.node.id ===
                                headingIdToScrollTo
                        );

                    const activePresentation =
                        latestLayout.nodes.find(
                            node =>
                                node.node.side ===
                                    "manuscript" &&
                                node.node.source.id ===
                                    headingIdToScrollTo
                        );

                    const targetY =
                        activeGroup
                            ? activeGroup.y + 25
                            : activePresentation?.y;
                   

                    if (targetY === undefined) {
                        return;
                    }

                    pendingDocumentHeadingScrollRef.current =
                        null;

                    const top = Math.max(
                        0,
                        targetY -
                            canvas.clientHeight / 2
                    );

                    canvas.scrollTo({
                        top,
                        behavior: "smooth",
                    });

                    window.requestAnimationFrame(() => {
                       
                    });
                });
            });
        }
        /*
         * Structure key
         */

        const structureKey =
            JSON.stringify({
                nodes: layout.nodes
                    .map(
                        node =>
                            node.node.id
                    )
                    .sort(),

                edges: presentation.edges
                    .map(
                        edge =>
                            `${edge.source}->${edge.target}`
                    )
                    .sort(),
            });

        const structureChanged =
            structureKey !==
            simulationStructureRef.current;

        simulationStructureRef.current =
            structureKey;

        /*
         * Selection
         */



        /*
         * SVG dimensions
         */

        svg
            .attr(
                "viewBox",
                `0 0 ${availableWidth} ${layout.height}`
            )
            .attr(
                "width",
                availableWidth
            )
            .attr(
                "height",
                layout.height
            );

        /*
         * Definitions
         */

        const defs =
            d3Layer.append("defs");

        defs
            .append("marker")
            .attr(
                "id",
                "arrowhead"
            )
            .attr(
                "viewBox",
                "0 -5 10 10"
            )
            .attr(
                "refX",
                9
            )
            .attr(
                "refY",
                0
            )
            .attr(
                "markerWidth",
                7
            )
            .attr(
                "markerHeight",
                7
            )
            .attr(
                "orient",
                "auto"
            )
            .append("path")
            .attr(
                "d",
                "M 0 -5 L 10 0 L 0 5 Z"
            )
            .attr(
                "fill",
                "#777"
            );

        /*
         * Groups
         */

                renderGraphGroups(
    d3Layer,
    layout,
    availableWidth,
    groups,
    linkPlotGroup,
    plotGroupId =>
        linkPlotGroup(
            plotGroupId,
            ""
        ),
    navigateToParagraph,
    activeDocumentHeadingId,
);

        /*
         * Simulation data
         */

        const {
            simulationNodes,
            edges,
        } = createGraphSimulationData(
            layout,
            presentation,
            availableWidth,
            nodePositionsRef.current
        );

        /*
         * Edge layer
         */

        const {
            edgePaths,
            edgeHitPaths,
        } = renderGraphEdges(
            d3Layer,
            edges,
            {
                causalFocusNodeIds,
                causalNeighborhood,
                selectedRelation,
            },
            (
                sourceId,
                targetId
            ) => {
                setSelection({
                    type: "relation",
                    sourceId,
                    targetId,
                });
            }
        );

        /*
         * Node layer
         */

        const quicklinkLayer =
            d3Layer
                .append("g")
                .attr(
                    "class",
                    "quicklinks"
                );

        const nodeGroups =
            createNodeGroups(
                d3Layer,
                simulationNodes
            );

        applyNodeOpacity(
            nodeGroups,
            causalFocusNodeIds,
            causalNeighborhood
        );

          renderNodeCircles(
            nodeGroups,
            nodeRadius,
            validBookmarkNames,
            activeBookmarkNames
        );

        renderNodeSelectionRing(
            nodeGroups,
            nodeRadius,
            manualNeighborhoodNodeId
        );

        renderAggregateCounts(
            nodeGroups
        );

        renderNodeLabels(
            nodeGroups,
            selection,
            editingNodeId,
            setEditingNodeId,
            persistNewPlotNode,
            renamePlotNode,
            cancelPlotNode
        );

        /*
         * Quicklinks
         */

        const quicklinks =
            createGraphQuicklinks(
                structure,
                simulationNodes,
                nodeGroups,
                quicklinkLayer,
                layout,
                manualNeighborhoodNodeId,
                causalNeighborhood,
                {
                    addPlotRelation,
                    createPlotNode,
                    setEditingNodeId,
                }
            );

        /*
         * Radial menus
         */

        const radialMenuInstances =
            renderGraphRadialMenus(
                nodeGroups,
                selection?.type === "node"
                    ? selection
                    : null,
                causalNeighborhoodLocked,
                causalNeighborhoodLockNodeId,
                validBookmarkNames,
                hasTextSelection,
                {
                    getNotionPageUrl,
 canDeletePlotNode,
                    
                    onNavigateBookmark:
                        navigateToBookmark,

                    onSelect:
                        handleRadialMenuSelect,

                    onToggle:
                        handleRadialMenuToggle,

                    onDragStart: (
                        node,
                        item
                    ) => {
                        if (
                            item.id ===
                            "create-prerequisite"
                        ) {
                            quicklinks.start(
                                node,
                                "incoming"
                            );
                        } else if (
                            item.id ===
                            "create-consequence"
                        ) {
                            quicklinks.start(
                                node,
                                "outgoing"
                            );
                        }
                    },

                    onDrag: (
                        item,
                        x,
                        y
                    ) => {
                        if (
                            item.id ===
                                "create-prerequisite" ||
                            item.id ===
                                "create-consequence"
                        ) {
                            quicklinks.drag(
                                x,
                                y
                            );
                        }
                    },

                    onDragEnd: async (
                        item,
                        x,
                        y
                    ) => {
                        if (
                            item.id ===
                                "create-prerequisite" ||
                            item.id ===
                                "create-consequence"
                        ) {
                            await quicklinks.end(
                                x,
                                y
                            );
                        }
                    },
                }
            );

        /*
         * Node selection
         */

        nodeGroups
            .filter(
                node =>
                    node.node.type !==
                    "aggregate"
            )
            .style(
                "cursor",
                "pointer"
            )
            .on(
                "click",
                (event, node) => {
                    event.stopPropagation();

                    setSelection({
                        type: "node",
                        id: node.node.source.id,
                    });
                }
            );

            /*
 * Plot aggregate selection
 */

enableAggregateSelection(
    nodeGroups,
    groups
);

        const canvas = canvasRef.current!;

const quickNav =
    createGraphQuickNav(
        d3Layer,
        canvas,
        edges,
        causalFocusNodeIds,
        causalNeighborhood,
        nodeId =>
    getPlotNodeLabel(
        plot,
        nodeId
    ),
        targetId => {
            groups.expandPath(
                structure,
                targetId
            );

            window.requestAnimationFrame(() => {
                window.requestAnimationFrame(() => {
                    const position =
                        nodePositionsRef.current.get(
                            targetId
                        );

                    if (!position) {
                        return;
                    }

                    canvas.scrollTo({
                        top: Math.max(
                            0,
                            position.y -
                                canvas.clientHeight / 2
                        ),
                        behavior: "smooth",
                    });
                });
            });
        }
    );

        const updateQuickNav = () => {
            quickNav.update();
        };

        canvas.addEventListener(
            "scroll",
            updateQuickNav,
            {
                passive: true,
            }
        );

        quickNav.update();

        /*
         * Simulation
         */

        const simulation =
            createGraphSimulation(
                simulationNodes,
                edges,
                nodeGroups,
                edgePaths,
                edgeHitPaths,
                availableWidth,
                structureChanged,
                nodePositionsRef,
                updateQuickNav
            );

        /*
         * Hierarchical dragging
         */

        enableGraphNodeDragging(
            nodeGroups,
            simulation,
            layout,
            groups,
            {
                movePlotNode,
                setPlotNodeLayoutPreferences,
                reloadPlot,
            }
        );

        /*
         * Cleanup
         */

          return () => {
            canvas.removeEventListener(
                "scroll",
                updateQuickNav
            );

            quickNav.destroy();

            destroyGraphRadialMenus(
                radialMenuInstances
            );

            simulation.stop();

            svg.on(
                "click",
                null
            );
        };
        }, [
        structure,
        groups.expanded,
        selection,
        editingNodeId,
        canvasWidth,
        causalNeighborhoodLocked,
        causalNeighborhoodLockNodeId,
        activeDocumentHeadingId,
        validBookmarkNames,
        activeBookmarkNames,
        navigateToBookmark,
                hasTextSelection,
        onCreateBookmarkLink,
        onUnlinkBookmark,
         canDeletePlotNode,
        deletePlotNode,
        setPlotNodeLayoutPreferences,
        movePlotNode,reloadPlot,
        focusMode
    ]);

    function getNotionPageUrl(
        nodeId: string
    ): string | null {
        const pending = [plot];

        while (pending.length) {
            const node = pending.pop()!;

            if (node.id === nodeId) {
                const url =
                    node.properties?.notionUrl;

                return typeof url === "string"
                    ? url
                    : null;
            }

            pending.push(
                ...node.children
            );
        }

        return null;
    }

    /*
     * Radial menu selection
     */

    function handleRadialMenuSelect(
        nodeId: string,
        item: RadialMenuItem
    ) {
        switch (item.id) {
            case "mark-node":
                setSelection({
                    type: "node",
                    id: nodeId,
                });
                return;

            case "notion": {
                const notionUrl =
                    getNotionPageUrl(nodeId);

                if (notionUrl) {
                    window.open(
                        notionUrl.replace(
                            /^https:/,
                            "notion:"
                        ),
                        "_blank",
                        "noopener,noreferrer"
                    );
                }

                return;
            }

            case "rename-node":
                setEditingNodeId(
                    nodeId
                );
                return;
            case "create-bookmark":
                onCreateBookmarkLink(nodeId);
                return;
            case "text-unlink":
                onUnlinkBookmark(nodeId);
                return;

           case "delete-node":
                setSelection(null);

                if (
                    causalNeighborhoodLockNodeId ===
                    nodeId
                ) {
                    setCausalNeighborhoodLocked(false);

                    setCausalNeighborhoodLockNodeId(
                        null
                    );
                }

                void deletePlotNode(nodeId);
                return;

            default:
                return;
        }
    }

    /*
     * Radial menu toggle
     */

    function handleRadialMenuToggle(
        nodeId: string,
        item: RadialMenuItem,
        active: boolean
    ) {
        if (item.id === "mark-node") {
            if (active) {
                setSelection({
                    type: "node",
                    id: nodeId,
                });
            } else if (
                selection?.type === "node" &&
                selection.id === nodeId
            ) {
                setSelection(null);
            }

            return;
        }

        if (
            item.id !==
            "lock-causal-neighborhood"
        ) {
            return;
        }

        if (active) {
            setSelection({
                type: "node",
                id: nodeId,
            });

            setCausalNeighborhoodLockNodeId(
                nodeId
            );

            setCausalNeighborhoodLocked(
                true
            );

            return;
        }

        setCausalNeighborhoodLocked(
            false
        );

        setCausalNeighborhoodLockNodeId(
            null
        );
    }

    /*
     * SVG
     */

return (
    <div
        ref={canvasRef}
        className="graph-canvas"
        style={{
            position: "relative",
            overflowY: "auto",
            overflowX: "hidden",
            width: "100%",
            height: "100%",
        }}
    >
        <div
            role="toolbar"
            aria-label="PlotGraph-værktøjer"
            style={{
                position: "sticky",
                top: 0,
                zIndex: 2,
                display: "flex",
                alignItems: "center",
                gap: 8,
                padding: "6px 10px",
                borderBottom:
                    "1px solid rgba(0, 0, 0, 0.12)",
                background: "#fff",
            }}
        >
            <button
                type="button"
                aria-pressed={focusMode}
                title={
                    focusMode
                        ? "Slå fokus fra"
                        : "Vis kausalt fokus for den aktuelle scene"
                }
                onClick={() => {
                    setFocusMode(
                        previous => !previous
                    );
                }}
                style={{
                    border: "1px solid #8b8795",
                    borderRadius: 4,
                    padding: "4px 9px",
                    cursor: "pointer",
                    font: "inherit",
                    color: focusMode
                        ? "#fff"
                        : "#514d5c",
                    background: focusMode
                        ? "#514d5c"
                        : "#fff",
                }}
            >
                Fokus
            </button>
        </div>

        <svg
            ref={svgRef}
            role="img"
            aria-label="Askebladet plot graph"
            style={{
                display: "block",
                width: Math.max(
                    canvasWidth,
                    540
                ),
                height: graphHeight,
            }}
        >
            <g ref={d3LayerRef} />
        </svg>
    </div>
);
}

function getActiveScenePlotPointIds(
    manuscriptRoot: TreeNode,
    activeDocumentHeadingId: string | null
): Set<string> {
    if (!activeDocumentHeadingId) {
        return new Set();
    }

    const manuscriptPath =
        findNodePath(
            manuscriptRoot,
            activeDocumentHeadingId
        );

    if (!manuscriptPath) {
        return new Set();
    }

    const linkedScene =
        [...manuscriptPath]
            .reverse()
            .find(
                node =>
                    node.role === "container" &&
                    node.link?.role === "container"
            );

    if (!linkedScene?.link) {
        return new Set();
    }

    const plotPointIds = new Set<string>();

    function collectPlotPoints(
        node: TreeNode
    ): void {
        if (node.role === "node") {
            plotPointIds.add(node.id);
        }

        for (const child of node.children) {
            collectPlotPoints(child);
        }
    }

    collectPlotPoints(linkedScene.link);

    return plotPointIds;
}

function findNodePath(
    node: TreeNode,
    targetId: string
): TreeNode[] | null {
    if (node.id === targetId) {
        return [node];
    }

    for (const child of node.children) {
        const childPath =
            findNodePath(child, targetId);

        if (childPath) {
            return [
                node,
                ...childPath,
            ];
        }
    }

    return null;
}

function getPlotNodeLabel(
    plotRoot: TreeNode,
    nodeId: string
): string | null {
    const pending = [plotRoot];

    while (pending.length > 0) {
        const node = pending.pop()!;

        if (node.id === nodeId) {
            return node.label;
        }

        pending.push(...node.children);
    }

    return null;
}