
import type { TreeNode } from "../model/types";

import type {
    OmittedInterval,
    PresentationModel,
    PresentationNode,
    PresentationEdge
} from "./presentation";

import {
    getOriginalPlotTree,
    getRuntimePlotTree,
} from "./structure";

const TOP = 25;
const BOTTOM = 25;
const GAP = 12;
const HEADER_GAP = 6;
const NODE_HEIGHT = 50;
const NODE_GAP = 12;
const INDENT = 15;
const GROUP_LABEL_OFFSET = 25;
const GROUP_HEADER_HEIGHT = 22;
const OMISSION_HEIGHT = 24;

type Side = "manuscript" | "plot";

export interface LayoutNode {
    node: PresentationNode;
    x: number;
    y: number;
    width: number;
    height: number;
    depth: number;
}

export interface LayoutGroup {
    node: TreeNode;
    side: Side;
    x: number;
    y: number;
    width: number;
    height: number;
    depth: number;
    showFrame: boolean;
}

export interface LayoutOmission {
    id: string;
    side: Side;
    y: number;
    height: number;
    rowStart: number;
    rowEnd: number;
    depth: number;
}

export interface LayoutTreeNode {
    node: TreeNode;
    depth: number;
    side: Side;
}

export interface Layout {
    nodes: LayoutNode[];
    groups: LayoutGroup[];
    tree: LayoutTreeNode[];
    omissions: LayoutOmission[];
    width: number;
    height: number;
}

interface PreparedNode {
    node: PresentationNode;
    x: number;
    width: number;
    depth: number;
}

interface GroupHeader {
    kind: "header";
    id: string;
    node: TreeNode;
    side: Side;
    x: number;
    width: number;
    depth: number;
    rowStart: number;
    rowEnd: number;
    preferredRow: number;
    descendantIds: Set<string>;
}

interface NodeItem {
    kind: "node";
    id: string;
    side: Side;
    x: number;
    width: number;
    rowStart: number;
    rowEnd: number;
    preferredRow: number;
    prepared: PreparedNode;
}

interface OmissionItem {
    kind: "omission";
    id: string;
    side: Side;
    x: number;
    width: number;
    rowStart: number;
    rowEnd: number;
    preferredRow: number;
    depth: number;
}

type LayoutItem =
    | NodeItem
    | GroupHeader
    | OmissionItem;

interface LayoutUnit {
    items: LayoutItem[];
    rowStart: number;
    rowEnd: number;
    preferredRow: number;
    height: number;
}

export function createLayout(
    root: TreeNode,
    presentation: PresentationModel,
    availableWidth: number
): Layout {
    const originalPlot =
        getOriginalPlotTree(root);

    const runtimePlot =
        getRuntimePlotTree(root);

    if (!originalPlot || !runtimePlot) {
        throw new Error(
            "PlottrÃ¦ mangler. KontrollÃ©r mergeStructure()."
        );
    }

    const canonicalHorizontalRanks =
        createCanonicalHorizontalRanks(
            runtimePlot
        );

    const manuscriptById =
        indexTree(root);

    const plotById =
        indexTree(runtimePlot);

    const manuscriptDepth =
        indexDepth(root);

    const plotDepth =
        indexDepth(originalPlot);

    const visibleByKey =
        new Map<string, PresentationNode>();

    for (const node of presentation.nodes) {
        visibleByKey.set(
            key(node.side, node.id),
            node
        );
    }

    const prepared =
        presentation.nodes.map(node => {
            const source =
                node.side === "manuscript"
                    ? manuscriptById.get(node.id)
                    : plotById.get(node.id);

            const resolved: PresentationNode = {
                ...node,
                source: source ?? node.source,
            };

            const depth =
                resolved.side === "manuscript"
                    ? manuscriptDepth.get(
                        resolved.id
                    ) ?? 0
                    : plotDepth.get(
                        resolved.id
                    ) ?? 0;

            const width =
                estimateWidth(resolved.source);

            return {
                node: resolved,
                x:
                    resolved.side === "manuscript"
                        ? depth * INDENT
                        : Math.max(
                            0,
                            availableWidth -
                                width -
                                depth * INDENT
                        ),
                width,
                depth,
            };
        });

    distributeLocalPlotRows(
        prepared,
        presentation.edges,
        availableWidth,
        canonicalHorizontalRanks
    );
    /*
     * Udfoldede grupper bliver layout-only headers.
     * De optager et track fÃ¸r deres descendants,
     * men de renderes som group-labels, ikke bokse.
     */
    const headers = [
    ...createGroupHeaders(
        root,
        "manuscript",
        manuscriptById,
        manuscriptDepth,
        visibleByKey,
        presentation.visibleGroupKeys,
        availableWidth
    ),
    ...createGroupHeaders(
        originalPlot,
        "plot",
        plotById,
        plotDepth,
        visibleByKey,
        presentation.visibleGroupKeys,
        availableWidth
    ),
];

   const units = [
    ...createNodeUnits(prepared),
    ...createHeaderUnits(headers),
    ...createOmissionUnits(
        presentation.omittedIntervals,
        availableWidth
    ),
].sort(compareUnits);

    const visualTrackByUnit =
        placeUnits(units);

    const trackYByIndex =
    createTrackYByIndex(
        units,
        visualTrackByUnit
    );

    const headerTrackByKey =
        new Map<string, number>();
    
    const omissions: LayoutOmission[] = [];
    
    const nodes: LayoutNode[] = [];

    for (const unit of units) {
        const track =
            visualTrackByUnit.get(unit)!;

        const y =
    trackYByIndex.get(track)!;

        for (const item of unit.items) {
            if (item.kind === "omission") {
               omissions.push({
    id: item.id,
    side: item.side,
    y,
    height: OMISSION_HEIGHT,
    rowStart: item.rowStart,
    rowEnd: item.rowEnd,
    depth: item.depth,
});

                continue;
}

            if (item.kind === "header") {
                headerTrackByKey.set(
                    key(item.side, item.id),
                    track
                );

                continue;
            }

            const member = item.prepared;

            nodes.push({
                node: member.node,
                x: member.x,
                y,
                width: member.width,
                height: NODE_HEIGHT,
                depth: member.depth,
            });
        }
    }

    nodes.sort((left, right) => {
        if (left.y !== right.y) {
            return left.y - right.y;
        }

        if (
            left.node.side !==
            right.node.side
        ) {
            return left.node.side ===
                "manuscript"
                ? -1
                : 1;
        }

        return left.node.id.localeCompare(
            right.node.id
        );
    });

    const layoutByKey =
        new Map<string, LayoutNode>();

    for (const node of nodes) {
        layoutByKey.set(
            key(
                node.node.side,
                node.node.id
            ),
            node
        );
    }

    const groups: LayoutGroup[] = [];
    const tree: LayoutTreeNode[] = [];

  addGroups(
    root,
    "manuscript",
    manuscriptById,
    layoutByKey,
    visibleByKey,
    presentation.visibleGroupKeys,
    headerTrackByKey,
    trackYByIndex,
    groups,
    tree,
    availableWidth
);

addGroups(
    originalPlot,
    "plot",
    plotById,
    layoutByKey,
    visibleByKey,
    presentation.visibleGroupKeys,
    headerTrackByKey,
    trackYByIndex,
    groups,
    tree,
    availableWidth
);

    const bottom =
    Math.max(
        ...nodes.map(
            node =>
                node.y +
                NODE_HEIGHT / 2
        ),
        ...omissions.map(
            omission =>
                omission.y +
                omission.height / 2
        ),
        ...[...headerTrackByKey.values()].map(
            track =>
                trackYByIndex.get(track) ?? TOP
        ),
        TOP
    );

 return {
    nodes,
    groups,
    tree,
    omissions,
    width: availableWidth,
    height: bottom + BOTTOM,
};
}

function createNodeUnits(
    prepared: PreparedNode[]
): LayoutUnit[] {
    const union = new UnionFind(prepared.length);

    const indexByKey =
        new Map<string, number>();

    prepared.forEach((item, index) => {
        indexByKey.set(
            key(
                item.node.side,
                item.node.id
            ),
            index
        );
    });

    prepared.forEach((item, index) => {
        const linked = item.node.source.link;

        if (!linked) return;

        const otherSide =
            item.node.side === "manuscript"
                ? "plot"
                : "manuscript";

        const linkedIndex =
            indexByKey.get(
                key(otherSide, linked.id)
            );

        if (linkedIndex !== undefined) {
            union.join(index, linkedIndex);
        }
    });

    const itemsByRoot =
        new Map<number, LayoutItem[]>();

    prepared.forEach((item, index) => {
        const root = union.find(index);

        const items =
            itemsByRoot.get(root) ?? [];

        items.push({
            kind: "node",
            id: item.node.id,
            side: item.node.side,
            x: item.x,
            width: item.width,
            rowStart: item.node.rowStart,
            rowEnd: item.node.rowEnd,
            preferredRow:
                item.node.preferredRow,
            prepared: item,
        });

        itemsByRoot.set(root, items);
    });

    return [...itemsByRoot.values()].map(
        makeUnit
    );
}

function createOmissionUnits(
    intervals: OmittedInterval[],
    availableWidth: number
): LayoutUnit[] {
    return intervals.map(interval =>
        makeUnit([
            {
                kind: "omission",
                id: interval.id,
                side: interval.side,
                x: 0,
                width: availableWidth,
                rowStart: interval.rowStart,
                rowEnd: interval.rowEnd,
                preferredRow: interval.rowStart,
                depth: interval.depth,
                
            },
        ])
    );
}

function createHeaderUnits(
    headers: GroupHeader[]
): LayoutUnit[] {
    const headerByKey =
        new Map<string, GroupHeader>();

    for (const header of headers) {
        headerByKey.set(
            key(header.side, header.id),
            header
        );
    }

    const visited = new Set<string>();
    const units: LayoutUnit[] = [];

    for (const header of headers) {
        const ownKey = key(
            header.side,
            header.id
        );

        if (visited.has(ownKey)) {
            continue;
        }

        visited.add(ownKey);

        const linked = header.node.link;

        const otherSide =
            header.side === "manuscript"
                ? "plot"
                : "manuscript";

        const partner = linked
            ? headerByKey.get(
                key(otherSide, linked.id)
            )
            : undefined;

        if (partner) {
            visited.add(
                key(partner.side, partner.id)
            );

            units.push(
                makeUnit([header, partner])
            );
        } else {
            units.push(makeUnit([header]));
        }
    }

    return units;
}

function createGroupHeaders(
    root: TreeNode,
    side: Side,
    runtimeById: Map<string, TreeNode>,
    depthById: Map<string, number>,
    visibleByKey: Map<string, PresentationNode>,
    visibleGroupKeys: ReadonlySet<string>,
    availableWidth: number
): GroupHeader[] {
    const headers: GroupHeader[] = [];

    function visit(original: TreeNode): void {
        const runtime =
            runtimeById.get(original.id) ??
            original;

        const presentation =
            visibleByKey.get(
                key(side, original.id)
            );

        const collapsed =
            presentation?.type === "aggregate";

            if (
    runtime.role === "container" &&
    !visibleGroupKeys.has(
        key(side, runtime.id)
    )
) {
    return;
}

        if (
            runtime.role === "container" &&
            !collapsed
        ) {
            const depth =
                depthById.get(runtime.id) ?? 0;

            const width =
                estimateWidth(runtime);

            const row = runtime.row ?? 0;

            headers.push({
                kind: "header",
                id: runtime.id,
                node: runtime,
                side,
                x:
                    side === "manuscript"
                        ? depth * INDENT
                        : Math.max(
                            0,
                            availableWidth -
                                width -
                                depth * INDENT
                        ),
                width,
                depth,
                rowStart: row,
                rowEnd: row,
                preferredRow: row,
                descendantIds: descendantIds(
                    original
                ),
            });
        }

        if (collapsed) {
            return;
        }

        for (const child of original.children) {
            visit(child);
        }
    }

    visit(root);
    return headers;
}

function descendantIds(
    node: TreeNode
): Set<string> {
    const result = new Set<string>();

    function visit(current: TreeNode): void {
        for (const child of current.children) {
            result.add(child.id);
            visit(child);
        }
    }

    visit(node);

    return result;
}

function makeUnit(
    items: LayoutItem[]
): LayoutUnit {
    const rowStart = Math.max(
        ...items.map(item => item.rowStart)
    );

    const rowEnd = Math.min(
        ...items.map(item => item.rowEnd)
    );

    if (rowStart > rowEnd) {
        throw new Error(
            `Linkede layout-elementer har intet ` +
            `fÃ¦lles rÃ¦kkeinterval: ${unitKey({
                items,
                rowStart,
                rowEnd,
                preferredRow: rowStart,
                height: Math.max(
    ...items.map(layoutItemHeight)
),
            })}`
        );
    }

   return {
    items,
    rowStart,
    rowEnd,
    preferredRow: Math.min(
        rowEnd,
        Math.max(
            rowStart,
            ...items.map(
                item => item.preferredRow
            )
        )
    ),
    height: Math.max(
        ...items.map(layoutItemHeight)
    ),
};
}

function compareUnits(
    left: LayoutUnit,
    right: LayoutUnit
): number {
    if (left.rowStart !== right.rowStart) {
        return left.rowStart - right.rowStart;
    }

    if (
        left.preferredRow !==
        right.preferredRow
    ) {
        return (
            left.preferredRow -
            right.preferredRow
        );
    }

    return unitKey(left).localeCompare(
        unitKey(right)
    );
}

function placeUnits(
    units: LayoutUnit[]
): Map<LayoutUnit, number> {
    interface VisualTrack {
        semanticRow: number;
        contents: LayoutItem[];
    }

    const predecessors =
        new Map<LayoutUnit, Set<LayoutUnit>>();

    const successors =
        new Map<LayoutUnit, Set<LayoutUnit>>();

    for (const unit of units) {
        predecessors.set(unit, new Set());
        successors.set(unit, new Set());
    }

    for (const before of units) {
        for (const after of units) {
            if (
                before === after ||
                !mustFollow(before, after)
            ) {
                continue;
            }

            successors.get(before)!.add(after);
            predecessors.get(after)!.add(before);
        }
    }

    const ordered = topologicalUnits(
        units,
        predecessors,
        successors
    );

    const semanticRows = [
        ...new Set(
            units.flatMap(unit => [
                unit.rowStart,
                unit.preferredRow,
                unit.rowEnd,
            ])
        ),
    ].sort((left, right) => left - right);

    const tracks: VisualTrack[] = [];

    const trackByUnit =
        new Map<LayoutUnit, VisualTrack>();

    function trackIndex(
        track: VisualTrack
    ): number {
        return tracks.indexOf(track);
    }

    function insertIndexForRow(
        semanticRow: number
    ): number {
        let index = 0;

        while (
            index < tracks.length &&
            tracks[index].semanticRow <= semanticRow
        ) {
            index++;
        }

        return index;
    }

    function allowedRows(
        unit: LayoutUnit
    ): number[] {
        const rows = semanticRows.filter(
            row =>
                row >= unit.rowStart &&
                row <= unit.rowEnd
        );

        return rows.sort((left, right) => {
            const leftDistance =
                Math.abs(
                    left - unit.preferredRow
                );

            const rightDistance =
                Math.abs(
                    right - unit.preferredRow
                );

            return (
                leftDistance - rightDistance ||
                left - right
            );
        });
    }

    for (const unit of ordered) {
        const minimumTrackIndex =
            Math.max(
                -1,
                ...[
                    ...(
                        predecessors.get(unit) ??
                        []
                    ),
                ].map(predecessor => {
                    const predecessorTrack =
                        trackByUnit.get(predecessor);

                    return predecessorTrack
                        ? trackIndex(predecessorTrack)
                        : -1;
                })
            ) + 1;

        let selectedTrack:
            | VisualTrack
            | undefined;

        for (const track of tracks) {
            if (
                track.semanticRow < unit.rowStart ||
                track.semanticRow > unit.rowEnd ||
                trackIndex(track) <
                    minimumTrackIndex ||
                !fitsTrack(
                    unit,
                    track.contents
                )
            ) {
                continue;
            }

            selectedTrack = track;
            break;
        }

        if (selectedTrack) {
            selectedTrack.contents.push(
                ...unit.items
            );

            trackByUnit.set(
                unit,
                selectedTrack
            );

            continue;
        }

        const row = allowedRows(unit).find(
            candidateRow =>
                insertIndexForRow(candidateRow) >=
                minimumTrackIndex
        );

        if (row === undefined) {
            throw new Error(
                `Kan ikke placere ${unitKey(unit)} ` +
                `inden for [${unit.rowStart}, ` +
                `${unit.rowEnd}] efter sine forfÃ¦dre.`
            );
        }

        const newTrack: VisualTrack = {
            semanticRow: row,
            contents: [...unit.items],
        };

        tracks.splice(
            insertIndexForRow(row),
            0,
            newTrack
        );

        trackByUnit.set(unit, newTrack);
    }

    const result =
        new Map<LayoutUnit, number>();

    for (const [
        unit,
        track,
    ] of trackByUnit) {
        result.set(
            unit,
            trackIndex(track)
        );
    }

    return result;
}

function topologicalUnits(
    units: LayoutUnit[],
    predecessors: Map<
        LayoutUnit,
        Set<LayoutUnit>
    >,
    successors: Map<
        LayoutUnit,
        Set<LayoutUnit>
    >
): LayoutUnit[] {
    const incoming =
        new Map<LayoutUnit, number>();

    for (const unit of units) {
        incoming.set(
            unit,
            predecessors.get(unit)!.size
        );
    }

    const ready = units.filter(
        unit => incoming.get(unit) === 0
    );

    const result: LayoutUnit[] = [];

    while (ready.length) {
        ready.sort(compareUnits);

        const next = ready.shift()!;

        result.push(next);

        for (
            const successor of
            successors.get(next)!
        ) {
            const count =
                incoming.get(successor)! - 1;

            incoming.set(successor, count);

            if (count === 0) {
                ready.push(successor);
            }
        }
    }

    if (result.length !== units.length) {
        throw new Error(
            "Layoutconstraints indeholder en cyklus."
        );
    }

    return result;
}

function mustFollow(
    before: LayoutUnit,
    after: LayoutUnit
): boolean {
    /*
     * En udfoldet gruppeheader skal altid ligge
     * fÃ¸r bÃ¥de nested gruppeheaders og synlige
     * descendants pÃ¥ samme side.
     */
    for (const item of before.items) {
        if (item.kind !== "header") {
            continue;
        }

        for (const candidate of after.items) {
            if (
                candidate.side === item.side &&
                item.descendantIds.has(
                    candidate.id
                )
            ) {
                return true;
            }
        }
    }

    /*
     * UafhÃ¦ngige ting med disjunkte semantiske
     * intervaller beholder deres rÃ¦kkefÃ¸lge.
     */
    if (before.rowEnd >= after.rowStart) {
        return false;
    }

    return before.items.some(left =>
        after.items.some(
            right =>
                left.side === right.side
        )
    );
}

function fitsTrack(
    unit: LayoutUnit,
    contents: LayoutItem[]
): boolean {
    return unit.items.every(candidate =>
        contents.every(existing => {
            if (
                candidate.side !==
                existing.side
            ) {
                return true;
            }

            return !overlapsHorizontally(
                candidate,
                existing
            );
        })
    );
}

function overlapsHorizontally(
    left: LayoutItem,
    right: LayoutItem
): boolean {
    return (
        left.x <
            right.x +
                right.width +
                NODE_GAP &&
        right.x <
            left.x +
                left.width +
                NODE_GAP
    );
}

function addGroups(
    original: TreeNode,
    side: Side,
    runtimeById: Map<string, TreeNode>,
    layoutByKey: Map<string, LayoutNode>,
    visibleByKey: Map<string, PresentationNode>,
    visibleGroupKeys: ReadonlySet<string>,
    headerTrackByKey: Map<string, number>,
    trackYByIndex: ReadonlyMap<number, number>,
    groups: LayoutGroup[],
    tree: LayoutTreeNode[],
    availableWidth: number,
    depth = 0
): void {
    const runtime =
        runtimeById.get(original.id) ??
        original;

    if (
        runtime.role === "container" &&
        !visibleGroupKeys.has(
            key(side, runtime.id)
        )
    ) {
        return;
    }

    const ownPresentation =
        visibleByKey.get(
            key(side, original.id)
        );

    const collapsed =
        ownPresentation?.type === "aggregate";

    if (runtime.role === "container") {
        tree.push({
            node: runtime,
            depth,
            side,
        });
    }

    if (
        runtime.role === "container" &&
        !collapsed
    ) {
        const descendants =
            collectDescendantLayouts(
                original,
                side,
                layoutByKey
            );

        const headerTrack =
            headerTrackByKey.get(
                key(side, original.id)
            );

        if (headerTrack !== undefined) {
            const headerY =
                trackYByIndex.get(
                    headerTrack
                )!;

            const bottom =
                descendants.length > 0
                    ? Math.max(
                        ...descendants.map(
                            node =>
                                node.y +
                                NODE_HEIGHT / 2
                        )
                    )
                    : headerY +
                        GROUP_HEADER_HEIGHT / 2;

            const hasDirectNodes =
                original.children.some(
                    child =>
                        layoutByKey.has(
                            key(side, child.id)
                        )
                );

            groups.push({
                node: runtime,
                side,
                x: 0,
                y:
                    headerY -
                    GROUP_LABEL_OFFSET,
                width: availableWidth,
                height:
                    bottom -
                    (
                        headerY -
                        GROUP_LABEL_OFFSET
                    ) +
                    BOTTOM,
                depth,
                showFrame:
                    descendants.length > 0 &&
                    hasDirectNodes,
            });
        }
    }

    if (collapsed) {
        return;
    }

    for (const child of original.children) {
        addGroups(
            child,
            side,
            runtimeById,
            layoutByKey,
            visibleByKey,
            visibleGroupKeys,
            headerTrackByKey,
            trackYByIndex,
            groups,
            tree,
            availableWidth,
            depth + 1
        );
    }
}

function collectDescendantLayouts(
    node: TreeNode,
    side: Side,
    layoutByKey: Map<string, LayoutNode>
): LayoutNode[] {
    const result: LayoutNode[] = [];

    function visit(current: TreeNode): void {
        const layout = layoutByKey.get(
            key(side, current.id)
        );

        if (layout) {
            result.push(layout);
        }

        for (const child of current.children) {
            visit(child);
        }
    }

    for (const child of node.children) {
        visit(child);
    }

    return result;
}

function createTrackYByIndex(
    units: LayoutUnit[],
    trackByUnit: ReadonlyMap<
        LayoutUnit,
        number
    >
): Map<number, number> {
    const heightByTrack =
        new Map<number, number>();

    const gapByTrack =
        new Map<number, number>();

    for (const unit of units) {
        const track =
            trackByUnit.get(unit)!;

        heightByTrack.set(
            track,
            Math.max(
                heightByTrack.get(track) ?? 0,
                unit.height
            )
        );

        const containsOnlyHeaders =
            unit.items.every(
                item => item.kind === "header"
            );

        const gap =
            containsOnlyHeaders
                ? HEADER_GAP
                : GAP;

        gapByTrack.set(
            track,
            Math.max(
                gapByTrack.get(track) ?? 0,
                gap
            )
        );
    }

    const yByTrack =
        new Map<number, number>();

    let cursor = TOP;

    for (
        const track of [
            ...heightByTrack.keys(),
        ].sort(
            (left, right) => left - right
        )
    ) {
        const height =
            heightByTrack.get(track)!;

        yByTrack.set(
            track,
            cursor + height / 2
        );

        cursor +=
            height +
            (gapByTrack.get(track) ?? GAP);
    }

    return yByTrack;
}

function indexTree(
    root: TreeNode
): Map<string, TreeNode> {
    const result =
        new Map<string, TreeNode>();

    function visit(node: TreeNode): void {
        result.set(node.id, node);

        for (const child of node.children) {
            visit(child);
        }
    }

    visit(root);

    return result;
}

function indexDepth(
    root: TreeNode
): Map<string, number> {
    const result =
        new Map<string, number>();

    function visit(
        node: TreeNode,
        depth: number
    ): void {
        result.set(node.id, depth);

        for (const child of node.children) {
            visit(child, depth + 1);
        }
    }

    visit(root, 0);

    return result;
}

function key(
    side: Side,
    id: string
): string {
    return `${side}:${id}`;
}

function unitKey(
    unit: LayoutUnit
): string {
    return unit.items
        .map(
            item =>
                `${item.kind}:${item.side}:${item.id}`
        )
        .sort()
        .join("|");
}

function createCanonicalHorizontalRanks(
    plotRoot: TreeNode
): Map<string, number> {
    const ranks = new Map<string, number>();

    function visitScene(
        scene: TreeNode
    ): void {
        const directNodes =
            scene.children.filter(
                child =>
                    child.role === "node"
            );

        directNodes.forEach(
            (node, index) => {
                ranks.set(
                    node.id,
                    (index + 1) /
                        (
                            directNodes.length +
                            1
                        )
                );
            }
        );

        for (const child of scene.children) {
            if (child.role === "container") {
                visitScene(child);
            }
        }
    }

    visitScene(plotRoot);

    return ranks;
}
function estimateWidth(
    node: TreeNode
): number {
    return Math.max(
        40,
        node.label.length * 7 + 30
    );
}

class UnionFind {
    private readonly parent: number[];

    constructor(size: number) {
        this.parent = Array.from(
            { length: size },
            (_, index) => index
        );
    }

    find(index: number): number {
        const parent = this.parent[index];

        if (parent === index) {
            return index;
        }

        const root = this.find(parent);

        this.parent[index] = root;

        return root;
    }

    join(left: number, right: number): void {
        const leftRoot = this.find(left);
        const rightRoot = this.find(right);

        if (leftRoot !== rightRoot) {
            this.parent[rightRoot] = leftRoot;
        }
    }
}

function layoutItemHeight(
    item: LayoutItem
): number {
    switch (item.kind) {
        case "node":
            return NODE_HEIGHT;

        case "header":
            return GROUP_HEADER_HEIGHT;

        case "omission":
            return OMISSION_HEIGHT;
    }
}

function distributeLocalPlotRows(
    prepared: PreparedNode[],
    edges: PresentationEdge[],
    availableWidth: number,
    canonicalHorizontalRanks: ReadonlyMap<
        string,
        number
    >
): void {
    const plotNodes = prepared.filter(
        item =>
            item.node.side === "plot" &&
            item.node.type === "node" &&
            item.node.localSceneId !== undefined
    );

    const byId = new Map(
        plotNodes.map(item => [
            item.node.id,
            item,
        ])
    );

    const localNeighbours =
        new Map<string, Set<string>>();

    const externalNeighbours =
        new Map<string, Set<string>>();

    for (const item of plotNodes) {
        localNeighbours.set(
            item.node.id,
            new Set()
        );

        externalNeighbours.set(
            item.node.id,
            new Set()
        );
    }

    for (const edge of edges) {
        const source = byId.get(edge.source);
        const target = byId.get(edge.target);

        if (!source || !target) {
            continue;
        }

        const neighbours =
            source.node.localSceneId ===
            target.node.localSceneId
                ? localNeighbours
                : externalNeighbours;

        neighbours
            .get(source.node.id)!
            .add(target.node.id);

        neighbours
            .get(target.node.id)!
            .add(source.node.id);
    }

    const rows = new Map<
        string,
        PreparedNode[]
    >();

    for (const item of plotNodes) {
        const rowKey =
            `${item.node.localSceneId}:` +
            `${item.node.rowStart}`;

        const items = rows.get(rowKey) ?? [];

        items.push(item);
        rows.set(rowKey, items);
    }

    const orderedRows = [
        ...rows.values(),
    ].sort(
        (left, right) =>
            left[0].node.rowStart -
            right[0].node.rowStart
    );

    function requestedHorizontalRank(
        item: PreparedNode
    ): number {
        

        return (
            item.node.source
                .layoutPreference?.horizontalRank ??
            canonicalHorizontalRanks.get(
                item.node.id
            ) ??
            0.5
        );
    }
    function hasExplicitHorizontalRank(
        item: PreparedNode
    ): boolean {
        return (
            item.node.source
                .layoutPreference?.horizontalRank !==
            undefined
        );
    }

    function compareHorizontalRank(
        left: PreparedNode,
        right: PreparedNode
    ): number {
        const difference =
            requestedHorizontalRank(left) -
            requestedHorizontalRank(right);

        return Math.abs(difference) < 0.0001
            ? left.node.id.localeCompare(
                right.node.id
            )
            : difference;
    }

   function distribute(
    items: PreparedNode[]
): void {
    const gap = 24;
    const left = 28;
    const right = availableWidth - 28;

    function desiredX(
        item: PreparedNode
    ): number {
       return (
    left +
    requestedHorizontalRank(item) *
        (right - left)
);
    }

    const positions: number[] =
        items.map(desiredX);

    const anchorIndexes = items
        .map(
            (item, index) =>
                hasExplicitHorizontalRank(item)
                    ? index
                    : -1
        )
        .filter(index => index >= 0);

    /*
 * Eksplicitte brugerankre må ikke flyttes.
 *
 * Hvis de overlapper, må den øvrige layoutfase
 * skabe ekstra lodrette tracks; den må ikke
 * ændre den gemte horisontale rang.
 */
    

    function placeAutomaticSegment(
        startIndex: number,
        endIndex: number,
        leftBound: number,
        rightBound: number
    ): void {
        if (startIndex > endIndex) {
            return;
        }

        /*
         * FremadgÃ¥ende passering: hver automatisk
         * node respekterer bÃ¥de sin Ã¸nskede rank
         * og den foregÃ¥ende nodes label.
         */
        let cursor = leftBound;

        for (
            let index = startIndex;
            index <= endIndex;
            index++
        ) {
            const item = items[index];

            positions[index] = Math.max(
                desiredX(item),
                cursor
            );

            cursor =
                positions[index] +
                item.width +
                gap;
        }

        /*
         * BagudgÃ¥ende passering: pressÃ©r kun de
         * automatiske noder tilbage ind mod nÃ¦ste
         * anker. Ankret selv flyttes aldrig her.
         */
        cursor = rightBound;

        for (
            let index = endIndex;
            index >= startIndex;
            index--
        ) {
            const item = items[index];

            positions[index] = Math.min(
                positions[index],
                cursor - item.width
            );

            cursor = positions[index] - gap;
        }

        /*
         * Hvis segmentet reelt er for smalt, mÃ¥
         * de automatiske noder gerne overlappe
         * vandret. placeUnits() opdeler da rÃ¦kken
         * i ekstra lodrette tracks i stedet for at
         * flytte brugerens ankre.
         */
        for (
            let index = startIndex;
            index <= endIndex;
            index++
        ) {
            const item = items[index];

            positions[index] = Math.max(
                leftBound,
                Math.min(
                    rightBound - item.width,
                    positions[index]
                )
            );
        }
    }

    let segmentStart = 0;
    let leftBound = left;

    for (const anchorIndex of anchorIndexes) {
        placeAutomaticSegment(
            segmentStart,
            anchorIndex - 1,
            leftBound,
            positions[anchorIndex] - gap
        );

        segmentStart = anchorIndex + 1;
        leftBound =
            positions[anchorIndex] +
            items[anchorIndex].width +
            gap;
    }

    placeAutomaticSegment(
        segmentStart,
        items.length - 1,
        leftBound,
        right
    );

    for (
        let index = 0;
        index < items.length;
        index++
    ) {
        items[index].x = Math.max(
    left,
    Math.min(
        right,
        positions[index]
    )
);
    }
 
}

    function barycenter(
        item: PreparedNode,
        neighboursById: Map<
            string,
            Set<string>
        >
    ): number | undefined {
        const neighbours = [
            ...(
                neighboursById.get(
                    item.node.id
                ) ?? []
            ),
        ]
            .map(id => byId.get(id))
            .filter(
                (
                    value
                ): value is PreparedNode =>
                    value !== undefined
            );

        if (neighbours.length === 0) {
            return undefined;
        }

        return neighbours.reduce(
            (sum, neighbour) =>
                sum + neighbour.x,
            0
        ) / neighbours.length;
    }

    function compareBarycenters(
        left: number | undefined,
        right: number | undefined
    ): number {
        if (
            left === undefined ||
            right === undefined
        ) {
            return 0;
        }

        const difference = left - right;

        return Math.abs(difference) < 0.5
            ? 0
            : difference;
    }

    for (const row of orderedRows) {
        row.sort(compareHorizontalRank);
        distribute(row);
    }

    /*
     * En eksplicit rank er stÃ¦rkere end
     * krydsningsoptimering. For Ã¸vrige noder:
     *
     * 1. lokale kausale forbindelser
     * 2. forbindelser til andre scener
     * 3. stabil automatisk rank
     */
    for (
        let iteration = 0;
        iteration < 4;
        iteration++
    ) {
        for (const row of orderedRows) {
            row.sort((left, right) => {
                const rankDifference =
                    requestedHorizontalRank(left) -
                    requestedHorizontalRank(right);

                if (
                    Math.abs(rankDifference) >= 0.0001
                ) {
                    return rankDifference;
                }

                if (
                    hasExplicitHorizontalRank(left) ||
                    hasExplicitHorizontalRank(right)
                ) {
                    return compareHorizontalRank(
                        left,
                        right
                    );
                }

                const localDifference =
                    compareBarycenters(
                        barycenter(
                            left,
                            localNeighbours
                        ),
                        barycenter(
                            right,
                            localNeighbours
                        )
                    );

                if (localDifference !== 0) {
                    return localDifference;
                }

                const externalDifference =
                    compareBarycenters(
                        barycenter(
                            left,
                            externalNeighbours
                        ),
                        barycenter(
                            right,
                            externalNeighbours
                        )
                    );

                if (externalDifference !== 0) {
                    return externalDifference;
                }

                return compareHorizontalRank(
                    left,
                    right
                );
            });

            distribute(row);
        }
    }
}
