const NOTION_VERSION = "2026-03-11";

export interface PlotGraphNotionSettings {
    version: 1;
    notionApiKey: string;
    notionDataSourceId: string;
}

let configuredSettings:
    | PlotGraphNotionSettings
    | null = null;

export function configureNotion(
    settings: PlotGraphNotionSettings,
): void {
    configuredSettings = settings;
}

function getSettings(): PlotGraphNotionSettings {
    if (!configuredSettings) {
        throw new Error(
            "PlotGraph er ikke forbundet med Notion.",
        );
    }

    return configuredSettings;
}

function normalizeNotionId(
    value: string,
): string {
    const compact = value
        .replace(/-/g, "")
        .toLowerCase();

    if (!/^[0-9a-f]{32}$/.test(compact)) {
        throw new Error(
            "Data source ID skal være et gyldigt Notion-id.",
        );
    }

    return [
        compact.slice(0, 8),
        compact.slice(8, 12),
        compact.slice(12, 16),
        compact.slice(16, 20),
        compact.slice(20, 32),
    ].join("-");
}

async function getErrorMessage(
    response: Response,
): Promise<string> {
    const body = await response
        .json()
        .catch(() => null);

    if (
        body &&
        typeof body === "object" &&
        "message" in body &&
        typeof body.message === "string"
    ) {
        return body.message;
    }

    return response.statusText ||
        `HTTP ${response.status}`;
}

export async function validateNotionSettings(
    input: Pick<
        PlotGraphNotionSettings,
        "notionApiKey" | "notionDataSourceId"
    >,
): Promise<PlotGraphNotionSettings> {
    const notionApiKey =
        input.notionApiKey.trim();

    if (!notionApiKey) {
        throw new Error(
            "Indtast en Notion API-nøgle.",
        );
    }

    const notionDataSourceId =
        normalizeNotionId(
            input.notionDataSourceId,
        );

    const response = await fetch(
        `https://api.notion.com/v1/data_sources/${notionDataSourceId}/query`,
        {
            method: "POST",
            headers: {
                Authorization:
                    `Bearer ${notionApiKey}`,
                "Notion-Version":
                    NOTION_VERSION,
                "Content-Type":
                    "application/json",
            },
            body: JSON.stringify({
                page_size: 1,
            }),
        },
    );

    if (!response.ok) {
        throw new Error(
            `Notion-forbindelsen kunne ikke valideres: ${
                await getErrorMessage(response)
            }`,
        );
    }

    return {
        version: 1,
        notionApiKey,
        notionDataSourceId,
    };
}

async function notionFetch(
    url: string,
    options: RequestInit = {},
): Promise<Response> {
    const settings = getSettings();

    return fetch(url, {
        ...options,
        headers: {
            Authorization:
                `Bearer ${settings.notionApiKey}`,
            "Notion-Version":
                NOTION_VERSION,
            "Content-Type":
                "application/json",
            ...(options.headers ?? {}),
        },
    });
}

export async function queryNotion(
    body: Record<string, unknown> = {},
): Promise<Response> {
    const settings = getSettings();

    return notionFetch(
        `https://api.notion.com/v1/data_sources/${settings.notionDataSourceId}/query`,
        {
            method: "POST",
            body: JSON.stringify(body),
        },
    );
}

export async function createNotionPage(
    parentId: string,
    label: string,
): Promise<Response> {
    const settings = getSettings();

    return notionFetch(
        "https://api.notion.com/v1/pages",
        {
            method: "POST",
            body: JSON.stringify({
                parent: {
                    data_source_id:
                        settings.notionDataSourceId,
                },
                properties: {
                    title: {
                        title: [
                            {
                                text: {
                                    content: label,
                                },
                            },
                        ],
                    },
                    "Overordnet element": {
                        relation: [
                            {
                                id: parentId,
                            },
                        ],
                    },
                },
            }),
        },
    );
}

export async function moveNotionPage(
    pageId: string,
    parentId: string | null,
): Promise<Response> {
    return notionFetch(
        `https://api.notion.com/v1/pages/${pageId}`,
        {
            method: "PATCH",
            body: JSON.stringify({
                properties: {
                    "Overordnet element": {
                        relation: parentId
                            ? [{ id: parentId }]
                            : [],
                    },
                },
            }),
        },
    );
}

export async function archiveNotionPage(
    pageId: string,
): Promise<Response> {
    return notionFetch(
        `https://api.notion.com/v1/pages/${pageId}`,
        {
            method: "PATCH",
            body: JSON.stringify({
                in_trash: true,
            }),
        },
    );
}

