import * as d3 from "d3";

import {
    ScanSearch,
    Pin,
    Move,
    ArrowDownToDot,
    ArrowUpFromDot,
    Link,
    Unlink,
    FileText,
    ExternalLink,
    Trash2,
    Pencil,
    type IconNode,
} from "lucide";

type IconGroup = d3.Selection<
    SVGGElement,
    unknown,
    null,
    undefined
>;

const icons: Record<
    string,
    IconNode
> = {
    mark: ScanSearch,
    pin: Pin,
    move: Move,
    prerequisite: ArrowDownToDot,
    consequence: ArrowUpFromDot,
    link: Link,
    unlink: Unlink,
    text: FileText,
    notion: ExternalLink,
    delete: Trash2,
    rename: Pencil,
};

export function renderPlotGraphIcon(
    group: IconGroup,
    icon: string,
    size: number
): void {
    const iconNode = icons[icon];

    if (!iconNode) {
        return;
    }

    const svg =
    group
        .append("svg")
        .attr("width", size)
        .attr("height", size)
        .attr("viewBox", "0 0 24 24")
        .attr("fill", "none")
        .attr("stroke", "#222")
        .attr("stroke-width", 2)
        .attr("stroke-linecap", "round")
        .attr("stroke-linejoin", "round")
        .attr("pointer-events", "none")
        .attr("aria-hidden", "true");

    const iconGroup =
        svg.append("g");

    if (icon === "consequence") {
        iconGroup.attr(
            "transform",
            `rotate(180 12 12)`
        );
    }

    for (const [
        tag,
        attrs,
    ] of iconNode) {
        const element =
            iconGroup.append(tag);

        for (const [
            name,
            value,
        ] of Object.entries(attrs)) {
            if (value !== undefined) {
                element.attr(
                    name,
                    value
                );
            }
        }
    }
}