import * as d3 from "d3";

import type { TreeNode } from "../model/types";

import type {
    LayoutGroup,
    LayoutNode,
} from "./layout";

export const nodeRadius = 7;
export const horizontalPadding = 20;
export const maxLabelWidth = 180;
export const labelLineHeight = 12;
export const labelPadding = 6;

export interface SimulationNode
    extends LayoutNode {
    baseY: number;
    baseX: number;
    fx?: number | null;
    fy?: number | null;
}

export interface StoredNodePosition {
    x: number;
    y: number;
    layoutX: number;
    layoutY: number;
}

export interface SimulationEdge {
    source:
        | string
        | SimulationNode;
    target:
        | string
        | SimulationNode;
    sourceNode?: SimulationNode;
    targetNode?: SimulationNode;
    internal?: boolean;
    crossedGroups?: number;
    semanticLinks?: Array<{
    sourceId: string;
    targetId: string;
}>;
}

export function wrapLabel(
    label: string
): string[] {
    const words =
        label.split(/\s+/);

    const lines: string[] = [];
    let currentLine = "";

    for (
        const word of words
    ) {
        const candidate =
            currentLine
                ? `${currentLine} ${word}`
                : word;

        if (
            currentLine &&
            candidate.length * 7 >
                maxLabelWidth
        ) {
            lines.push(
                currentLine
            );

            currentLine = word;
        } else {
            currentLine =
                candidate;
        }
    }

    if (currentLine) {
        lines.push(
            currentLine
        );
    }

    return lines;
}

export function effectiveNodeWidth(
    node: SimulationNode
): number {
    return Math.min(
        node.width,
        maxLabelWidth
    );
}

export function labelHeight(
    node: SimulationNode
): number {
    return (
        wrapLabel(
            node.node.source.label
        ).length *
            labelLineHeight +
        labelPadding
    );
}

export type LabelCollisionForce =
    d3.Force<
        SimulationNode,
        undefined
    > & {
        strength(): number;
        strength(
            value: number
        ): LabelCollisionForce;
    };

export function labelCollision(): LabelCollisionForce {
    let nodes: SimulationNode[] = [];
    let strength = 1;

    const force =
        ((_alpha: number) => {
            for (
                let i = 0;
                i < nodes.length;
                i++
            ) {
                const a =
                    nodes[i];

                for (
                    let j = i + 1;
                    j < nodes.length;
                    j++
                ) {
                    const b =
                        nodes[j];

                    const aHeight =
                        labelHeight(a);

                    const bHeight =
                        labelHeight(b);

                    const minimumYDistance =
                        (
                            aHeight +
                            bHeight
                        ) / 2 + 8;

                    const verticalDistance =
                        Math.abs(
                            b.y - a.y
                        );

                    /*
                     * If the labels are already
                     * separated vertically, they
                     * do not need horizontal
                     * separation.
                     */
                    if (
                        verticalDistance >=
                        minimumYDistance
                    ) {
                        continue;
                    }

                    const aHalf =
                        effectiveNodeWidth(
                            a
                        ) / 2;

                    const bHalf =
                        effectiveNodeWidth(
                            b
                        ) / 2;

                    const minimumXDistance =
                        aHalf +
                        bHalf +
                        20;

                    const dx =
                        b.x - a.x;

                    const distance =
                        Math.abs(dx);

                    if (
                        distance <
                        minimumXDistance
                    ) {
                        const direction =
                            dx >= 0
                                ? 1
                                : -1;

                        const push =
                            (
                                minimumXDistance -
                                distance
                            ) *
                            strength;

                        a.x -=
                            direction *
                            push /
                            2;

                        b.x +=
                            direction *
                            push /
                            2;
                    }

                    /*
                     * Preserve semantic vertical
                     * ordering.
                     */
                    if (
                        verticalDistance <
                        minimumYDistance
                    ) {
                        const aAbove =
                            a.baseY <
                            b.baseY;

                        const push =
                            (
                                minimumYDistance -
                                verticalDistance
                            ) *
                            strength;

                        if (aAbove) {
                            a.y -=
                                push / 2;

                            b.y +=
                                push / 2;
                        } else {
                            a.y +=
                                push / 2;

                            b.y -=
                                push / 2;
                        }
                    }
                }
            }
        }) as LabelCollisionForce;

    force.initialize = (
        simulationNodes
    ) => {
        nodes =
            simulationNodes;
    };

    force.strength = ((
        value?: number
    ) => {
        if (
            value === undefined
        ) {
            return strength;
        }

        strength = value;
        return force;
    }) as LabelCollisionForce["strength"];

    return force;
}

export function orderNodesHorizontally(
    nodes: SimulationNode[],
    edges: SimulationEdge[],
    width: number
): void {
    const plotNodes =
        nodes.filter(
            node =>
                node.node.side === "plot" &&
                node.node.type === "node"
        );

    const byId =
        new Map(
            plotNodes.map(node => [
                node.node.id,
                node,
            ])
        );

    for (const node of nodes) {
        node.x = node.baseX;
    }

    if (plotNodes.length === 0) {
        return;
    }

    const internalSuccessors =
        new Map<string, Set<string>>();

    const internalIncoming =
        new Map<string, number>();

    const allNeighbours =
        new Map<string, Set<string>>();

    const componentParent =
        new Map<string, string>();

    for (const node of plotNodes) {
        const id = node.node.id;

        internalSuccessors.set(id, new Set());
        internalIncoming.set(id, 0);
        allNeighbours.set(id, new Set());
        componentParent.set(id, id);
    }

    function findComponent(
        id: string
    ): string {
        const parent =
            componentParent.get(id)!;

        if (parent === id) {
            return id;
        }

        const root =
            findComponent(parent);

        componentParent.set(id, root);

        return root;
    }

    function joinComponents(
        left: string,
        right: string
    ): void {
        const leftRoot =
            findComponent(left);

        const rightRoot =
            findComponent(right);

        if (leftRoot !== rightRoot) {
            componentParent.set(
                rightRoot,
                leftRoot
            );
        }
    }

    for (const edge of edges) {
        const sourceId =
            edge.sourceNode?.node.id;

        const targetId =
            edge.targetNode?.node.id;

        if (
            !sourceId ||
            !targetId ||
            !byId.has(sourceId) ||
            !byId.has(targetId) ||
            sourceId === targetId
        ) {
            continue;
        }

        allNeighbours
            .get(sourceId)!
            .add(targetId);

        allNeighbours
            .get(targetId)!
            .add(sourceId);

        /*
         * Kun kanter inden for samme scene
         * definerer lokal kausal rang.
         */
        if (!edge.internal) {
            continue;
        }

        const targets =
            internalSuccessors.get(sourceId)!;

        if (targets.has(targetId)) {
            continue;
        }

        targets.add(targetId);

        internalIncoming.set(
            targetId,
            internalIncoming.get(targetId)! + 1
        );

        joinComponents(
            sourceId,
            targetId
        );
    }

    const nodesByComponent =
        new Map<string, SimulationNode[]>();

    for (const node of plotNodes) {
        const componentId =
            findComponent(node.node.id);

        const component =
            nodesByComponent.get(componentId) ??
            [];

        component.push(node);

        nodesByComponent.set(
            componentId,
            component
        );
    }

    const rankById =
        new Map<string, number>();

    const maxRankByComponent =
        new Map<string, number>();

    for (const [
        componentId,
        componentNodes,
    ] of nodesByComponent) {
        const incoming =
            new Map<string, number>();

        for (const node of componentNodes) {
            incoming.set(
                node.node.id,
                internalIncoming.get(
                    node.node.id
                ) ?? 0
            );

            rankById.set(node.node.id, 0);
        }

        const ready =
            componentNodes
                .filter(
                    node =>
                        incoming.get(
                            node.node.id
                        ) === 0
                )
                .sort(
                    (left, right) =>
                        left.baseY - right.baseY
                );

        const processed =
            new Set<string>();

        while (ready.length > 0) {
            const node = ready.shift()!;
            const id = node.node.id;

            processed.add(id);

            for (
                const targetId of
                internalSuccessors.get(id) ?? []
            ) {
                /*
                 * Kryds-scene kanter er ikke med i
                 * den lokale komponent.
                 */
                if (
                    findComponent(targetId) !==
                    componentId
                ) {
                    continue;
                }

                rankById.set(
                    targetId,
                    Math.max(
                        rankById.get(targetId) ?? 0,
                        (rankById.get(id) ?? 0) +
                            1
                    )
                );

                const remaining =
                    incoming.get(targetId)! - 1;

                incoming.set(
                    targetId,
                    remaining
                );

                if (remaining === 0) {
                    ready.push(
                        byId.get(targetId)!
                    );

                    ready.sort(
                        (left, right) =>
                            left.baseY - right.baseY
                    );
                }
            }
        }

        /*
         * Cykler får stabile, lokale slots, men
         * kan ikke få en egentlig DAG-rang.
         */
        const cyclic =
            componentNodes
                .filter(
                    node =>
                        !processed.has(
                            node.node.id
                        )
                )
                .sort(
                    (left, right) =>
                        left.baseY - right.baseY
                );

        cyclic.forEach(
            (node, index) => {
                rankById.set(
                    node.node.id,
                    index
                );
            }
        );

        maxRankByComponent.set(
            componentId,
            Math.max(
                0,
                ...componentNodes.map(
                    node =>
                        rankById.get(
                            node.node.id
                        ) ?? 0
                )
            )
        );
    }

    const left =
        horizontalPadding + 28;

    const right =
        width -
        horizontalPadding -
        28;

    const slotGroups =
        new Map<
            string,
            SimulationNode[]
        >();

    for (const node of plotNodes) {
        const componentId =
            findComponent(node.node.id);

        const rank =
            rankById.get(node.node.id) ?? 0;

        const key =
            `${componentId}:${rank}`;

        const group =
            slotGroups.get(key) ?? [];

        group.push(node);

        slotGroups.set(key, group);
    }

    function columnX(
        node: SimulationNode
    ): number {
        const componentId =
            findComponent(node.node.id);

        const maxRank =
            maxRankByComponent.get(
                componentId
            ) ?? 0;

        const rank =
            rankById.get(node.node.id) ?? 0;

        /*
         * En scene uden lokale kausale kanter
         * får ikke en central lodret kø. Dens
         * punkter fordeles senere som slots.
         */
        if (maxRank === 0) {
            return (left + right) / 2;
        }

        return (
            left +
            rank *
                (
                    (right - left) /
                    maxRank
                )
        );
    }

    /*
     * Første placering: kausale rangkolonner.
     */
    for (const node of plotNodes) {
        node.x = columnX(node);
    }

    /*
     * Flere sweeps fordeler parallelle punkter
     * omkring deres fælles rangkolonne.
     *
     * Nabopunkter bestemmer hvilken side et slot
     * helst skal ligge på. Det reducerer kryds,
     * men flytter aldrig et punkt til en anden
     * kausal rang.
     */
    for (
        let iteration = 0;
        iteration < 6;
        iteration++
    ) {
        for (const group of slotGroups.values()) {
            const first = group[0];

            const componentId =
                findComponent(
                    first.node.id
                );

            const maxRank =
                maxRankByComponent.get(
                    componentId
                ) ?? 0;

            const rank =
                rankById.get(
                    first.node.id
                ) ?? 0;

            const center =
                maxRank === 0
                    ? (left + right) / 2
                    : left +
                        rank *
                            (
                                (right - left) /
                                maxRank
                            );

            const columnWidth =
                maxRank === 0
                    ? right - left
                    : Math.min(
                        150,
                        (right - left) /
                            Math.max(1, maxRank) *
                            0.7
                    );

            const ordered =
                [...group].sort(
                    (leftNode, rightNode) => {
                        function barycenter(
                            node: SimulationNode
                        ): number {
                            const neighbours =
                                [
                                    ...(
                                        allNeighbours.get(
                                            node.node.id
                                        ) ?? []
                                    ),
                                ]
                                    .map(id =>
                                        byId.get(id)
                                    )
                                    .filter(
                                        (
                                            neighbour
                                        ): neighbour is SimulationNode =>
                                            neighbour !==
                                            undefined
                                    );

                            if (
                                neighbours.length === 0
                            ) {
                                return node.baseY;
                            }

                            return neighbours.reduce(
                                (
                                    total,
                                    neighbour
                                ) =>
                                    total +
                                    neighbour.x,
                                0
                            ) / neighbours.length;
                        }

                        return (
                            barycenter(leftNode) -
                            barycenter(rightNode)
                        );
                    }
                );

            ordered.forEach(
                (node, index) => {
                    const x =
                        ordered.length === 1
                            ? center
                            : center -
                                columnWidth / 2 +
                                index *
                                    (
                                        columnWidth /
                                        (
                                            ordered.length -
                                            1
                                        )
                                    );

                    const nodeWidth =
                        effectiveNodeWidth(node);

                    node.x =
                        Math.max(
                            horizontalPadding +
                                nodeWidth / 2,
                            Math.min(
                                width -
                                    horizontalPadding -
                                    nodeWidth / 2,
                                x
                            )
                        );
                }
            );
        }
    }
}

export function edgePath(
    edge: SimulationEdge
): string {
    if (
        !edge.sourceNode ||
        !edge.targetNode
    ) {
        return "";
    }

    const s =
        edge.sourceNode;

    const t =
        edge.targetNode;

    const dx =
        t.x - s.x;

    const dy =
        t.y - s.y;

    const curve =
        Math.max(
            35,
            Math.abs(dx) * 0.35
        );

    const direction =
        dx >= 0 ? 1 : -1;

    const targetRadius =
        t.node.type ===
        "aggregate"
            ? nodeRadius + 7
            : nodeRadius;

    const x1 = s.x;
    const y1 = s.y;
    const x2 = t.x;

    const y2 =
        t.y -
        Math.sign(dy) *
            targetRadius;

    return `
        M ${x1} ${y1}
        C ${s.x + direction * curve} ${y1},
          ${t.x} ${
              t.y -
              Math.sign(dy) *
                  curve
          },
          ${x2} ${y2}
    `;
}

export function containsNode(
    root: TreeNode,
    id: string
): boolean {
    if (root.id === id) {
        return true;
    }

    for (
        const child of
            root.children
    ) {
        if (
            containsNode(
                child,
                id
            )
        ) {
            return true;
        }
    }

    return false;
}

export function countPlotPoints(
    node: TreeNode
): number {
    if (
        node.children.length === 0
    ) {
        return 1;
    }

    return node.children.reduce(
        (count, child) =>
            count +
            countPlotPoints(child),
        0
    );
}

export function countCrossedGroups(
    edge: SimulationEdge,
    groups: LayoutGroup[],
    sourceGroupId?: string,
    targetGroupId?: string
): number {
    if (
        !edge.sourceNode ||
        !edge.targetNode
    ) {
        return 0;
    }

    const source =
        edge.sourceNode;

    const target =
        edge.targetNode;

    const dx =
        target.x - source.x;

    const dy =
        target.y - source.y;

    const curve =
        Math.max(
            35,
            Math.abs(dx) * 0.35
        );

    const direction =
        dx >= 0 ? 1 : -1;

    const p0 = {
        x: source.x,
        y: source.y,
    };

    const p1 = {
        x:
            source.x +
            direction * curve,
        y: source.y,
    };

    const p2 = {
        x: target.x,
        y:
            target.y -
            Math.sign(dy) * curve,
    };

    const p3 = {
        x: target.x,
        y: target.y,
    };

    let count = 0;

    for (const group of groups) {
        if (
            group.node.id ===
                sourceGroupId ||
            group.node.id ===
                targetGroupId
        ) {
            continue;
        }

        if (
            bezierIntersectsRectangle(
                p0,
                p1,
                p2,
                p3,
                group
            )
        ) {
            count++;
        }
    }

    return count;
}

export function bezierIntersectsRectangle(
    p0: { x: number; y: number },
    p1: { x: number; y: number },
    p2: { x: number; y: number },
    p3: { x: number; y: number },
    group: LayoutGroup
): boolean {
    const steps = 40;

    for (
        let i = 0;
        i <= steps;
        i++
    ) {
        const t =
            i / steps;

        const point =
            cubicBezierPoint(
                p0,
                p1,
                p2,
                p3,
                t
            );

        if (
            point.x >= group.x &&
            point.x <=
                group.x +
                    group.width &&
            point.y >= group.y &&
            point.y <=
                group.y +
                    group.height
        ) {
            return true;
        }
    }

    return false;
}

export function cubicBezierPoint(
    p0: { x: number; y: number },
    p1: { x: number; y: number },
    p2: { x: number; y: number },
    p3: { x: number; y: number },
    t: number
): {
    x: number;
    y: number;
} {
    const u = 1 - t;

    return {
        x:
            u * u * u * p0.x +
            3 *
                u *
                u *
                t *
                p1.x +
            3 *
                u *
                t *
                t *
                p2.x +
            t *
                t *
                t *
                p3.x,

        y:
            u * u * u * p0.y +
            3 *
                u *
                u *
                t *
                p1.y +
            3 *
                u *
                t *
                t *
                p2.y +
            t *
                t *
                t *
                p3.y,
    };
}