type OnlyOfficeCommand = () => any;

type OnlyOfficeCallback = (
    returnValue: any,
) => void;

interface QueuedCommand {
    scope: Record<string, any>;
    func: OnlyOfficeCommand;
    isClose: boolean;
    isCalc: boolean;
    callback?: OnlyOfficeCallback;
}

let installed = false;

let commandIsRunning = false;

const commandQueue: QueuedCommand[] = [];

function cloneScopeValue(
    value: unknown,
): unknown {
    if (Array.isArray(value)) {
        return value.map(cloneScopeValue);
    }

    if (
        typeof value === "object" &&
        value !== null
    ) {
        return {
            ...(value as Record<string, unknown>),
        };
    }

    return value;
}

function snapshotScope(): Record<string, any> {
    return Object.fromEntries(
        Object.entries(Asc.scope).map(
            ([key, value]) => [
                key,
                cloneScopeValue(value),
            ],
        ),
    );
}

function restoreScope(
    snapshot: Record<string, any>,
): void {
    for (const key of Object.keys(Asc.scope)) {
        if (!(key in snapshot)) {
            delete Asc.scope[key];
        }
    }

    Object.assign(
        Asc.scope,
        snapshot,
    );
}

function runNextCommand(): void {
    if (commandIsRunning) {
        return;
    }

    const nextCommand =
        commandQueue.shift();

    if (!nextCommand) {
        return;
    }

    const command: QueuedCommand =
        nextCommand;

    const callCommand =
        originalCallCommand;

    if (!callCommand) {
        console.error(
            "ONLYOFFICE-kommandokøen er ikke initialiseret.",
        );

        runNextCommand();
        return;
    }

    commandIsRunning = true;

    restoreScope(command.scope);

    let completed = false;

    function complete(
        returnValue: any,
    ): void {
        if (completed) {
            return;
        }

        completed = true;

        try {
            command.callback?.(returnValue);
        } finally {
            commandIsRunning = false;
            runNextCommand();
        }
    }

    try {
        callCommand(
            command.func,
            command.isClose,
            command.isCalc,
            complete,
        );
    } catch (error) {
        console.error(
            "ONLYOFFICE callCommand fejlede:",
            error,
        );

        complete(undefined);
    }
}

let originalCallCommand:
    | ((
        func: OnlyOfficeCommand,
        isClose?: boolean,
        isCalc?: boolean,
        callback?: OnlyOfficeCallback,
    ) => void)
    | undefined;

export function installOnlyOfficeCommandQueue(): void {
    if (installed) {
        return;
    }

    installed = true;

    originalCallCommand =
        Asc.plugin.callCommand.bind(
            Asc.plugin,
        );

    Asc.plugin.callCommand = (
        func: OnlyOfficeCommand,
        isClose = false,
        isCalc = false,
        callback?: OnlyOfficeCallback,
    ): void => {
        commandQueue.push({
            scope: snapshotScope(),
            func,
            isClose,
            isCalc,
            callback,
        });

        runNextCommand();
    };
}