import * as d3 from "d3";

import {
    useCallback,
    useState,
} from "react";

import type { TreeNode } from "../model/types";

import type {
    Layout,
    LayoutOmission,
    LayoutTreeNode,
} from "./layout";

import {
    getRuntimePlotTree,
} from "./structure";

export interface GraphGroupsControl {
    expanded: Set<string>;

    toggleGroup(
        group: TreeNode
    ): void;

    expandPath(
        root: TreeNode,
        targetId: string
    ): void;
}

export function useGraphGroups(): GraphGroupsControl {
    const [
        expanded,
        setExpanded,
    ] = useState<Set<string>>(
        new Set()
    );

    const toggleGroup =
        useCallback(
            (group: TreeNode) => {
                setExpanded(previous => {
                    const next = new Set(previous);

                    const ids = [
                        group.id,
                        group.link?.id,
                    ].filter(
                        (id): id is string =>
                            Boolean(id)
                    );

                    const shouldExpand = ids.some(
                        id => !next.has(id)
                    );

                    for (const id of ids) {
                        if (shouldExpand) {
                            next.add(id);
                        } else {
                            next.delete(id);
                        }
                    }

                    return next;
                });
            },
            []
        );

    const expandPath = useCallback(
        (
            manuscriptRoot: TreeNode,
            targetId: string
        ) => {
            const plotRoot =
                getRuntimePlotTree(
                    manuscriptRoot
                );

            const manuscriptPath =
                findNodePath(
                    manuscriptRoot,
                    targetId
                );

            const plotPath =
                plotRoot
                    ? findNodePath(
                        plotRoot,
                        targetId
                    )
                    : undefined;

            const initialPath =
                manuscriptPath ?? plotPath;

            const initialRoot =
                manuscriptPath
                    ? manuscriptRoot
                    : plotPath
                        ? plotRoot
                        : undefined;

            if (!initialPath || !initialRoot) {
                return;
            }

            const nodesToExpand =
                new Set<TreeNode>();

            const visited =
                new Set<TreeNode>();

            const pending: Array<{
                node: TreeNode;
                root: TreeNode;
            }> = initialPath.map(node => ({
                node,
                root: initialRoot,
            }));

            while (pending.length > 0) {
                const entry = pending.pop()!;

                if (visited.has(entry.node)) {
                    continue;
                }

                visited.add(entry.node);

                const path =
                    findNodePathByReference(
                        entry.root,
                        entry.node
                    );

                if (!path) {
                    continue;
                }

                for (const node of path.slice(1)) {
                    if (node.children.length > 0) {
                        nodesToExpand.add(node);
                    }
                }

                if (!entry.node.link) {
                    continue;
                }

                const linkedRoot =
                    entry.root === manuscriptRoot
                        ? plotRoot
                        : manuscriptRoot;

                if (!linkedRoot) {
                    continue;
                }

                const linkedPath =
                    findNodePathByReference(
                        linkedRoot,
                        entry.node.link
                    );

                if (!linkedPath) {
                    continue;
                }

                for (const node of linkedPath) {
                    pending.push({
                        node,
                        root: linkedRoot,
                    });
                }
            }

            setExpanded(previous => {
                const next = new Set(previous);
                let changed = false;

                for (const node of nodesToExpand) {
                    if (!next.has(node.id)) {
                        next.add(node.id);
                        changed = true;
                    }
                }

                return changed
                    ? next
                    : previous;
            });
        },
        []
    );

    return {
        expanded,
        toggleGroup,
        expandPath,
    };
}

function findNodePath(
    node: TreeNode,
    targetId: string
): TreeNode[] | undefined {
    if (node.id === targetId) {
        return [node];
    }

    for (const child of node.children) {
        const childPath =
            findNodePath(
                child,
                targetId
            );

        if (childPath) {
            return [
                node,
                ...childPath,
            ];
        }
    }

    return undefined;
}

function findNodePathByReference(
    node: TreeNode,
    target: TreeNode
): TreeNode[] | undefined {
    if (node === target) {
        return [node];
    }

    for (const child of node.children) {
        const childPath =
            findNodePathByReference(
                child,
                target
            );

        if (childPath) {
            return [
                node,
                ...childPath,
            ];
        }
    }

    return undefined;
}

export function renderGraphGroups(
    d3Layer: d3.Selection<
        SVGGElement,
        unknown,
        null,
        undefined
    >,
    layout: Layout,
    availableWidth: number,
    groups: GraphGroupsControl,
    linkPlotGroup: (
        plotNodeId: string,
        manuscriptNodeId: string
    ) => void,
    unlinkPlotGroup: (
        plotNodeId: string
    ) => void,
    navigateToParagraph: (
        paraId: string
    ) => void,
    activeDocumentHeadingId: string | null
): void {
    const manuscriptGroupX =
        availableWidth / 2 - 20;

    const plotGroupX =
        availableWidth / 2 + 20;

    const documentContext =
        getDocumentContext(
            layout,
            activeDocumentHeadingId
        );

    function contextKind(
        treeNode: LayoutTreeNode
    ): "current" | "ancestor" | null {
        if (
            treeNode.side === "manuscript" &&
            treeNode.node.id ===
                documentContext.currentId
        ) {
            return "current";
        }

        if (
            treeNode.side === "manuscript" &&
            documentContext.ancestorIds.has(
                treeNode.node.id
            )
        ) {
            return "ancestor";
        }

        return null;
    }

    function contextColor(
        treeNode: LayoutTreeNode
    ): string {
        switch (contextKind(treeNode)) {
            case "current":
                return "#3d6f9f";

            case "ancestor":
                return "#9cb8d1";

            default:
                return "#bbb";
        }
    }

        function isLinkedPlotGroup(
        treeNode: LayoutTreeNode
    ): boolean {
        return (
            treeNode.side === "plot" &&
            treeNode.node.link !== undefined
        );
    }

    /*
     * Hele gruppelaget er passivt som udgangspunkt.
     * Kun markører, disclosure-ikoner og labels får
     * eksplicit lov til at modtage pointer-events.
     */
    const groupLayer =
        d3Layer
            .append("g")
            .attr(
                "class",
                "groups"
            )
            ;

    renderOmissionBands(
        groupLayer,
        layout.omissions,
        availableWidth
    );

    
        groupLayer
            .selectAll<
                SVGLineElement,
                LayoutTreeNode
            >("line.group-line")
            .data(layout.tree)
            .join("line")
            .attr(
                "class",
                "group-line"
            )            
            .attr(
                "x1",
                treeNode =>
                    treeNode.side === "plot"
                        ? plotGroupX
                        : treeNode.depth * 15
            )
            .attr(
                "y1",
                treeNode =>
                    getGroupY(
                        treeNode,
                        layout
                    )
            )
            .attr(
                "x2",
                treeNode =>
                    treeNode.side === "plot"
    ? availableWidth -
        (
            isLinkedPlotGroup(treeNode)
                ? 26
                : getGroupLabelWidth(
                    treeNode
                ) + 5
        )
                        : treeNode.node.link
                            ? availableWidth
                            : manuscriptGroupX
            )
            .attr(
                "y2",
                treeNode =>
                    getGroupY(
                        treeNode,
                        layout
                    )
            )
            .attr(
                "stroke",
                contextColor
            );

    const manuscriptMarkers =
        groupLayer
            .selectAll<
                SVGCircleElement,
                LayoutTreeNode
            >(
                ".unlinked-manuscript-marker"
            )
            .data(
                layout.tree.filter(
                    treeNode =>
                        treeNode.side ===
                            "manuscript" &&
                        !treeNode.node.link
                )
            )
            .join("circle")
            .attr(
                "class",
                "unlinked-manuscript-marker"
            )
            .attr(
                "cx",
                manuscriptGroupX
            )
            .attr(
                "cy",
                treeNode =>
                    getGroupY(
                        treeNode,
                        layout
                    )
            )
            .attr(
                "r",
                4
            )
            .attr(
                "fill",
                "#555"
            )
            .style(
                "cursor",
                "grab"
            )
            .style(
                "pointer-events",
                "all"
            );

    const plotMarkers =
        groupLayer
            .selectAll<
                SVGCircleElement,
                LayoutTreeNode
            >(
                ".unlinked-plot-marker"
            )
            .data(
                layout.tree.filter(
                    treeNode =>
                        treeNode.side === "plot" &&
                        !treeNode.node.link
                )
            )
            .join("circle")
            .attr(
                "class",
                "unlinked-plot-marker"
            )
            .attr(
                "cx",
                plotGroupX
            )
            .attr(
                "cy",
                treeNode =>
                    getGroupY(
                        treeNode,
                        layout
                    )
            )
            .attr(
                "r",
                4
            )
            .attr(
                "fill",
                "white"
            )
            .attr(
                "stroke",
                "#555"
            )
            .attr(
                "stroke-width",
                1.5
            )
            .style(
                "cursor",
                "grab"
            )
            .style(
                "pointer-events",
                "all"
            );

    let draggingSide:
        | "manuscript"
        | "plot"
        | null = null;

    let draggingNode:
        | LayoutTreeNode
        | null = null;

    let currentTarget:
        | LayoutTreeNode
        | null = null;

    const dragLine =
        groupLayer
            .append("line")
            .attr(
                "class",
                "group-link-drag-line"
            )
            .attr(
                "stroke",
                "#555"
            )
            .attr(
                "stroke-width",
                2
            )
            .style(
                "pointer-events",
                "none"
            )
            .style(
                "display",
                "none"
            );

    function getTargetMarkers():
        d3.Selection<
            SVGCircleElement,
            LayoutTreeNode,
            SVGGElement,
            unknown
        > {
        return draggingSide === "manuscript"
            ? plotMarkers
            : manuscriptMarkers;
    }

    function clearTargetHighlight(): void {
        manuscriptMarkers
            .attr("r", 4)
            .style("cursor", "grab");

        plotMarkers
            .attr("r", 4)
            .style("cursor", "grab");

        currentTarget = null;
    }

    function findTarget(
        x: number,
        y: number
    ): LayoutTreeNode | null {
        const targetMarkers =
            getTargetMarkers();

        let closest:
            | LayoutTreeNode
            | null = null;

        let closestDistance =
            Infinity;

        targetMarkers.each(target => {
            const targetX =
                draggingSide === "manuscript"
                    ? plotGroupX
                    : manuscriptGroupX;

            const targetY =
                getGroupY(
                    target,
                    layout
                );

            const distance =
                Math.hypot(
                    x - targetX,
                    y - targetY
                );

            if (
                distance <= 12 &&
                distance < closestDistance
            ) {
                closest = target;
                closestDistance = distance;
            }
        });

        return closest;
    }

    function highlightTarget(
        target: LayoutTreeNode | null
    ): void {
        if (
            currentTarget?.node.id ===
            target?.node.id
        ) {
            return;
        }

        clearTargetHighlight();

        if (!target) {
            return;
        }

        getTargetMarkers()
            .filter(
                treeNode =>
                    treeNode.node.id ===
                    target.node.id
            )
            .attr("r", 9)
            .style(
                "cursor",
                "pointer"
            );

        currentTarget = target;
    }

    function startGroupLinkDrag(
        event: d3.D3DragEvent<
            SVGCircleElement,
            LayoutTreeNode,
            unknown
        >,
        treeNode: LayoutTreeNode
    ): void {
        draggingSide = treeNode.side;
        draggingNode = treeNode;

        getTargetMarkers()
            .attr("r", 7)
            .style(
                "cursor",
                "crosshair"
            );

        const x =
            treeNode.side === "manuscript"
                ? manuscriptGroupX
                : plotGroupX;

        const y =
            getGroupY(
                treeNode,
                layout
            );

        dragLine
            .attr("x1", x)
            .attr("y1", y)
            .attr("x2", event.x)
            .attr("y2", event.y)
            .style(
                "display",
                null
            );
    }

    function dragGroupLink(
        event: d3.D3DragEvent<
            SVGCircleElement,
            LayoutTreeNode,
            unknown
        >
    ): void {
        if (!draggingSide) {
            return;
        }

        dragLine
            .attr("x2", event.x)
            .attr("y2", event.y);

        highlightTarget(
            findTarget(
                event.x,
                event.y
            )
        );
    }

    function endGroupLinkDrag(): void {
        if (
            draggingNode &&
            currentTarget
        ) {
            if (draggingSide === "plot") {
                linkPlotGroup(
                    draggingNode.node.id,
                    currentTarget.node.id
                );
            } else {
                linkPlotGroup(
                    currentTarget.node.id,
                    draggingNode.node.id
                );
            }
        }

        clearTargetHighlight();

        dragLine.style(
            "display",
            "none"
        );

        draggingSide = null;
        draggingNode = null;
        currentTarget = null;
    }

    manuscriptMarkers.call(
        d3.drag<
            SVGCircleElement,
            LayoutTreeNode
        >()
            .on(
                "start",
                startGroupLinkDrag
            )
            .on(
                "drag",
                dragGroupLink
            )
            .on(
                "end",
                endGroupLinkDrag
            )
    );

    plotMarkers.call(
        d3.drag<
            SVGCircleElement,
            LayoutTreeNode
        >()
            .on(
                "start",
                startGroupLinkDrag
            )
            .on(
                "drag",
                dragGroupLink
            )
            .on(
                "end",
                endGroupLinkDrag
            )
    );

    groupLayer
        .selectAll<
            SVGRectElement,
            LayoutTreeNode
        >(".group-label-background")
                .data(
            layout.tree.filter(
                treeNode =>
                    !isLinkedPlotGroup(
                        treeNode
                    )
            )
        )
        .join("rect")
        .attr(
            "class",
            "group-label-background"
        )
        .attr(
            "x",
            treeNode =>
                treeNode.side === "plot"
                    ? availableWidth -
                        getGroupLabelWidth(treeNode)
                    : treeNode.depth * 15
        )
        .attr(
            "y",
            treeNode =>
                getGroupY(
                    treeNode,
                    layout
                ) - 9
        )
        .attr(
            "width",
            treeNode =>
                getGroupLabelWidth(treeNode)
        )
        .attr(
            "height",
            18
        )
        .attr(
            "fill",
            treeNode => {
                switch (contextKind(treeNode)) {
                    case "current":
                        return "#e7f1fb";

                    case "ancestor":
                        return "#f3f7fb";

                    default:
                        return "#fff";
                }
            }
        )
        .style(
            "pointer-events",
            "none"
        );

    groupLayer
        .selectAll<
            SVGRectElement,
            LayoutTreeNode
        >(".document-context-marker")
        .data(
            layout.tree.filter(
                treeNode =>
                    contextKind(treeNode) !== null
            )
        )
        .join("rect")
        .attr(
            "class",
            "document-context-marker"
        )
        .attr(
            "x",
            treeNode =>
                treeNode.side === "manuscript"
                    ? treeNode.depth * 15
                    : availableWidth -
                        getGroupLabelWidth(treeNode)
        )
        .attr(
            "y",
            treeNode =>
                getGroupY(
                    treeNode,
                    layout
                ) - 10
        )
        .attr("width", 3)
        .attr("height", 20)
        .attr(
            "fill",
            contextColor
        )
        .attr(
            "opacity",
            treeNode =>
                contextKind(treeNode) === "current"
                    ? 1
                    : 0.55
        )
        .style(
            "pointer-events",
            "none"
        );

    const manuscriptDisclosures =
        groupLayer
            .selectAll<
                SVGTextElement,
                LayoutTreeNode
            >(".manuscript-group-disclosure")
            .data(
                layout.tree.filter(
                    treeNode =>
                        treeNode.side ===
                            "manuscript" &&
                        canToggleGroup(treeNode)
                )
            )
            .join("text")
            .attr(
                "class",
                "manuscript-group-disclosure"
            )
            .attr(
                "x",
                treeNode =>
                    treeNode.depth * 15 + 5
            )
            .attr(
                "y",
                treeNode =>
                    getGroupY(
                        treeNode,
                        layout
                    ) + 4
            )
            .attr(
                "text-anchor",
                "start"
            )
            .text(treeNode =>
                groups.expanded.has(
                    treeNode.node.id
                ) ||
                (
                    treeNode.node.link !==
                        undefined &&
                    groups.expanded.has(
                        treeNode.node.link.id
                    )
                )
                    ? "▾"
                    : "▸"
            )
            .style(
                "cursor",
                "pointer"
            )
            .style(
                "pointer-events",
                "all"
            );

    manuscriptDisclosures.on(
        "click",
        (event, treeNode) => {
            event.stopPropagation();

            groups.toggleGroup(
                treeNode.node
            );
        }
    );

    const groupLabels =
        groupLayer
            .selectAll<
                SVGTextElement,
                LayoutTreeNode
            >(".group-label")
                    .data(
            layout.tree.filter(
                treeNode =>
                    !isLinkedPlotGroup(
                        treeNode
                    )
            )
        )
            .join("text")
            .attr(
                "x",
                treeNode => {
                    if (treeNode.side === "plot") {
                        return availableWidth - 5;
                    }

                    return (
                        treeNode.depth * 15 +
                        (
                            canToggleGroup(treeNode)
                                ? 18
                                : 5
                        )
                    );
                }
            )
            .attr(
                "y",
                treeNode =>
                    getGroupY(
                        treeNode,
                        layout
                    ) + 4
            )
            .attr(
                "class",
                "group-label"
            )
            .attr(
                "text-anchor",
                treeNode =>
                    treeNode.side === "plot"
                        ? "end"
                        : "start"
            )
            .text(treeNode => {
                const label =
                    getRenderedGroupLabel(
                        treeNode,
                        groups
                    );

                const maxWidth =
                    treeNode.side === "plot"
                        ? plotGroupX - 25
                        : manuscriptGroupX -
                            treeNode.depth * 15 -
                            35;

                const maxChars =
                    Math.max(
                        5,
                        Math.floor(maxWidth / 6)
                    );

                return label.length > maxChars
                    ? label.slice(
                        0,
                        maxChars - 1
                    ) + "…"
                    : label;
            })
            .style(
                "cursor",
                treeNode => {
                    if (treeNode.side === "plot") {
                        return canToggleGroup(treeNode)
                            ? "pointer"
                            : "default";
                    }

                    return getParaId(
                        treeNode.node
                    )
                        ? "pointer"
                        : "default";
                }
            )
            .attr(
                "fill",
                treeNode =>
                    contextKind(treeNode) === "current"
                        ? "#294f76"
                        : "#667"
            )
            .attr(
                "font-weight",
                treeNode =>
                    contextKind(treeNode) === "current"
                        ? 700
                        : contextKind(treeNode)
                            ? 600
                            : 400
            )
            .style(
                "pointer-events",
                "all"
            );

    groupLabels.on(
        "click",
        (event, treeNode) => {
            event.stopPropagation();

            if (treeNode.side === "plot") {
                toggleGroup(
                    treeNode,
                    groups
                );

                return;
            }

            const paraId = getParaId(
                treeNode.node
            );
          

            if (paraId) {
                navigateToParagraph(paraId);
            }
        }
    );

           const linkedPlotGroups =
        layout.tree.filter(
            isLinkedPlotGroup
        );

    const hideUnlinkTimeoutById =
        new Map<string, number>();

    const linkedPlotGroupControls =
        groupLayer
            .selectAll<
                SVGTextElement,
                LayoutTreeNode
            >(".linked-plot-group-unlink")
            .data(
                linkedPlotGroups,
                treeNode => treeNode.node.id
            )
            .join("text")
            .attr(
                "class",
                "linked-plot-group-unlink"
            )
            .attr(
                "x",
                availableWidth - 7
            )
            .attr(
                "y",
                treeNode =>
                    getGroupY(
                        treeNode,
                        layout
                    ) + 5
            )
            .attr(
                "text-anchor",
                "end"
            )
            .attr(
                "font-size",
                "16px"
            )
            .attr(
                "fill",
                "#8b8795"
            )
            .text("×")
            .style(
                "cursor",
                "pointer"
            )
            .style("opacity", 0)
            .style(
                "pointer-events",
                "none"
            );

        const linkedPlotGroupHoverLabels =
        groupLayer
            .selectAll<
                SVGTextElement,
                LayoutTreeNode
            >(".linked-plot-group-hover-label")
            .data(
                linkedPlotGroups,
                treeNode => treeNode.node.id
            )
            .join("text")
            .attr(
                "class",
                "linked-plot-group-hover-label"
            )
            .attr(
                "x",
                availableWidth - 30
            )
            .attr(
                "y",
                treeNode =>
                    getGroupY(
                        treeNode,
                        layout
                    ) - 8
            )
            .attr(
                "text-anchor",
                "end"
            )
            .attr(
                "font-size",
                "12px"
            )
            .attr(
                "fill",
                "#667"
            )
            .text(
                treeNode =>
                    treeNode.node.label
            )
            .style("opacity", 0)
            .style(
                "pointer-events",
                "none"
            );

    function showUnlinkControl(
        treeNode: LayoutTreeNode
    ): void {
        const timeout =
            hideUnlinkTimeoutById.get(
                treeNode.node.id
            );

        if (timeout !== undefined) {
            window.clearTimeout(timeout);

            hideUnlinkTimeoutById.delete(
                treeNode.node.id
            );
        }

        linkedPlotGroupControls
            .filter(
                candidate =>
                    candidate.node.id ===
                    treeNode.node.id
            )
            .style("opacity", 1)
            .style(
                "pointer-events",
                "all"
            );
                linkedPlotGroupHoverLabels
            .filter(
                candidate =>
                    candidate.node.id ===
                    treeNode.node.id
            )
            .style("opacity", 1);
    }

        function hideUnlinkControl(
        treeNode: LayoutTreeNode
    ): void {
        const existingTimeout =
            hideUnlinkTimeoutById.get(
                treeNode.node.id
            );

        if (existingTimeout !== undefined) {
            window.clearTimeout(
                existingTimeout
            );
        }

        const timeout =
            window.setTimeout(() => {
                linkedPlotGroupControls
                    .filter(
                        candidate =>
                            candidate.node.id ===
                            treeNode.node.id
                    )
                    .style("opacity", 0)
                    .style(
                        "pointer-events",
                        "none"
                    );

                linkedPlotGroupHoverLabels
                    .filter(
                        candidate =>
                            candidate.node.id ===
                            treeNode.node.id
                    )
                    .style("opacity", 0);

                hideUnlinkTimeoutById.delete(
                    treeNode.node.id
                );
            }, 180);

        hideUnlinkTimeoutById.set(
            treeNode.node.id,
            timeout
        );
    }

    linkedPlotGroupControls
        .on(
            "mouseenter",
            (_event, treeNode) => {
                showUnlinkControl(
                    treeNode
                );
            }
        )
        .on(
            "mouseleave",
            (_event, treeNode) => {
                hideUnlinkControl(
                    treeNode
                );
            }
        )
        .on(
            "click",
            (event, treeNode) => {
                event.stopPropagation();

                unlinkPlotGroup(
                    treeNode.node.id
                );
            }
        );

    linkedPlotGroupControls
        .append("title")
        .text(
            "Bryd kæde til manuskriptgruppe"
        );

                        
    groupLayer
        .selectAll<
            SVGLineElement,
            LayoutTreeNode
        >(".linked-plot-group-hit-area")
        .data(
            linkedPlotGroups,
            treeNode => treeNode.node.id
        )
        .join("line")
        .attr(
            "class",
            "linked-plot-group-hit-area"
        )
        .attr(
            "x1",
            plotGroupX
        )
        .attr(
            "y1",
            treeNode =>
                getGroupY(
                    treeNode,
                    layout
                )
        )
        .attr(
            "x2",
            availableWidth - 26
        )
        .attr(
            "y2",
            treeNode =>
                getGroupY(
                    treeNode,
                    layout
                )
        )
        .attr(
            "stroke",
            "rgba(0, 0, 0, 0)"
        )
        .attr(
            "stroke-width",
            18
        )
        .style(
            "pointer-events",
            "stroke"
        )
        .on(
            "mouseenter",
            (_event, treeNode) => {
                showUnlinkControl(
                    treeNode
                );
            }
        )
        .on(
            "mouseleave",
            (_event, treeNode) => {
                hideUnlinkControl(
                    treeNode
                );
            }
        );
}

function canToggleGroup(
    treeNode: LayoutTreeNode
): boolean {
    return (
        treeNode.depth > 0 &&
        treeNode.node.children.length > 0
    );
}

function toggleGroup(
    treeNode: LayoutTreeNode,
    groups: GraphGroupsControl
): void {
    if (!canToggleGroup(treeNode)) {
        return;
    }

    groups.toggleGroup(treeNode.node);
}

function getRenderedGroupLabel(
    treeNode: LayoutTreeNode,
    groups: GraphGroupsControl
): string {
    if (treeNode.side === "manuscript") {
        return getGroupLabel(treeNode);
    }

    const disclosure =
        canToggleGroup(treeNode)
            ? groups.expanded.has(
                treeNode.node.id
            )
                ? "▾ "
                : "▸ "
            : "";

    return (
        disclosure +
        getGroupLabel(treeNode)
    );
}

function getGroupLabelWidth(
    treeNode: LayoutTreeNode
): number {
    const disclosureWidth =
        canToggleGroup(treeNode)
            ? 12
            : 0;

    return (
        getGroupLabel(treeNode).length *
            6 +
        8 +
        disclosureWidth
    );
}

function getGroupY(
    treeNode: LayoutTreeNode,
    layout: Layout
): number {
    const group =
        layout.groups.find(
            candidate =>
                candidate.side ===
                    treeNode.side &&
                candidate.node.id ===
                    treeNode.node.id
        );

    if (group) {
        return group.y + 25;
    }

    const aggregate =
        layout.nodes.find(
            node =>
                node.node.source.id ===
                    treeNode.node.id &&
                node.node.type ===
                    "aggregate"
        );

    if (aggregate) {
        return aggregate.y;
    }

    return 25;
}

function getGroupLabel(
    treeNode: LayoutTreeNode
): string {
    return treeNode.node.label;
}

function getParaId(
    node: TreeNode
): string {
    return node.id.replace(
        /^onlyoffice:heading:/,
        ""
    );
}

function getDocumentContext(
    layout: Layout,
    activeDocumentHeadingId: string | null
): {
    currentId: string | null;
    ancestorIds: Set<string>;
} {
    const ancestorIds = new Set<string>();

    if (!activeDocumentHeadingId) {
        return {
            currentId: null,
            ancestorIds,
        };
    }

    const activeIndex =
        layout.tree.findIndex(
            treeNode =>
                treeNode.side === "manuscript" &&
                treeNode.node.id ===
                    activeDocumentHeadingId
        );

    if (activeIndex === -1) {
        return {
            currentId: null,
            ancestorIds,
        };
    }

    const active =
        layout.tree[activeIndex];

    let requiredAncestorDepth =
        active.depth;

    for (
        let index = activeIndex - 1;
        index >= 0;
        index--
    ) {
        const candidate =
            layout.tree[index];

        if (
            candidate.side !== "manuscript" ||
            candidate.depth >=
                requiredAncestorDepth
        ) {
            continue;
        }

        ancestorIds.add(candidate.node.id);

        requiredAncestorDepth =
            candidate.depth;

        if (requiredAncestorDepth === 0) {
            break;
        }
    }

    return {
        currentId: activeDocumentHeadingId,
        ancestorIds,
    };
}

function renderOmissionBands(
    groupLayer: d3.Selection<
        SVGGElement,
        unknown,
        null,
        undefined
    >,
    omissions: LayoutOmission[],
    availableWidth: number
): void {
    const bands =
        groupLayer
            .selectAll<
                SVGGElement,
                LayoutOmission
            >("g.omission-band")
            .data(
                omissions,
                omission => omission.id
            )
            .join("g")
            .attr(
                "class",
                "omission-band"
            )
            .style(
                "pointer-events",
                "none"
            );

    bands
        .selectAll<
            SVGRectElement,
            LayoutOmission
        >("rect")
        .data(
            omission => [omission]
        )
        .join("rect")
        .attr(
            "x",
            omission =>
                omission.side === "manuscript"
                    ? omission.depth * 15
                    : 0
        )
        .attr(
            "y",
            omission =>
                omission.y -
                omission.height / 2
        )
        .attr(
            "width",
            omission =>
                omission.side === "manuscript"
                    ? availableWidth -
                        omission.depth * 15
                    : availableWidth
        )
        .attr(
            "height",
            omission => omission.height
        )
        .attr(
            "fill",
            "rgba(110, 108, 118, 0.10)"
        );

    bands
        .selectAll<
            SVGTextElement,
            LayoutOmission
        >("text")
        .data(
            omission => [omission]
        )
        .join("text")
        .attr(
            "x",
            omission =>
                omission.side === "manuscript"
                    ? omission.depth * 15 + 9
                    : 9
        )
        .attr(
            "y",
            omission => omission.y + 5
        )
        .attr(
            "text-anchor",
            "middle"
        )
        .attr(
            "font-size",
            "18px"
        )
        .attr(
            "fill",
            "#8b8795"
        )
        .text("⋮");
}