export function getCurrentSelection(
    callback: (text: string | null) => void,
): void {
    Asc.plugin.callCommand(
        () => {
            const document = Api.GetDocument();
            const range = document.GetRangeBySelect();

            if (!range) {
                return null;
            }

            return range.GetText();
        },
        false,
        false,
        callback,
    );
}

export function createBookmark(
    name: string,
    callback?: (result: string | null) => void,
): void {
    Asc.scope.bookmarkName = name;

    Asc.plugin.callCommand(
        () => {
            const document = Api.GetDocument();
            const range = document.GetRangeBySelect();

            if (!range) {
                return "No selection";
            }

            range.AddBookmark(Asc.scope.bookmarkName);

            return Asc.scope.bookmarkName;
        },
        false,
        false,
        callback,
    );
}

export function deleteBookmark(
    name: string,
    callback: (deleted: boolean) => void
): void {
    Asc.scope.bookmarkName = name;

    Asc.plugin.callCommand(
        () => {
            const document = Api.GetDocument();

            return document.DeleteBookmark(
                Asc.scope.bookmarkName
            );
        },
        false,
        false,
        returnValue => {
            callback(returnValue === true);
        }
    );
}

export function goToBookmark(name: string): void {
    Asc.scope.bookmarkName = name;

    Asc.plugin.callCommand(
        () => {
            const document = Api.GetDocument();
            const bookmark = document.GetBookmark(
                Asc.scope.bookmarkName,
            );

            if (!bookmark) {
                return;
            }

            bookmark.GoTo();
            bookmark.Select();
        },
        false,
        false,
    );
}

export interface DocumentHeading {
    index: number;    
    paraId: string;
    internalId: string;
    text: string;
    level?: number;
    style?: string;
}

export function getDocumentHeadings(
    callback: (headings: DocumentHeading[]) => void,
): void {
    Asc.plugin.callCommand(
        () => {
            const document =
                Api.GetDocument();

            const paragraphs =
                document.GetAllHeadingParagraphs();

            const usedIds = new Set<number>();

            for (const paragraph of paragraphs) {
                const id =
                    paragraph.GetParaId();

                if (id > 0) {
                    usedIds.add(id);
                }
            }

            let nextId = 1;

            function allocateId(): number {
                while (usedIds.has(nextId)) {
                    nextId++;
                }

                const id = nextId;

                usedIds.add(id);
                nextId++;

                return id;
            }

            return paragraphs.map(
                (paragraph, index) => {
                    let paragraphId =
                        paragraph.GetParaId();

                    if (paragraphId === 0) {
                        paragraphId =
                            allocateId();

                        const result =
                            paragraph.SetParaId(
                                paragraphId,
                            );

                        if (!result) {
                            throw new Error(
                                `Kunne ikke tildele ParaId til heading ${index}`,
                            );
                        }

                        paragraphId =
                            paragraph.GetParaId();
                    }

                    const style =
                        paragraph.GetStyle();

                    const styleName =
                        style
                            ? style.GetName()
                            : null;

                    const match =
                        styleName?.match(
                            /^Heading (\d+)$/,
                        );

                    const level =
                        match
                            ? Number(match[1])
                            : undefined;

                   return {
    index,    
    paraId: paragraphId.toString(),
    internalId: paragraph.GetInternalId(),
    text: paragraph.GetText(),
    level,
    style: styleName,
};
                },
            );
        },
        false,
        false,
        (returnValue) => {
            callback(
                returnValue as DocumentHeading[],
            );
        },
    );
}

