export function goToHeading(
    paraId: string
): void {
    console.log("goToHeading kaldt", { paraId });

    Asc.scope.paraId = paraId;

    Asc.plugin.callCommand(
        () => {
            const targetId =
                Number(Asc.scope.paraId);

            const headings =
                Api.GetDocument()
                    .GetAllHeadingParagraphs();

            const paragraph =
                headings.find(
                    heading =>
                        heading.GetParaId() ===
                        targetId
                );

            console.log(
                "ONLYOFFICE: heading-opslag",
                {
                    paraId: Asc.scope.paraId,
                    targetId,
                    headingCount: headings.length,
                    found: Boolean(paragraph),
                }
            );

            if (!paragraph) {
                return false;
            }

            return paragraph.MoveCursorToEnd();
        },
        false,
        false,
        result => {
            console.log(
                "ONLYOFFICE: MoveCursorToEnd resultat",
                { paraId, result }
            );
        }
    );
}