import type { TreeNode } from "../model/types";

import {
    createBookmark,
    deleteBookmark,
    getAllBookmarkNames,
    getDocumentHeadings,
    type DocumentHeading,
} from "./OnlyOfficeDocument";

const BOOKMARK_PREFIX = "plotgraph:";

interface ParagraphTextEvent {
    paragraphId: string;
    recalcId: string;
    text: string;
}

interface DocumentPosition {
    headingInternalId: string | null;
    activeBookmarkNames: string[];
    hasTextSelection: boolean;
}

type ManuscriptSubscriber =
    (root: TreeNode) => void;

type DocumentHeadingPositionSubscriber =
    (headingId: string | null) => void;

type ActivePlotGraphBookmarkSubscriber =
    (bookmarkNames: ReadonlySet<string>) => void;

type DocumentTextSelectionSubscriber =
    (hasTextSelection: boolean) => void;

let manuscriptRoot: TreeNode | null = null;

let headingIdByInternalId =
    new Map<string, string>();

let knownPlotGraphBookmarkNames: string[] = [];

const subscribers =
    new Set<ManuscriptSubscriber>();

const documentHeadingPositionSubscribers =
    new Set<DocumentHeadingPositionSubscriber>();

const activePlotGraphBookmarkSubscribers =
    new Set<ActivePlotGraphBookmarkSubscriber>();

const documentTextSelectionSubscribers =
    new Set<DocumentTextSelectionSubscriber>();

let lastDocumentHeadingId:
    | string
    | null
    | undefined;

let lastActivePlotGraphBookmarkNames:
    | ReadonlySet<string>
    | undefined;

let lastHasTextSelection:
    | boolean
    | undefined;

let documentPositionTimer: number | null =
    null;

let documentPositionRequestInFlight =
    false;

let documentPositionRequestQueued =
    false;

let documentPositionEventsAttached =
    false;

let paragraphEvents: ParagraphTextEvent[] = [];

let syncTimer: number | null = null;

let eventsAttached = false;

export function loadManuscript(
    callback: (root: TreeNode) => void,
): void {
    getDocumentHeadings((headings) => {
        const root =
            createManuscriptTree(headings);

        manuscriptRoot = root;

        headingIdByInternalId =
            createHeadingIdMap(headings);

        scheduleDocumentHeadingPositionUpdate();

        callback(root);
    });
}

export function subscribeManuscript(
    callback: ManuscriptSubscriber,
): () => void {
    subscribers.add(callback);

    attachManuscriptEvents();

    loadManuscript((root) => {
        callback(root);
    });

    return () => {
        subscribers.delete(callback);
    };
}

export function subscribeDocumentHeadingPosition(
    callback: DocumentHeadingPositionSubscriber,
): () => void {
    documentHeadingPositionSubscribers.add(
        callback,
    );

    attachDocumentPositionEvents();

    if (
        lastDocumentHeadingId !== undefined
    ) {
        callback(lastDocumentHeadingId);
    } else {
        scheduleDocumentHeadingPositionUpdate();
    }

    return () => {
        documentHeadingPositionSubscribers.delete(
            callback,
        );
    };
}

export function subscribeActivePlotGraphBookmarks(
    callback: ActivePlotGraphBookmarkSubscriber,
): () => void {
    activePlotGraphBookmarkSubscribers.add(
        callback,
    );

    attachDocumentPositionEvents();

    if (
        lastActivePlotGraphBookmarkNames !==
        undefined
    ) {
        callback(
            new Set(
                lastActivePlotGraphBookmarkNames,
            ),
        );
    } else {
        scheduleDocumentHeadingPositionUpdate();
    }

    return () => {
        activePlotGraphBookmarkSubscribers.delete(
            callback,
        );
    };
}

export function subscribeDocumentTextSelection(
    callback: DocumentTextSelectionSubscriber,
): () => void {
    documentTextSelectionSubscribers.add(
        callback,
    );

    attachDocumentPositionEvents();

    if (
        lastHasTextSelection !== undefined
    ) {
        callback(lastHasTextSelection);
    } else {
        scheduleDocumentHeadingPositionUpdate();
    }

    return () => {
        documentTextSelectionSubscribers.delete(
            callback,
        );
    };
}

function attachDocumentPositionEvents(): void {
    if (documentPositionEventsAttached) {
        return;
    }

    documentPositionEventsAttached = true;

    Asc.plugin.attachEditorEvent(
        "onTargetPositionChanged",
        scheduleDocumentHeadingPositionUpdate,
    );
}

function scheduleDocumentHeadingPositionUpdate(): void {
    if (documentPositionTimer !== null) {
        window.clearTimeout(
            documentPositionTimer,
        );
    }

    documentPositionTimer =
        window.setTimeout(
            readDocumentHeadingPosition,
            150,
        );
}

function readDocumentHeadingPosition(): void {
    documentPositionTimer = null;

    if (!manuscriptRoot) {
        return;
    }

    if (documentPositionRequestInFlight) {
        documentPositionRequestQueued = true;
        return;
    }

    documentPositionRequestInFlight = true;

    Asc.scope.headingInternalIds = [
        ...headingIdByInternalId.keys(),
    ];

    Asc.scope.plotGraphBookmarkNames = [
        ...knownPlotGraphBookmarkNames,
    ];

    Asc.plugin.callCommand(
        () => {
            const document =
                Api.GetDocument();

            const range =
                document.GetRangeBySelect();

            if (!range) {
                return {
                    headingInternalId: null,
                    activeBookmarkNames: [],
                    hasTextSelection: false,
                };
            }

            const hasTextSelection =
                range.GetText().length > 0;

            const rangeStart =
                Math.min(
                    range.GetStartPos(),
                    range.GetEndPos(),
                );

            const rangeEnd =
                Math.max(
                    range.GetStartPos(),
                    range.GetEndPos(),
                );

            const activeBookmarkNames: string[] =
                [];

            const bookmarkNames = Array.isArray(
    Asc.scope.plotGraphBookmarkNames,
)
    ? Asc.scope.plotGraphBookmarkNames
    : [];

for (const bookmarkName of bookmarkNames) {
    const bookmarkRange =
        document.GetBookmarkRange(
            bookmarkName,
        );

    if (!bookmarkRange) {
        continue;
    }




                const bookmarkStart =
                    Math.min(
                        bookmarkRange.GetStartPos(),
                        bookmarkRange.GetEndPos(),
                    );

                const bookmarkEnd =
                    Math.max(
                        bookmarkRange.GetStartPos(),
                        bookmarkRange.GetEndPos(),
                    );

                if (
                    rangeStart <= bookmarkEnd &&
                    rangeEnd >= bookmarkStart
                ) {
                    activeBookmarkNames.push(
                        bookmarkName,
                    );
                }
            }

            const activeParagraph =
                range.GetParagraph(0);

            if (!activeParagraph) {
                return {
                    headingInternalId: null,
                    activeBookmarkNames,
                    hasTextSelection,
                };
            }

            const activeInternalId =
                activeParagraph.GetInternalId();

            const headingInternalIds =
                new Set(
                    Asc.scope.headingInternalIds,
                );

            let nearestHeadingInternalId:
                | string
                | null = null;

            for (
                const paragraph of
                document.GetAllParagraphs()
            ) {
                const internalId =
                    paragraph.GetInternalId();

                if (
                    headingInternalIds.has(
                        internalId,
                    )
                ) {
                    nearestHeadingInternalId =
                        internalId;
                }

                if (
                    internalId ===
                    activeInternalId
                ) {
                    break;
                }
            }

            return {
                headingInternalId:
                    nearestHeadingInternalId,
                activeBookmarkNames,
                hasTextSelection,
            };
        },
        false,
        false,
        (returnValue) => {
            documentPositionRequestInFlight =
                false;

            const position =
                returnValue as Partial<DocumentPosition>
                    | null;

            const headingInternalId =
                typeof position?.headingInternalId ===
                "string"
                    ? position.headingInternalId
                    : null;

            const headingId =
                headingInternalId === null
                    ? null
                    : headingIdByInternalId.get(
                        headingInternalId,
                    ) ?? null;

            const activeBookmarkNames =
                new Set(
                    Array.isArray(
                        position?.activeBookmarkNames,
                    )
                        ? position.activeBookmarkNames.filter(
                            isPlotGraphBookmark,
                        )
                        : [],
                );

            const hasTextSelection =
                position?.hasTextSelection === true;

            notifyDocumentHeadingPosition(
                headingId,
            );

            notifyActivePlotGraphBookmarks(
                activeBookmarkNames,
            );

            notifyDocumentTextSelection(
                hasTextSelection,
            );

            if (
                documentPositionRequestQueued
            ) {
                documentPositionRequestQueued =
                    false;

                scheduleDocumentHeadingPositionUpdate();
            }
        },
    );
}

function notifyDocumentHeadingPosition(
    headingId: string | null,
): void {
    if (
        headingId ===
        lastDocumentHeadingId
    ) {
        return;
    }

    lastDocumentHeadingId = headingId;

    for (
        const subscriber of
        documentHeadingPositionSubscribers
    ) {
        subscriber(headingId);
    }
}

function notifyActivePlotGraphBookmarks(
    bookmarkNames: ReadonlySet<string>,
): void {
    if (
        setsAreEqual(
            bookmarkNames,
            lastActivePlotGraphBookmarkNames,
        )
    ) {
        return;
    }

    lastActivePlotGraphBookmarkNames =
        new Set(bookmarkNames);

    for (
        const subscriber of
        activePlotGraphBookmarkSubscribers
    ) {
        subscriber(new Set(bookmarkNames));
    }
}

function notifyDocumentTextSelection(
    hasTextSelection: boolean,
): void {
    if (
        hasTextSelection ===
        lastHasTextSelection
    ) {
        return;
    }

    lastHasTextSelection = hasTextSelection;

    for (
        const subscriber of
        documentTextSelectionSubscribers
    ) {
        subscriber(hasTextSelection);
    }
}

function setsAreEqual(
    first: ReadonlySet<string>,
    second: ReadonlySet<string> | undefined,
): boolean {
    if (!second || first.size !== second.size) {
        return false;
    }

    for (const value of first) {
        if (!second.has(value)) {
            return false;
        }
    }

    return true;
}

function attachManuscriptEvents(): void {
    if (eventsAttached) {
        return;
    }

    eventsAttached = true;

    Asc.plugin.attachEditorEvent(
        "onParagraphText",
        (...args: any[]) => {
            const event =
                args[0] as
                    | ParagraphTextEvent
                    | undefined;

            if (!event) {
                return;
            }

            paragraphEvents.push(event);

            if (syncTimer !== null) {
                window.clearTimeout(syncTimer);
            }

            syncTimer = window.setTimeout(
                processParagraphEvents,
                100,
            );
        },
    );
}

function processParagraphEvents(): void {
    const batch = paragraphEvents;

    paragraphEvents = [];
    syncTimer = null;

    if (batch.length === 0) {
        return;
    }

    if (
        batch.length === 1 &&
        manuscriptRoot !== null
    ) {
        const event = batch[0];

        const nodeId =
            headingIdByInternalId.get(
                event.paragraphId,
            );

        if (nodeId !== undefined) {
            const updatedRoot =
                updateNodeLabel(
                    manuscriptRoot,
                    nodeId,
                    event.text,
                );

            manuscriptRoot = updatedRoot;

            notifySubscribers(updatedRoot);

            return;
        }
    }

    resyncManuscript();
}

function resyncManuscript(): void {
    getDocumentHeadings((headings) => {
        const root =
            createManuscriptTree(headings);

        manuscriptRoot = root;

        headingIdByInternalId =
            createHeadingIdMap(headings);

        scheduleDocumentHeadingPositionUpdate();

        notifySubscribers(root);
    });
}

function notifySubscribers(
    root: TreeNode,
): void {
    for (const subscriber of subscribers) {
        subscriber(root);
    }
}

function createHeadingIdMap(
    headings: DocumentHeading[],
): Map<string, string> {
    return new Map(
        headings.map((heading) => [
            heading.internalId,
            `onlyoffice:heading:${heading.paraId}`,
        ]),
    );
}

function updateNodeLabel(
    node: TreeNode,
    nodeId: string,
    label: string,
): TreeNode {
    if (node.id === nodeId) {
        return {
            ...node,
            label,
        };
    }

    let changed = false;

    const children = node.children.map(
        (child) => {
            const updated =
                updateNodeLabel(
                    child,
                    nodeId,
                    label,
                );

            if (updated !== child) {
                changed = true;
            }

            return updated;
        },
    );

    if (!changed) {
        return node;
    }

    return {
        ...node,
        children,
    };
}

function createManuscriptTree(
    headings: DocumentHeading[],
): TreeNode {
    const root: TreeNode = {
        id: "manuscript",
        label: "Manuskript",
        role: "container",
        children: [],
        prerequisites: [],
    };

    const stack: Array<{
        level: number;
        node: TreeNode;
    }> = [];

    for (const heading of headings) {
        const level =
            heading.level ?? 1;

        const node: TreeNode = {
            id:
                `onlyoffice:heading:${heading.paraId}`,
            label: heading.text,
            role: "container",
            children: [],
            prerequisites: [],
        };

        while (
            stack.length > 0 &&
            stack[stack.length - 1].level >= level
        ) {
            stack.pop();
        }

        if (stack.length === 0) {
            root.children.push(node);
        } else {
            stack[
                stack.length - 1
            ].node.children.push(node);
        }

        stack.push({
            level,
            node,
        });
    }

    return root;
}

export function loadPlotGraphBookmarks(
    callback: (root: TreeNode) => void,
): void {
    getAllBookmarkNames((bookmarkNames) => {
        const plotGraphBookmarks =
            bookmarkNames.filter(
                isPlotGraphBookmark,
            );

        setKnownPlotGraphBookmarkNames(
            plotGraphBookmarks,
        );

        const root: TreeNode = {
            id: "bookmarks",
            label: "Bookmarks",
            role: "container",
            children:
                plotGraphBookmarks.map(
                    (bookmarkName): TreeNode => ({
                        id: bookmarkName,
                        label: bookmarkName,
                        role: "container",
                        children: [],
                        prerequisites: [],
                    }),
                ),
            prerequisites: [],
        };

        callback(root);
    });
}

function isPlotGraphBookmark(
    name: unknown,
): name is string {
    return (
        typeof name === "string" &&
        name.startsWith(BOOKMARK_PREFIX)
    );
}

function setKnownPlotGraphBookmarkNames(
    bookmarkNames: readonly string[],
): void {
    knownPlotGraphBookmarkNames = [
        ...new Set(bookmarkNames),
    ];

    scheduleDocumentHeadingPositionUpdate();
}

export function createTestBookmark(
    callback?: (result: string | null) => void,
): void {
    const name =
        `${BOOKMARK_PREFIX}test`;

    createBookmark(name, callback);
}

export function createPlotGraphBookmark(
    callback: (
        bookmarkName: string | null
    ) => void,
): void {
    const bookmarkName =
        `${BOOKMARK_PREFIX}${crypto.randomUUID()}`;

    createBookmark(
        bookmarkName,
        (result) => {
            const createdBookmarkName =
                result === bookmarkName
                    ? bookmarkName
                    : null;

            if (createdBookmarkName) {
                setKnownPlotGraphBookmarkNames([
                    ...knownPlotGraphBookmarkNames,
                    createdBookmarkName,
                ]);
            }

            callback(createdBookmarkName);
        },
    );
}

export function deletePlotGraphBookmark(
    bookmarkName: string,
    callback: (deleted: boolean) => void,
): void {
    if (!isPlotGraphBookmark(bookmarkName)) {
        callback(false);
        return;
    }

    deleteBookmark(
        bookmarkName,
        (deleted) => {
            if (deleted) {
                setKnownPlotGraphBookmarkNames(
                    knownPlotGraphBookmarkNames.filter(
                        (name) =>
                            name !== bookmarkName,
                    ),
                );
            }

            callback(deleted);
        },
    );
}

export function getPlotGraphBookmarkNames(
    callback: (
        names: Set<string>
    ) => void,
): void {
    getAllBookmarkNames((names) => {
        const rawBookmarks =
            names as unknown[];

        const plotGraphBookmarkNames =
            rawBookmarks.filter(
                isPlotGraphBookmark,
            );

        setKnownPlotGraphBookmarkNames(
            plotGraphBookmarkNames,
        );

        callback(
            new Set(plotGraphBookmarkNames),
        );
    });
}

export const PLOTGRAPH_SETTINGS_PROPERTY =
    "PlotGraphSettings";

export interface PlotGraphDocumentSettings {
    version: 1;
    notionApiKey: string;
    notionDataSourceId: string;
}

function isPlotGraphDocumentSettings(
    value: unknown,
): value is PlotGraphDocumentSettings {
    if (
        typeof value !== "object" ||
        value === null
    ) {
        return false;
    }

    const settings =
        value as Partial<PlotGraphDocumentSettings>;

    return (
        settings.version === 1 &&
        typeof settings.notionApiKey ===
            "string" &&
        typeof settings.notionDataSourceId ===
            "string"
    );
}

export function getPlotGraphDocumentSettings(
    callback: (
        settings: PlotGraphDocumentSettings | null,
    ) => void,
): void {
    Asc.scope.plotGraphSettingsProperty =
        PLOTGRAPH_SETTINGS_PROPERTY;

    Asc.plugin.callCommand(
        () => {
            try {
                const document = Api.GetDocument();

                const getCustomProperties = (
                    document as unknown as {
                        GetCustomProperties?: () =>
                            ApiCustomProperties;
                    }
                ).GetCustomProperties;

                if (
                    typeof getCustomProperties !==
                    "function"
                ) {
                    return "";
                }

                const properties =
                    getCustomProperties.call(
                        document,
                    );

                const value = properties.Get(
                    Asc.scope
                        .plotGraphSettingsProperty,
                );

                return typeof value === "string"
                    ? value
                    : "";
            } catch {
                return "";
            }
        },
        false,
        false,
        (value: unknown) => {
            if (
                typeof value !== "string" ||
                value.length === 0
            ) {
                callback(null);
                return;
            }

            try {
                const parsed =
                    JSON.parse(value) as unknown;

                callback(
                    isPlotGraphDocumentSettings(
                        parsed,
                    )
                        ? parsed
                        : null,
                );
            } catch {
                callback(null);
            }
        },
    );
}

export function savePlotGraphDocumentSettings(
    settings: PlotGraphDocumentSettings,
    callback: (saved: boolean) => void,
): void {
    Asc.scope.plotGraphSettingsProperty =
        PLOTGRAPH_SETTINGS_PROPERTY;

    Asc.scope.plotGraphSettingsJson =
        JSON.stringify(settings);

    Asc.plugin.callCommand(
        () => {
            try {
                const document = Api.GetDocument();

                const getCustomProperties = (
                    document as unknown as {
                        GetCustomProperties?: () =>
                            ApiCustomProperties;
                    }
                ).GetCustomProperties;

                if (
                    typeof getCustomProperties !==
                    "function"
                ) {
                    return false;
                }

                const properties =
                    getCustomProperties.call(
                        document,
                    );

                const added = properties.Add(
                    Asc.scope
                        .plotGraphSettingsProperty,
                    Asc.scope.plotGraphSettingsJson,
                );

                const stored = properties.Get(
                    Asc.scope
                        .plotGraphSettingsProperty,
                );

                return (
                    added === true &&
                    stored ===
                        Asc.scope
                            .plotGraphSettingsJson
                );
            } catch {
                return false;
            }
        },
        false,
        false,
        (saved: unknown) => {
            callback(saved === true);
        },
    );
}