export async function updatePlotLayoutPreference(
    pageId: string,
    layoutPreference: LayoutPreference | undefined,
): Promise<void> {
    const response =
        await updateNotionLayoutPreference(
            pageId,
            serializeLayoutPreference(
                layoutPreference,
            ),
        );

    if (!response.ok) {
        const body =
            await response.text();

        throw new Error(
            `Kunne ikke opdatere plotlayout: ${
                response.status
            } ${body}`,
        );
    }
}

export async function createPlotPage(
    parentId: string,
    label: string,
): Promise<{
    id: string;
    url: string;
}> {
    const response =
        await createNotionPage(
            parentId,
            label,
        );

    if (!response.ok) {
        const body =
            await response.text();

        throw new Error(
            `Kunne ikke oprette plotpunkt: ${
                response.status
            } ${body}`,
        );
    }

    const page =
        await response.json() as {
            id: string;
            url: string;
        };

    return {
        id: page.id,
        url: page.url,
    };
}

export function getNotionPageUrl(
    pageId: string,
): string {
    return `notion://${pageId.replace(
        /-/g,
        "",
    )}`;
}

function isRecord(
    value: unknown,
): value is Record<string, unknown> {
    return (
        typeof value === "object" &&
        value !== null
    );
}

function isNotionPage(
    value: unknown,
): value is NotionPage {
    if (!isRecord(value)) {
        return false;
    }

    return (
        typeof value.id === "string" &&
        typeof value.url === "string" &&
        isRecord(value.properties)
    );
}

function buildTree(
    pages: NotionPage[],
): TreeNode {
    const nodes =
        new Map<string, TreeNode>();

    const parents =
        new Map<string, string>();

    const childOrder =
        new Map<string, string[]>();

    for (const page of pages) {
        const properties =
            page.properties;

        const childIds =
            getRelations(
                properties["Under-element"],
            );

        const linkMasterId =
            getText(
                properties["linkMasterId"],
            );

        const layoutPreference =
            parseLayoutPreference(
                getText(
                    properties["plotgraphlayout"],
                ),
            );

        const node: TreeNode = {
            id: page.id,
            label: getText(
                properties["Navn"],
            ),
            role:
                childIds.length > 0
                    ? "container"
                    : "node",
            children: [],
            prerequisites:
                getRelations(
                    properties["Blokeret af"],
                ),
            ...(linkMasterId
                ? { linkMasterId }
                : {}),
            ...(layoutPreference
                ? { layoutPreference }
                : {}),
            properties: {
                notionUrl: page.url,
            },
        };

        nodes.set(page.id, node);

        const parentIds =
            getRelations(
                properties[
                    "Overordnet element"
                ],
            );

        if (parentIds.length > 0) {
            parents.set(
                page.id,
                parentIds[0],
            );
        }

        if (childIds.length > 0) {
            childOrder.set(
                page.id,
                childIds,
            );
        }
    }

    const root: TreeNode = {
        id: "root",
        label: "Root",
        role: "container",
        children: [],
        prerequisites: [],
    };

    for (const node of nodes.values()) {
        const parentId =
            parents.get(node.id);

        if (!parentId) {
            root.children.push(node);
            continue;
        }

        const parent =
            nodes.get(parentId);

        if (parent) {
            parent.children.push(node);
        } else {
            root.children.push(node);
        }
    }

    function sortChildren(
        parent: TreeNode,
    ): void {
        const order =
            childOrder.get(parent.id);

        if (order) {
            const position =
                new Map(
                    order.map(
                        (id, index) => [
                            id,
                            index,
                        ],
                    ),
                );

            parent.children.sort(
                (left, right) =>
                    (
                        position.get(left.id) ??
                        Number.MAX_SAFE_INTEGER
                    ) -
                    (
                        position.get(right.id) ??
                        Number.MAX_SAFE_INTEGER
                    ),
            );
        }

        for (const child of parent.children) {
            sortChildren(child);
        }
    }

    sortChildren(root);

    return root;
}

function getText(
    property: NotionProperty | undefined,
): string {
    if (!property) {
        return "";
    }

    const fragments =
        property.type === "title"
            ? property.title
            : property.type === "rich_text"
                ? property.rich_text
                : undefined;

    if (!Array.isArray(fragments)) {
        return "";
    }

    return fragments
        .filter(isRecord)
        .map(
            (part) =>
                typeof part.plain_text === "string"
                    ? part.plain_text
                    : "",
        )
        .join("");
}

function getRelations(
    property: NotionProperty | undefined,
): string[] {
    if (
        !property ||
        property.type !== "relation" ||
        !Array.isArray(property.relation)
    ) {
        return [];
    }

    return property.relation
        .filter(isRecord)
        .map(
            (relation) => relation.id,
        )
        .filter(
            (id): id is string =>
                typeof id === "string",
        );
}

function parseLayoutPreference(
    value: string | null | undefined,
): LayoutPreference | undefined {
    if (!value) {
        return undefined;
    }

    try {
        const candidate: unknown =
            JSON.parse(value);

        if (!isRecord(candidate)) {
            return undefined;
        }

        const horizontalRank =
            normaliseRank(
                candidate.horizontalRank,
            );

        const verticalRank =
            normaliseRank(
                candidate.verticalRank,
            );

        if (
            horizontalRank === undefined &&
            verticalRank === undefined
        ) {
            return undefined;
        }

        return {
            horizontalRank,
            verticalRank,
        };
    } catch {
        return undefined;
    }
}

function normaliseRank(
    value: unknown,
): number | undefined {
    if (
        typeof value !== "number" ||
        !Number.isFinite(value) ||
        value < 0 ||
        value > 1
    ) {
        return undefined;
    }

    return value;
}

function serializeLayoutPreference(
    layoutPreference:
        | LayoutPreference
        | undefined,
): string | null {
    if (!layoutPreference) {
        return null;
    }

    const horizontalRank =
        normaliseRank(
            layoutPreference.horizontalRank,
        );

    const verticalRank =
        normaliseRank(
            layoutPreference.verticalRank,
        );

    if (
        horizontalRank === undefined &&
        verticalRank === undefined
    ) {
        return null;
    }

    return JSON.stringify({
        v: 2,
        ...(horizontalRank === undefined
            ? {}
            : { horizontalRank }),
        ...(verticalRank === undefined
            ? {}
            : { verticalRank }),
    });
}