import * as d3 from "d3";

import type { GraphSelection } from "./selection";
import type { GraphGroupsControl } from "./GraphGroups";
import type { TreeNode } from "../model/types";

import {
    countPlotPoints,
    labelLineHeight,
    wrapLabel,
} from "./GraphCanvas.helpers";

import type {
    SimulationNode,
} from "./GraphCanvas.helpers";

export function createNodeGroups(
    d3Layer: d3.Selection<
        SVGGElement,
        unknown,
        null,
        undefined
    >,
    simulationNodes: SimulationNode[]
) {
    const nodeLayer =
        d3Layer
            .append("g")
            .attr(
                "class",
                "nodes"
            );

    return nodeLayer
        .selectAll<
            SVGGElement,
            SimulationNode
        >("g")
        .data(simulationNodes)
        .join("g")
        .attr(
            "class",
            "node"
        )
        .attr(
            "data-plot-node-id",
            node =>
                node.node.source.id
        );
}

export function applyNodeOpacity(
    nodeGroups: d3.Selection<
        SVGGElement,
        SimulationNode,
        SVGGElement,
        unknown
    >,
    causalFocusNodeIds: ReadonlySet<string>,
    causalNeighborhood: {
        upstream: Set<string>;
        downstream: Set<string>;
    }
): void {
        nodeGroups.attr(
        "opacity",
        node => {
            if (causalFocusNodeIds.size === 0) {
                return 1;
            }

            if (
                node.node.type === "aggregate" &&
                node.node.side === "plot"
            ) {
                return containsCausalPlotPoint(
                    node.node.source,
                    causalFocusNodeIds,
                    causalNeighborhood
                )
                    ? 1
                    : 0.15;
            }

            const id = node.node.source.id;

            return (
                causalFocusNodeIds.has(id) ||
                causalNeighborhood.upstream.has(id) ||
                causalNeighborhood.downstream.has(id)
            )
                ? 1
                : 0.15;
        }
    );
}

function containsCausalPlotPoint(
    node: TreeNode,
    causalFocusNodeIds: ReadonlySet<string>,
    causalNeighborhood: {
        upstream: Set<string>;
        downstream: Set<string>;
    }
): boolean {
    if (
        causalFocusNodeIds.has(node.id) ||
        causalNeighborhood.upstream.has(node.id) ||
        causalNeighborhood.downstream.has(node.id)
    ) {
        return true;
    }

    return node.children.some(
        child =>
            containsCausalPlotPoint(
                child,
                causalFocusNodeIds,
                causalNeighborhood
            )
    );
}

export function renderNodeCircles(
    nodeGroups: d3.Selection<
        SVGGElement,
        SimulationNode,
        SVGGElement,
        unknown
    >,
    nodeRadius: number,
    validBookmarkNames: ReadonlySet<string>,
    activeBookmarkNames: ReadonlySet<string>
): void {
    const visibleNodes =
        nodeGroups.filter(
            node =>
                !(
                    node.node.type ===
                        "aggregate" &&
                    node.node.side ===
                        "manuscript"
                )
        );

    visibleNodes
        .append("circle")
        .attr(
            "r",
            node =>
                node.node.type ===
                    "aggregate"
                    ? nodeRadius + 7
                    : nodeRadius
        )
        .attr(
            "fill",
            node => {
                if (
                    node.node.type ===
                    "aggregate"
                ) {
                    return "#555";
                }

                return hasValidBookmark(
                    node,
                    validBookmarkNames
                )
                    ? "#222"
                    : "white";
            }
        )
        .attr(
            "stroke",
            node =>
                node.node.type === "node" &&
                node.node.side === "plot"
                    ? "#222"
                    : "none"
        )
        .attr(
            "stroke-width",
            2
        );

    visibleNodes
        .filter(node =>
            hasActiveBookmark(
                node,
                activeBookmarkNames
            )
        )
        .append("circle")
        .attr(
            "class",
            "active-bookmark-ring"
        )
        .attr(
            "r",
            nodeRadius + 6
        )
        .attr("fill", "none")
        .attr("stroke", "#2f80ed")
        .attr(
            "stroke-width",
            3
        )
        .attr(
            "pointer-events",
            "none"
        );
}

export function renderNodeSelectionRing(
    nodeGroups: d3.Selection<
        SVGGElement,
        SimulationNode,
        SVGGElement,
        unknown
    >,
    nodeRadius: number,
    neighborhoodNodeId: string | null
): void {
    nodeGroups
        .filter(
            node =>
                !(
                    node.node.type ===
                        "aggregate" &&
                    node.node.side ===
                        "manuscript"
                )
        )
        .append<SVGCircleElement>(
            "circle"
        )
        .attr(
            "class",
            "node-selection-ring"
        )
        .attr(
            "r",
            node =>
                node.node.type ===
                    "aggregate"
                    ? nodeRadius + 11
                    : nodeRadius + 5
        )
        .attr("fill", "none")
        .attr("stroke", "#d22")
        .attr(
            "stroke-width",
            2
        )
        .attr(
            "opacity",
            node =>
                node.node.source.id ===
                neighborhoodNodeId
                    ? 1
                    : 0
        );
}

export function renderNodeLabels(
    nodeGroups: d3.Selection<
        SVGGElement,
        SimulationNode,
        SVGGElement,
        unknown
    >,
    selection: GraphSelection,
    editingNodeId: string | null,
    setEditingNodeId: React.Dispatch<
        React.SetStateAction<string | null>
    >,
    persistNewPlotNode: (
        nodeId: string,
        label: string
    ) => Promise<void>,
    renamePlotNode: (
        nodeId: string,
        label: string
    ) => void,
    cancelPlotNode: (
        nodeId: string
    ) => void
): void {
    nodeGroups.each(
        function (node) {
            /*
             * Aggregates er fortsat med i
             * simulation/layout, men vises nu
             * som disclosure ved gruppelabelen.
             */
            if (
                node.node.type ===
                "aggregate"
            ) {
                return;
            }

            const lines =
                wrapLabel(
                    node.node.source.label
                );

            const offset =
                -(
                    (lines.length - 1) *
                    labelLineHeight
                ) / 2;

            const labelX = 12;

            const textSelection =
                d3.select(this);

            const notionUrl =
                node.node.source
                    .properties
                    ?.notionUrl as
                    | string
                    | undefined;

            const text =
                node.node.source.id ===
                    "root" ||
                !notionUrl
                    ? textSelection
                        .append("text")
                        .attr("x", labelX)
                        .attr(
                            "text-anchor",
                            "start"
                        )
                        .attr(
                            "class",
                            "node-label"
                        )
                    : textSelection
                        .append("a")
                        .attr(
                            "href",
                            notionUrl.replace(
                                /^https:/,
                                "notion:"
                            )
                        )
                        .attr(
                            "target",
                            "_blank"
                        )
                        .attr(
                            "rel",
                            "noopener noreferrer"
                        )
                        .style(
                            "cursor",
                            "pointer"
                        )
                        .append("text")
                        .attr("x", labelX)
                        .attr(
                            "text-anchor",
                            "start"
                        )
                        .attr(
                            "class",
                            "node-label"
                        );

            lines.forEach(
                (line, index) => {
                    text
                        .append("tspan")
                        .attr("x", labelX)
                        .attr(
                            "y",
                            offset +
                                index *
                                    labelLineHeight +
                                5
                        )
                        .text(line);
                }
            );

            text.on(
                "click",
                event => {
                    if (
                        selection?.type ===
                            "node" &&
                        selection.id ===
                            node.node.source.id
                    ) {
                        event.preventDefault();
                        event.stopPropagation();

                        setEditingNodeId(
                            node.node.source.id
                        );
                    }
                }
            );

            if (
                editingNodeId ===
                node.node.source.id
            ) {
                text.style(
                    "display",
                    "none"
                );

                const input =
                    textSelection
                        .append(
                            "foreignObject"
                        )
                        .attr("x", labelX)
                        .attr("y", -14)
                        .attr("width", 250)
                        .attr("height", 30)
                        .append("xhtml:input")
                        .attr("type", "text")
                        .attr(
                            "value",
                            node.node.source.label
                        )
                        .style(
                            "width",
                            "240px"
                        )
                        .style(
                            "font",
                            "14px sans-serif"
                        )
                        .style(
                            "padding",
                            "2px 4px"
                        )
                        .style(
                            "box-sizing",
                            "border-box"
                        );

                const inputElement =
                    input.node() as
                        | HTMLInputElement
                        | null;

                if (!inputElement) {
                    return;
                }

                inputElement.focus({
                    preventScroll: true,
                });

                inputElement.select();

                input.on(
                    "keydown",
                    async event => {
                        if (
                            event.key ===
                            "Escape"
                        ) {
                            event.preventDefault();

                            if (
                                node.node.source.id.startsWith(
                                    "new-"
                                )
                            ) {
                                cancelPlotNode(
                                    node.node.source.id
                                );
                            }

                            setEditingNodeId(null);
                            return;
                        }

                        if (
                            event.key !==
                            "Enter"
                        ) {
                            return;
                        }

                        event.preventDefault();

                        const newLabel =
                            inputElement.value.trim();

                        if (!newLabel) {
                            return;
                        }

                        if (
                            node.node.source.id.startsWith(
                                "new-"
                            )
                        ) {
                            await persistNewPlotNode(
                                node.node.source.id,
                                newLabel
                            );
                        } else {
                            renamePlotNode(
                                node.node.source.id,
                                newLabel
                            );
                        }

                        setEditingNodeId(null);
                    }
                );
            }
        }
    );
}

export function renderAggregateCounts(
    nodeGroups: d3.Selection<
        SVGGElement,
        SimulationNode,
        SVGGElement,
        unknown
    >
): void {
    nodeGroups
        .filter(
            node =>
                node.node.type ===
                    "aggregate" &&
                node.node.side === "plot"
        )
        .append("text")
        .attr(
            "text-anchor",
            "middle"
        )
        .attr(
            "dy",
            "0.35em"
        )
        .attr("fill", "white")
        .attr(
            "font-size",
            "9px"
        )
        .attr(
            "font-weight",
            "bold"
        )
        .text(
            node =>
                countPlotPoints(
                    node.node.source
                )
        );
}

export function enableAggregateSelection(
    nodeGroups: d3.Selection<
        SVGGElement,
        SimulationNode,
        SVGGElement,
        unknown
    >,
    groups: GraphGroupsControl
): void {
    nodeGroups
        .filter(
            node =>
                node.node.type ===
                    "aggregate" &&
                node.node.side === "plot"
        )
        .style(
            "cursor",
            "pointer"
        )
        .on(
            "click",
            (event, node) => {
                event.stopPropagation();

                groups.toggleGroup(
                    node.node.source
                );
            }
        );
}

const BOOKMARK_LINK_PREFIX =
    "onlyoffice:bookmark:";

function hasValidBookmark(
    node: SimulationNode,
    validBookmarkNames: ReadonlySet<string>
): boolean {
    if (
        node.node.type !== "node" ||
        node.node.side !== "plot"
    ) {
        return false;
    }

    const linkMasterId =
        node.node.source.linkMasterId;

    if (
        !linkMasterId?.startsWith(
            BOOKMARK_LINK_PREFIX
        )
    ) {
        return false;
    }

    const bookmarkName =
        linkMasterId.slice(
            BOOKMARK_LINK_PREFIX.length
        );

    const isValid =
        validBookmarkNames.has(
            bookmarkName
        );
   
    return isValid;
}

function hasActiveBookmark(
    node: SimulationNode,
    activeBookmarkNames: ReadonlySet<string>
): boolean {
    if (
        node.node.type !== "node" ||
        node.node.side !== "plot"
    ) {
        return false;
    }

    const linkMasterId =
        node.node.source.linkMasterId;

    if (
        !linkMasterId?.startsWith(
            BOOKMARK_LINK_PREFIX
        )
    ) {
        return false;
    }

    const bookmarkName =
        linkMasterId.slice(
            BOOKMARK_LINK_PREFIX.length
        );

    return activeBookmarkNames.has(
        bookmarkName
    );
}