import type { TreeNode } from "../model/types";

/*
 * Det oprindelige plot bevarer hierarki og rækkefølge.
 * Runtime-plottet bærer links og beregnede rows.
 */
const originalPlotByRuntimeRoot =
    new WeakMap<TreeNode, TreeNode>();

const runtimePlotByRuntimeRoot =
    new WeakMap<TreeNode, TreeNode>();

export function getOriginalPlotTree(
    runtimeRoot: TreeNode
): TreeNode | undefined {
    return originalPlotByRuntimeRoot.get(
        runtimeRoot
    );
}

export function getRuntimePlotTree(
    runtimeRoot: TreeNode
): TreeNode | undefined {
    return runtimePlotByRuntimeRoot.get(
        runtimeRoot
    );
}

export function mergeStructure(
    plot: TreeNode,
    manuscript: TreeNode
): TreeNode {
    const runtimeManuscript =
        cloneTree(manuscript);

    const runtimePlot =
        cloneTree(plot);

    const originalPlot =
        cloneTree(plot);

    const manuscriptById =
        new Map<string, TreeNode>();

    collectNodes(
        runtimeManuscript,
        manuscriptById
    );

    linkExplicitPairs(
        runtimePlot,
        manuscriptById
    );

    assignRows(
        runtimeManuscript,
        runtimePlot
    );

    originalPlotByRuntimeRoot.set(
        runtimeManuscript,
        originalPlot
    );

    runtimePlotByRuntimeRoot.set(
        runtimeManuscript,
        runtimePlot
    );

    return runtimeManuscript;
}

function linkExplicitPairs(
    plotNode: TreeNode,
    manuscriptById: Map<string, TreeNode>
): void {
    if (plotNode.linkMasterId) {
        const manuscriptNode =
            manuscriptById.get(
                plotNode.linkMasterId
            );

        if (
            manuscriptNode &&
            plotNode.role === "container" &&
            manuscriptNode.role === "container"
        ) {
            plotNode.link = manuscriptNode;
            manuscriptNode.link = plotNode;
        }
    }

    for (const child of plotNode.children) {
        linkExplicitPairs(
            child,
            manuscriptById
        );
    }
}

interface IndexedNode {
    node: TreeNode;
    side: "manuscript" | "plot";
    index: number;
    parent?: IndexedNode;
}

function assignRows(
    manuscriptRoot: TreeNode,
    plotRoot: TreeNode
): void {
    const manuscript =
        indexDfs(manuscriptRoot, "manuscript");

    const plot =
        indexDfs(plotRoot, "plot");

    const manuscriptByNode =
        new Map(
            manuscript.map(entry =>
                [entry.node, entry] as const
            )
        );

    const plotByNode =
        new Map(
            plot.map(entry =>
                [entry.node, entry] as const
            )
        );

    const links = collectLinks(
        manuscript,
        plot,
        manuscriptByNode,
        plotByNode
    );

    /*
     * Ingen eksplicitte links:
     * hvert træ får sin egen DFS 0, 1, 2 ...
     */
    if (!links.length) {
        manuscript.forEach((entry, index) => {
            entry.node.row = index;
        });

        plot.forEach((entry, index) => {
            entry.node.row = index;
        });

        return;
    }

    const components =
        new Components([
            ...manuscript,
            ...plot,
        ]);

    for (const [left, right] of links) {
        components.join(left, right);
    }

    const groups = components.groups();

    const componentOf =
        new Map<IndexedNode, IndexedNode>();

    const groupByComponent =
        new Map<IndexedNode, IndexedNode[]>();

    for (const group of groups) {
        const component = group[0];

        groupByComponent.set(
            component,
            group
        );

        const manuscriptMembers =
            group.filter(
                entry =>
                    entry.side === "manuscript"
            );

        const plotMembers =
            group.filter(
                entry =>
                    entry.side === "plot"
            );

        /*
         * En linkkæde må ikke samle to noder fra
         * samme træ i én række.
         */
        if (
            manuscriptMembers.length > 1 ||
            plotMembers.length > 1
        ) {
            throw new Error(
                "Et link-komponent indeholder flere " +
                "nodes fra samme træ."
            );
        }

        for (const member of group) {
            componentOf.set(member, component);
        }
    }

    const manuscriptIndexByComponent =
        new Map<IndexedNode, number>();

    for (const entry of manuscript) {
        const component =
            componentOf.get(entry)!;

        if (
            !manuscriptIndexByComponent.has(
                component
            )
        ) {
            manuscriptIndexByComponent.set(
                component,
                entry.index
            );
        }
    }

    const plotIndexByComponent =
        new Map<IndexedNode, number>();

    for (const entry of plot) {
        const component =
            componentOf.get(entry)!;

        if (
            !plotIndexByComponent.has(component)
        ) {
            plotIndexByComponent.set(
                component,
                entry.index
            );
        }
    }

    /*
     * Ulinkede plotnoder foretrækkes lige før
     * næste linkede manuskriptkomponent.
     */
    const nextManuscriptByComponent =
        new Map<IndexedNode, number>();

    let nextManuscriptIndex = Infinity;

    for (
        let index = plot.length - 1;
        index >= 0;
        index -= 1
    ) {
        const component =
            componentOf.get(plot[index])!;

        const manuscriptIndex =
            manuscriptIndexByComponent.get(
                component
            );

        if (manuscriptIndex !== undefined) {
            nextManuscriptIndex =
                manuscriptIndex;
        } else if (
            !nextManuscriptByComponent.has(
                component
            )
        ) {
            nextManuscriptByComponent.set(
                component,
                nextManuscriptIndex
            );
        }
    }

    const graph = new ComponentGraph(
        groups.map(group => group[0])
    );

    /*
     * Manuskriptets DFS er den hårde hovedorden.
     */
    for (
        let index = 1;
        index < manuscript.length;
        index += 1
    ) {
        graph.add(
            componentOf.get(
                manuscript[index - 1]
            )!,
            componentOf.get(manuscript[index])!
        );
    }

    /*
     * Bevar plot-hierarki, hvor det ikke strider
     * mod manuskriptets hovedorden.
     */
    for (const entry of plot) {
        if (!entry.parent) {
            continue;
        }

        const parent =
            componentOf.get(entry.parent)!;

        const child =
            componentOf.get(entry)!;

        if (
            parent !== child &&
            !graph.wouldCreateCycle(parent, child)
        ) {
            graph.add(parent, child);
        }
    }

    /*
     * Første manuskript-link er række 0.
     */
    const anchor =
        manuscript.find(entry => {
            const component =
                componentOf.get(entry)!;

            return groupByComponent
                .get(component)!
                .some(
                    member =>
                        member.side === "plot"
                );
        });

    if (!anchor) {
        throw new Error(
            "Kunne ikke finde manuskriptanker."
        );
    }

    const ordered = graph.topologicalOrder(
        component => {
            const manuscriptIndex =
                manuscriptIndexByComponent.get(
                    component
                );

            if (manuscriptIndex !== undefined) {
                return [
                    manuscriptIndex * 2,
                    0,
                    plotIndexByComponent.get(
                        component
                    ) ?? Infinity,
                ] as const;
            }

            const next =
                nextManuscriptByComponent.get(
                    component
                ) ?? Infinity;

            return [
                next === Infinity
                    ? Infinity
                    : next * 2 - 1,
                1,
                plotIndexByComponent.get(
                    component
                ) ?? Infinity,
            ] as const;
        }
    );

    const anchorComponent =
        componentOf.get(anchor)!;

    const anchorIndex =
        ordered.indexOf(anchorComponent);

    ordered.forEach(
        (component, index) => {
            const row = index - anchorIndex;

            for (
                const member of
                groupByComponent.get(component)!
            ) {
                member.node.row = row;
            }
        }
    );
}

function indexDfs(
    root: TreeNode,
    side: "manuscript" | "plot"
): IndexedNode[] {
    const result: IndexedNode[] = [];

    function visit(
        node: TreeNode,
        parent?: IndexedNode
    ): void {
        const entry: IndexedNode = {
            node,
            side,
            index: result.length,
            parent,
        };

        result.push(entry);

        for (const child of node.children) {
            visit(child, entry);
        }
    }

    visit(root);

    return result;
}

function collectLinks(
    manuscript: IndexedNode[],
    plot: IndexedNode[],
    manuscriptByNode: Map<TreeNode, IndexedNode>,
    plotByNode: Map<TreeNode, IndexedNode>
): Array<[IndexedNode, IndexedNode]> {
    const result: Array<
        [IndexedNode, IndexedNode]
    > = [];

    const seen = new Set<string>();

    for (const entry of [...manuscript, ...plot]) {
        const target = entry.node.link;

        if (!target) {
            continue;
        }

        const other =
            entry.side === "manuscript"
                ? plotByNode.get(target)
                : manuscriptByNode.get(target);

        if (!other) {
            continue;
        }

        const left =
            entry.side === "manuscript"
                ? entry
                : other;

        const right =
            entry.side === "manuscript"
                ? other
                : entry;

        const linkKey =
            `${left.index}:${right.index}`;

        if (seen.has(linkKey)) {
            continue;
        }

        seen.add(linkKey);
        result.push([left, right]);
    }

    return result;
}

class Components {
    private readonly parent =
        new Map<IndexedNode, IndexedNode>();

    constructor(nodes: IndexedNode[]) {
        for (const node of nodes) {
            this.parent.set(node, node);
        }
    }

    private find(
        node: IndexedNode
    ): IndexedNode {
        const parent = this.parent.get(node)!;

        if (parent === node) {
            return node;
        }

        const root = this.find(parent);

        this.parent.set(node, root);

        return root;
    }

    join(
        left: IndexedNode,
        right: IndexedNode
    ): void {
        const leftRoot = this.find(left);
        const rightRoot = this.find(right);

        if (leftRoot !== rightRoot) {
            this.parent.set(
                rightRoot,
                leftRoot
            );
        }
    }

    groups(): IndexedNode[][] {
        const result =
            new Map<IndexedNode, IndexedNode[]>();

        for (const node of this.parent.keys()) {
            const root = this.find(node);

            const group =
                result.get(root) ?? [];

            group.push(node);
            result.set(root, group);
        }

        return [...result.values()];
    }
}

class ComponentGraph {
    private readonly edges =
        new Map<
            IndexedNode,
            Set<IndexedNode>
        >();

    constructor(nodes: IndexedNode[]) {
        for (const node of nodes) {
            this.edges.set(node, new Set());
        }
    }

    add(
        from: IndexedNode,
        to: IndexedNode
    ): void {
        if (from !== to) {
            this.edges.get(from)!.add(to);
        }
    }

    wouldCreateCycle(
        from: IndexedNode,
        to: IndexedNode
    ): boolean {
        if (from === to) {
            return false;
        }

        const visited = new Set<IndexedNode>();

        const reaches = (
            current: IndexedNode
        ): boolean => {
            if (current === from) {
                return true;
            }

            if (visited.has(current)) {
                return false;
            }

            visited.add(current);

            return [
                ...this.edges.get(current)!,
            ].some(reaches);
        };

        return reaches(to);
    }

    topologicalOrder(
        orderKey: (
            node: IndexedNode
        ) => readonly [number, number, number]
    ): IndexedNode[] {
        const incoming =
            new Map<IndexedNode, number>();

        for (const node of this.edges.keys()) {
            incoming.set(node, 0);
        }

        for (const targets of this.edges.values()) {
            for (const target of targets) {
                incoming.set(
                    target,
                    incoming.get(target)! + 1
                );
            }
        }

        const ready = [...this.edges.keys()]
            .filter(
                node => incoming.get(node) === 0
            );

        const result: IndexedNode[] = [];

        function compare(
            left: IndexedNode,
            right: IndexedNode
        ): number {
            const a = orderKey(left);
            const b = orderKey(right);

            for (
                let index = 0;
                index < 3;
                index += 1
            ) {
                if (a[index] !== b[index]) {
                    return a[index] < b[index]
                        ? -1
                        : 1;
                }
            }

            return left.node.id.localeCompare(
                right.node.id
            );
        }

        while (ready.length) {
            ready.sort(compare);

            const next = ready.shift()!;

            result.push(next);

            for (const target of this.edges.get(next)!) {
                incoming.set(
                    target,
                    incoming.get(target)! - 1
                );

                if (incoming.get(target) === 0) {
                    ready.push(target);
                }
            }
        }

        if (result.length !== this.edges.size) {
            throw new Error(
                "Rækkekonstraint indeholder en cyklus."
            );
        }

        return result;
    }
}

function cloneTree(
    node: TreeNode
): TreeNode {
    const {
        link: _link,
        children,
        layoutPreference,
        ...properties
    } = node;

    return {
        ...properties,
        layoutPreference:
            layoutPreference === undefined
                ? undefined
                : {
                    ...layoutPreference,
                },
        children: children.map(
            cloneTree
        ),
    };
}

function collectNodes(
    root: TreeNode,
    target: Map<string, TreeNode>
): void {
    target.set(root.id, root);

    for (const child of root.children) {
        collectNodes(child, target);
    }
}