import type { TreeNode } from "../model/types";
import {
    getOriginalPlotTree,
    getRuntimePlotTree,
} from "./structure";

import type {
    FocusVisibility,
} from "./focus";

type Side = "manuscript" | "plot";

export interface PresentationNode {
    id: string;
    source: TreeNode;
    type: "node" | "aggregate";
    side: Side;
    rowStart: number;
    rowEnd: number;
    preferredRow: number;
    localSceneId?: string;
}

export interface SemanticLink {
    sourceId: string;
    targetId: string;
}

export interface OmittedInterval {
    id: string;
    side: Side;
    rowStart: number;
    rowEnd: number;
    depth: number;
}

export interface PresentationEdge {
    /*
     * Synlige præsentationsknuder. De kan være
     * aggregates, når en gruppe er foldet sammen.
     */
    source: string;
    target: string;

    /*
     * De konkrete plotrelationer, som den tegnede
     * kant repræsenterer. Quicknav bruger disse
     * ids til tooltip og navigation.
     */
    semanticLinks: SemanticLink[];
}

export interface PresentationModel {
    nodes: PresentationNode[];
    edges: PresentationEdge[];
    visibleGroupKeys: Set<string>;
    omittedIntervals: OmittedInterval[];
}

interface SemanticNode {
    node: TreeNode;
    side: Side;
}

export function createPresentationModel(
    root: TreeNode,
    expanded: Set<string>,
    focus?: FocusVisibility
): PresentationModel {
    const originalPlot =
        getOriginalPlotTree(root);

    const runtimePlot =
        getRuntimePlotTree(root);

    const manuscriptById =
        indexTree(root);

    const plotById = runtimePlot
        ? indexTree(runtimePlot)
        : new Map<string, TreeNode>();

    const nodes: PresentationNode[] = [];

    const visibleByKey =
        new Map<string, PresentationNode>();

    const visibleAncestorByKey =
        new Map<string, PresentationNode>();

        const visibleGroupKeys =
    new Set<string>();

function isIncludedInFocus(
    original: TreeNode,
    side: Side
): boolean {
    if (!focus) {
        return true;
    }

    if (original.role === "container") {
        return focus.showsGroup(
            side,
            original.id
        );
    }

    /*
     * Manuskriptets semantiske blade
     * er ikke plotpunkter. Fokus viser
     * gruppehierarkiet på manus-siden,
     * mens plotpunkterne vises på plot-siden.
     */
    return (
        side === "plot" &&
        focus.showsPlotNode(original.id)
    );
}

    function runtimeNode(
        original: TreeNode,
        side: Side
    ): TreeNode {
        const indexed =
            side === "manuscript"
                ? manuscriptById.get(original.id)
                : plotById.get(original.id);

        return indexed ?? original;
    }

    function rowOf(node: TreeNode): number {
        if (node.row === undefined) {
            throw new Error(
                `Node mangler row: ${node.id}`
            );
        }

        return node.row;
    }

    function hiddenIntervalFor(
        original: TreeNode,
        side: Side
    ): {
        start: number;
        end: number;
    } {
        const start = rowOf(
            runtimeNode(original, side)
        );

        let end = start;

        function collectHidden(
            node: TreeNode
        ): void {
            for (const child of node.children) {
                const childRow = rowOf(
                    runtimeNode(child, side)
                );

                end = Math.max(
                    end,
                    childRow
                );

                collectHidden(child);
            }
        }

        collectHidden(original);

        return { start, end };
    }

    function add(
        original: TreeNode,
        side: Side,
        type: "node" | "aggregate"
    ): PresentationNode {
        const source =
            runtimeNode(original, side);

        const interval =
            type === "aggregate"
                ? hiddenIntervalFor(
                    original,
                    side
                )
                : {
                    start: rowOf(source),
                    end: rowOf(source),
                };

        const result: PresentationNode = {
            id: source.id,
            source,
            type,
            side,
            rowStart: interval.start,
            rowEnd: interval.end,
            preferredRow: rowOf(source),
        };

        nodes.push(result);

        visibleByKey.set(
            key(side, source.id),
            result
        );

        return result;
    }

    function markDescendants(
        node: TreeNode,
        side: Side,
        aggregate: PresentationNode
    ): void {
        for (const child of node.children) {
            visibleAncestorByKey.set(
                key(side, child.id),
                aggregate
            );

            markDescendants(
                child,
                side,
                aggregate
            );
        }
    }

   function visit(
    original: TreeNode,
    side: Side,
    isRoot = false
): void {
    if (
        !isIncludedInFocus(
            original,
            side
        )
    ) {
        return;
    }

    const node =
        runtimeNode(original, side);

    if (node.role === "node") {
        add(original, side, "node");
        return;
    }

    visibleGroupKeys.add(
        key(side, node.id)
    );

    /*
     * I fokus er alle beholdte grupper
     * altid udfoldede. Uden fokus bruges
     * den sædvanlige manuelle tilstand.
     */
    if (
        !isRoot &&
        !focus &&
        !expanded.has(node.id)
    ) {
        const aggregate =
            add(original, side, "aggregate");

        markDescendants(
            original,
            side,
            aggregate
        );

        return;
    }

    for (const child of original.children) {
        visit(child, side);
    }
}

    visit(root, "manuscript", true);

    if (originalPlot && runtimePlot) {
        visit(originalPlot, "plot", true);
    }

    function visible(
        side: Side,
        id: string
    ): PresentationNode | undefined {
        return (
            visibleByKey.get(key(side, id)) ??
            visibleAncestorByKey.get(key(side, id))
        );
    }

    const semanticNodes: SemanticNode[] = [];

   function collectSemantic(
    original: TreeNode,
    side: Side
): void {
    if (
        !isIncludedInFocus(
            original,
            side
        )
    ) {
        return;
    }

    semanticNodes.push({
        node: runtimeNode(original, side),
        side,
    });

    for (const child of original.children) {
        collectSemantic(child, side);
    }
}

    collectSemantic(root, "manuscript");

    if (originalPlot && runtimePlot) {
        collectSemantic(originalPlot, "plot");
    }

const edges: PresentationEdge[] = [];

const edgeByKey =
    new Map<string, PresentationEdge>();

for (const {
    node,
    side,
} of semanticNodes) {
    const target = visible(side, node.id);

    if (!target) {
        continue;
    }

    for (
        const prerequisiteId of
        node.prerequisites
    ) {
        const source = visible(
            side,
            prerequisiteId
        );

        /*
         * En intern relation i samme foldede
         * gruppe får ingen synlig kant og dermed
         * heller ingen quicknav-markør.
         */
        if (
            !source ||
            source.id === target.id
        ) {
            continue;
        }

        const edgeKey =
            `${side}:${source.id}->${target.id}`;

        let edge =
            edgeByKey.get(edgeKey);

        if (!edge) {
            edge = {
                source: source.id,
                target: target.id,
                semanticLinks: [],
            };

            edgeByKey.set(edgeKey, edge);
            edges.push(edge);
        }

        const linkAlreadyKnown =
            edge.semanticLinks.some(
                link =>
                    link.sourceId ===
                        prerequisiteId &&
                    link.targetId === node.id
            );

        if (!linkAlreadyKnown) {
            edge.semanticLinks.push({
                sourceId: prerequisiteId,
                targetId: node.id,
            });
        }
    }
}

    /*
     * Plotnoders lodrette rækkefølge bestemmes
     * lokalt af scenens kausale DAG. Kanter til
     * andre scener ændrer ikke Y, men bevares i
     * edges og kan derfor fortsat påvirke X.
     */
    if (runtimePlot) {
        applyLocalPlotDagRows(
            nodes,
            edges,
            runtimePlot
        );
    }

    nodes.sort((left, right) => {
        if (left.rowStart !== right.rowStart) {
            return left.rowStart - right.rowStart;
        }

        if (left.rowEnd !== right.rowEnd) {
            return left.rowEnd - right.rowEnd;
        }

        if (left.side !== right.side) {
            return left.side === "manuscript"
                ? -1
                : 1;
        }

        return left.id.localeCompare(right.id);
    });

    function collectOmittedIntervals(
    originalRoot: TreeNode,
    side: Side
): OmittedInterval[] {
    const intervals: OmittedInterval[] = [];

    function lastDescendantRow(
        node: TreeNode
    ): number {
        let last = rowOf(
            runtimeNode(node, side)
        );

        for (const child of node.children) {
            last = Math.max(
                last,
                lastDescendantRow(child)
            );
        }

        return last;
    }

    function visit(
    parent: TreeNode,
    parentDepth: number
): void {
        let firstOmitted:
            | TreeNode
            | undefined;

        let lastOmitted:
            | TreeNode
            | undefined;

        function flush(): void {
            if (
                !firstOmitted ||
                !lastOmitted
            ) {
                return;
            }

            intervals.push({
                id:
                    `omitted:${side}:` +
                    `${firstOmitted.id}:` +
                    `${lastOmitted.id}`,
                side,
                rowStart: rowOf(
                    runtimeNode(
                        firstOmitted,
                        side
                    )
                ),
                rowEnd: lastDescendantRow(
                    lastOmitted
                ),
                depth: parentDepth + 1,
            });

            firstOmitted = undefined;
            lastOmitted = undefined;
        }

        for (const child of parent.children) {
            const included =
                isIncludedInFocus(
                    child,
                    side
                );

            if (
                child.role === "container" &&
                !included
            ) {
                firstOmitted ??= child;
                lastOmitted = child;
                continue;
            }

            flush();

            if (
                child.role === "container" &&
                included
            ) {
                visit(child, parentDepth + 1);
            }
        }

        flush();
    }

    visit(originalRoot, 0);

    return intervals;
}

function mergeOmittedIntervals(
    intervals: OmittedInterval[]
): OmittedInterval[] {
    const result: OmittedInterval[] = [];

    const ordered = [...intervals].sort(
        (left, right) =>
            left.rowStart - right.rowStart ||
            left.rowEnd - right.rowEnd
    );

    for (const interval of ordered) {
        const previous =
            result[result.length - 1];

        /*
         * Manus- og plotintervallet for samme
         * skjulte scene overlapper semantisk.
         * De skal tegnes som ét fælles bånd.
         */
        if (
            previous &&
            interval.rowStart <= previous.rowEnd
        ) {
            const manuscriptInterval =
                previous.side === "manuscript"
                    ? previous
                    : interval.side === "manuscript"
                        ? interval
                        : undefined;

            result[result.length - 1] = {
                id:
                    `omitted:` +
                    `${previous.id}:` +
                    `${interval.id}`,
                side:
                    manuscriptInterval?.side ??
                    previous.side,
                rowStart: Math.min(
                    previous.rowStart,
                    interval.rowStart
                ),
                rowEnd: Math.max(
                    previous.rowEnd,
                    interval.rowEnd
                ),
                depth:
                    manuscriptInterval?.depth ??
                    Math.min(
                        previous.depth,
                        interval.depth
                    ),
            };

            continue;
        }

        result.push(interval);
    }

    return result;
}

    const omittedIntervals =
    focus
        ? mergeOmittedIntervals([
            ...collectOmittedIntervals(
                root,
                "manuscript"
            ),
            ...(originalPlot
                ? collectOmittedIntervals(
                    originalPlot,
                    "plot"
                )
                : []),
        ])
        : [];

return {
    nodes,
    edges,
    visibleGroupKeys,
    omittedIntervals,
};
}

function applyLocalPlotDagRows(
    presentationNodes: PresentationNode[],
    _edges: PresentationEdge[],
    plotRoot: TreeNode
): void {
    const sceneByNodeId =
        new Map<string, string>();

    const rangeBySceneId =
        new Map<
            string,
            {
                start: number;
                end: number;
            }
        >();

    const semanticNodesByScene =
        new Map<string, TreeNode[]>();

    function rowOf(node: TreeNode): number {
        if (node.row === undefined) {
            throw new Error(
                `Plotnode mangler row: ${node.id}`
            );
        }

        return node.row;
    }

    function lastDescendantRow(
        node: TreeNode
    ): number {
        return node.children.reduce(
            (last, child) =>
                Math.max(
                    last,
                    lastDescendantRow(child)
                ),
            rowOf(node)
        );
    }

    function indexScenes(
        scene: TreeNode
    ): void {
        rangeBySceneId.set(scene.id, {
            start: rowOf(scene) + 1,
            end: lastDescendantRow(scene),
        });

        const directNodes = scene.children.filter(
            child => child.role === "node"
        );

        semanticNodesByScene.set(
            scene.id,
            directNodes
        );

        for (const node of directNodes) {
            sceneByNodeId.set(
                node.id,
                scene.id
            );
        }

        for (const child of scene.children) {
            if (child.role === "container") {
                indexScenes(child);
            }
        }
    }

    indexScenes(plotRoot);

    const visibleNodesByScene =
        new Map<
            string,
            PresentationNode[]
        >();

    for (const node of presentationNodes) {
        if (
            node.side !== "plot" ||
            node.type !== "node"
        ) {
            continue;
        }

        const sceneId =
            sceneByNodeId.get(node.id);

        if (!sceneId) {
            continue;
        }

        node.localSceneId = sceneId;

        const visibleNodes =
            visibleNodesByScene.get(sceneId) ?? [];

        visibleNodes.push(node);

        visibleNodesByScene.set(
            sceneId,
            visibleNodes
        );
    }

    /*
     * Vigtigt: semanticNodes er hele scenens
     * faktiske plotpunkter — ikke kun dem fokus
     * viser lige nu. Derfor ændrer fokus ikke
     * brugerens rank-system.
     */
    for (const [
        sceneId,
        semanticNodes,
    ] of semanticNodesByScene) {
        const visibleNodes =
            visibleNodesByScene.get(sceneId) ?? [];

        if (visibleNodes.length === 0) {
            continue;
        }

        const sceneRange =
    rangeBySceneId.get(sceneId);

if (!sceneRange) {
    continue;
}

const sceneStart = sceneRange.start;
const sceneEnd = sceneRange.end;

const availableRows =
    sceneEnd -
    sceneStart +
    1;

        if (availableRows < 1) {
            continue;
        }

        const semanticById =
            new Map(
                semanticNodes.map(node => [
                    node.id,
                    node,
                ])
            );

        const successors =
            new Map<string, Set<string>>();

        const predecessors =
            new Map<string, Set<string>>();

        const incoming =
            new Map<string, number>();

        for (const node of semanticNodes) {
            successors.set(node.id, new Set());
            predecessors.set(node.id, new Set());
            incoming.set(node.id, 0);
        }

        for (const node of semanticNodes) {
            for (
                const prerequisiteId of
                node.prerequisites
            ) {
                if (
                    !semanticById.has(
                        prerequisiteId
                    )
                ) {
                    continue;
                }

                const targets =
                    successors.get(
                        prerequisiteId
                    )!;

                if (targets.has(node.id)) {
                    continue;
                }

                targets.add(node.id);

                predecessors
                    .get(node.id)!
                    .add(prerequisiteId);

                incoming.set(
                    node.id,
                    incoming.get(node.id)! + 1
                );
            }
        }

        const ready = semanticNodes
            .filter(
                node =>
                    incoming.get(node.id) === 0
            )
            .sort(
                (left, right) =>
                    rowOf(left) -
                    rowOf(right)
            );

        const topologicalOrder: TreeNode[] = [];

        while (ready.length > 0) {
            const node = ready.shift()!;

            topologicalOrder.push(node);

            for (
                const targetId of
                successors.get(node.id) ?? []
            ) {
                const remaining =
                    incoming.get(targetId)! - 1;

                incoming.set(
                    targetId,
                    remaining
                );

                if (remaining === 0) {
                    ready.push(
                        semanticById.get(targetId)!
                    );

                    ready.sort(
                        (left, right) =>
                            rowOf(left) -
                            rowOf(right)
                    );
                }
            }
        }

        /*
         * En cyklisk scene kan ikke få sikre
         * kausale rank-intervaller. Behold dens
         * eksisterende semantiske rows.
         */
        if (
            topologicalOrder.length !==
            semanticNodes.length
        ) {
            continue;
        }

        const minimumRank =
            new Map<string, number>();

        for (const node of topologicalOrder) {
            const predecessorRanks = [
                ...(
                    predecessors.get(node.id) ??
                    []
                ),
            ].map(
                predecessorId =>
                    minimumRank.get(
                        predecessorId
                    ) ?? 0
            );

            minimumRank.set(
                node.id,
                predecessorRanks.length === 0
                    ? 0
                    : Math.max(
                        ...predecessorRanks
                    ) + 1
            );
        }

        const distanceToSink =
            new Map<string, number>();

        for (
            let index =
                topologicalOrder.length - 1;
            index >= 0;
            index--
        ) {
            const node =
                topologicalOrder[index];

            const successorDistances = [
                ...(
                    successors.get(node.id) ??
                    []
                ),
            ].map(
                successorId =>
                    distanceToSink.get(
                        successorId
                    ) ?? 0
            );

            distanceToSink.set(
                node.id,
                successorDistances.length === 0
                    ? 0
                    : Math.max(
                        ...successorDistances
                    ) + 1
            );
        }

        const minimumLayerCount =
            Math.max(
                ...minimumRank.values()
            ) + 1;

        const layerCount =
            Math.min(
                availableRows,
                Math.max(
                    minimumLayerCount,
                    semanticNodes.length
                )
            );

        const rankById =
            new Map<string, number>();

        for (const node of topologicalOrder) {
            const minimum =
                minimumRank.get(node.id) ?? 0;

            const maximum =
                layerCount -
                1 -
                (
                    distanceToSink.get(
                        node.id
                    ) ?? 0
                );

            const verticalRank =
                node.layoutPreference?.verticalRank;

            const requested =
                verticalRank === undefined
                    ? minimum
                    : Math.round(
                        Math.max(
                            0,
                            Math.min(
                                1,
                                verticalRank
                            )
                        ) *
                        Math.max(
                            0,
                            layerCount - 1
                        )
                    );

            const predecessorRank =
                Math.max(
                    -1,
                    ...[
                        ...(
                            predecessors.get(
                                node.id
                            ) ?? []
                        ),
                    ].map(
                        predecessorId =>
                            rankById.get(
                                predecessorId
                            ) ?? -1
                    )
                );

            rankById.set(
                node.id,
                Math.min(
                    maximum,
                    Math.max(
                        minimum,
                        requested,
                        predecessorRank + 1
                    )
                )
            );
        }

        function rowForRank(
            rank: number
        ): number {
            if (layerCount <= 1) {
                return sceneStart;
            }

            return (
                sceneStart +
                Math.round(
                    rank *
                    (availableRows - 1) /
                    (layerCount - 1)
                )
            );
        }

        const usedRanks = [
            ...new Set(
                rankById.values()
            ),
        ].sort((left, right) => left - right);

        for (const node of visibleNodes) {
            const rank =
                rankById.get(node.id) ?? 0;

            const rowStart =
                rowForRank(rank);

            const nextRank =
                usedRanks.find(
                    candidate => candidate > rank
                );

            const rowEnd =
                nextRank === undefined
                    ? sceneEnd
                    : Math.max(
                        rowStart,
                        rowForRank(nextRank) - 1
                    );

            node.rowStart = rowStart;
            node.rowEnd = rowEnd;
            node.preferredRow = rowStart;
        }
    }
}

function indexTree(
    root: TreeNode
): Map<string, TreeNode> {
    const result =
        new Map<string, TreeNode>();

    function visit(node: TreeNode): void {
        result.set(node.id, node);

        for (const child of node.children) {
            visit(child);
        }
    }

    visit(root);

    return result;
}

function key(
    side: Side,
    id: string
): string {
    return `${side}:${id}`;
}

