import * as d3 from "d3";

import {
    createRadialMenu,
} from "../components/RadialMenuD3";

import type {
    RadialMenuItem,
} from "../components/RadialMenuD3";

import {
    renderPlotGraphIcon,
} from "../components/plotGraphIcons";

import type {
    SimulationNode,
} from "./GraphCanvas.helpers";

const BOOKMARK_LINK_PREFIX =
    "onlyoffice:bookmark:";

export interface GraphRadialMenuCallbacks {
    getNotionPageUrl: (
        nodeId: string
    ) => string | null;

    onSelect: (
        nodeId: string,
        item: RadialMenuItem
    ) => void;

    onNavigateBookmark: (
        bookmarkName: string
    ) => void;

    onToggle: (
        nodeId: string,
        item: RadialMenuItem,
        active: boolean
    ) => void;

    onDragStart: (
        node: SimulationNode,
        item: RadialMenuItem
    ) => void;

    onDrag: (
        item: RadialMenuItem,
        x: number,
        y: number
    ) => void;

    onDragEnd: (
        item: RadialMenuItem,
        x: number,
        y: number
    ) => Promise<void>;

    canDeletePlotNode: (
        nodeId: string
    ) => boolean;
}

export function createRadialMenuCenter(
    nodeId: string,
    bookmarkName: string | undefined,
    selection: {
        type: "node";
        id: string;
    } | null,
    causalNeighborhoodLocked: boolean,
    causalNeighborhoodLockNodeId: string | null
): RadialMenuItem {
    if (bookmarkName) {
        return {
            id: "navigate-bookmark",
            label: "Gå til tilknyttet tekst",
            icon: "link",
            interactive: true,
            draggable: false,
        };
    }

    const isMarked =
        selection?.type === "node" &&
        selection.id === nodeId;

    const isPinned =
        causalNeighborhoodLocked &&
        causalNeighborhoodLockNodeId === nodeId;

    return {
        id: "mark-node",
        label: isPinned
            ? "Fastlåst plotpunkt"
            : isMarked
              ? "Afmarkér node"
              : "Markér node",
        icon: "mark",
        interactive: true,
        draggable: true,
        toggle: !isPinned,
        active: isMarked || isPinned,
        activeIcon: "mark",
    };
}

export function createRadialMenuItems(
    nodeId: string,
    getNotionPageUrl: (
        nodeId: string
    ) => string | null,
    causalNeighborhoodLocked: boolean,
    causalNeighborhoodLockNodeId: string | null,
    hasTextSelection: boolean,
    bookmarkName: string | undefined,
    isPlotNode: boolean,
    canDeleteNode: boolean
): RadialMenuItem[] {
    const isPinned =
        causalNeighborhoodLocked &&
        causalNeighborhoodLockNodeId === nodeId;

    const items: RadialMenuItem[] = [
        {
            id: "create-prerequisite",
            label: "Opret forudsætning",
            icon: "prerequisite",
            interactive: true,
            draggable: true,
            preferredAngle: 0,
        },

        {
            id: "notion",
            label: "Navigér til plotpunkt i Notion",
            icon: "notion",
            interactive: Boolean(
                getNotionPageUrl(nodeId)
            ),
        },

        {
            id: "create-consequence",
            label: "Opret følge",
            icon: "consequence",
            interactive: true,
            draggable: true,
            preferredAngle: 180,
        },

        {
            id: "lock-causal-neighborhood",
            label: "Lås kausalt nabolag",
            icon: "pin",
            interactive: true,
            toggle: true,
            active: isPinned,
            preferredAngle: 90,
        },

        {
            id: "rename-node",
            label: "Omdøb plotpunkt",
            icon: "rename",
            interactive: true,
            preferredAngle: 270,
            children: [
                {
                    id: "delete-node",
                    label: "Slet plotpunkt",
                    icon: "delete",
                    interactive:
                        isPlotNode &&
                        canDeleteNode,
                },
            ],
        },
    ];

    if (!isPlotNode) {
        return items;
    }

    const bookmarkAction: RadialMenuItem =
        hasTextSelection
            ? {
                id: "create-bookmark",
                label: bookmarkName
                    ? "Erstat tilknyttet tekst"
                    : "Knyt markeret tekst",
                icon: "link",
                interactive: true,
            }
            : bookmarkName
              ? {
                  id: "text-unlink",
                  label: "Frigør tilknyttet tekst",
                  icon: "unlink",
                  interactive: true,
              }
              : {
                  id: "create-bookmark",
                  label: "Knyt markeret tekst",
                  icon: "link",
                  interactive: false,
              };

    items.splice(2, 0, bookmarkAction);

    return items;
}

export function renderGraphRadialMenus(
    nodeGroups: d3.Selection<
        SVGGElement,
        SimulationNode,
        SVGGElement,
        unknown
    >,
    selection: {
        type: "node";
        id: string;
    } | null,
    causalNeighborhoodLocked: boolean,
    causalNeighborhoodLockNodeId: string | null,
    validBookmarkNames: ReadonlySet<string>,
    hasTextSelection: boolean,
    callbacks: GraphRadialMenuCallbacks
): Array<ReturnType<typeof createRadialMenu>> {
    const radialMenuInstances: Array<
        ReturnType<typeof createRadialMenu>
    > = [];

    nodeGroups
        .filter(
            node =>
                node.node.type !== "aggregate"
        )
        .each(function (node) {
            const nodeId =
                node.node.source.id;

            const isPlotNode =
                node.node.side === "plot" &&
                node.node.source.role === "node";

            const canDeleteNode =
                isPlotNode &&
                callbacks.canDeletePlotNode(
                    nodeId
                );

            const candidateBookmarkName =
                isPlotNode
                    ? getBookmarkName(
                        node.node.source.linkMasterId
                    )
                    : undefined;

            const bookmarkName =
                candidateBookmarkName &&
                validBookmarkNames.has(
                    candidateBookmarkName
                )
                    ? candidateBookmarkName
                    : undefined;

            const menu = createRadialMenu(
                d3.select(this),
                {
                    x: 0,
                    y: 0,

                    center: createRadialMenuCenter(
                        nodeId,
                        bookmarkName,
                        selection,
                        causalNeighborhoodLocked,
                        causalNeighborhoodLockNodeId
                    ),

                    secondary:
                        createRadialMenuItems(
                            nodeId,
                            callbacks.getNotionPageUrl,
                            causalNeighborhoodLocked,
                            causalNeighborhoodLockNodeId,
                            hasTextSelection,
                            bookmarkName,
                            isPlotNode,
                            canDeleteNode
                        ),

                    onSelect: item => {
                        if (
                            item.id ===
                                "navigate-bookmark" &&
                            bookmarkName
                        ) {
                            callbacks.onNavigateBookmark(
                                bookmarkName
                            );

                            return;
                        }

                        callbacks.onSelect(
                            nodeId,
                            item
                        );
                    },

                    onToggle: (
                        item,
                        active
                    ) =>
                        callbacks.onToggle(
                            nodeId,
                            item,
                            active
                        ),

                    onDragStart: item =>
                        callbacks.onDragStart(
                            node,
                            item
                        ),

                    onDrag: (
                        item,
                        x,
                        y
                    ) =>
                        callbacks.onDrag(
                            item,
                            x,
                            y
                        ),

                    onDragEnd: async (
                        item,
                        x,
                        y
                    ) =>
                        callbacks.onDragEnd(
                            item,
                            x,
                            y
                        ),

                    renderIcon:
                        renderPlotGraphIcon,
                }
            );

            radialMenuInstances.push(menu);
        });

    return radialMenuInstances;
}

export function destroyGraphRadialMenus(
    radialMenuInstances: Array<
        ReturnType<typeof createRadialMenu>
    >
): void {
    radialMenuInstances.forEach(
        menu => menu.destroy()
    );
}

function getBookmarkName(
    linkMasterId: string | undefined
): string | undefined {
    if (
        !linkMasterId?.startsWith(
            BOOKMARK_LINK_PREFIX
        )
    ) {
        return undefined;
    }

    return linkMasterId.slice(
        BOOKMARK_LINK_PREFIX.length
    );
}