import * as d3 from "d3";

import type {
    SimulationEdge,
    SimulationNode,
} from "./GraphCanvas.helpers";

import {
    isCausalEdge,
} from "./GraphEdges";


interface QuickNavTarget {
    id: string;
    label: string;
}

interface QuickNavItem {
    key: string;
    target: QuickNavTarget;
    direction: "up" | "down";
    x: number;
    y: number;
}

interface EdgeCurve {
    p0: Point;
    p1: Point;
    p2: Point;
    p3: Point;
}

interface Point {
    x: number;
    y: number;
}

export interface GraphQuickNav {
    update(): void;
    destroy(): void;
}

export function createGraphQuickNav(
    d3Layer: d3.Selection<
        SVGGElement,
        unknown,
        null,
        undefined
    >,
    canvas: HTMLDivElement,
    edges: SimulationEdge[],
    causalFocusNodeIds: ReadonlySet<string>,
    causalNeighborhood: {
        upstream: Set<string>;
        downstream: Set<string>;
    },
    getPlotLabel: (
        nodeId: string
    ) => string | null,
    onNavigate: (
        targetId: string
    ) => void
): GraphQuickNav {
    const layer =
        d3Layer
            .append("g")
            .attr(
                "class",
                "quick-nav"
            );

    function update(): void {
        const items = collectQuickNavItems(
            canvas,
            edges,
            causalFocusNodeIds,
            causalNeighborhood,
            getPlotLabel
        );

        const markers =
            layer
                .selectAll<
                    SVGGElement,
                    QuickNavItem
                >("g.quick-nav-item")
                .data(
                    items,
                    item => item.key
                )
                .join(
                    enter => {
                        const marker =
                            enter
                                .append("g")
                                .attr(
                                    "class",
                                    "quick-nav-item"
                                )
                                .style(
                                    "cursor",
                                    "pointer"
                                );

                        marker
                            .append("circle")
                            .attr("r", 10)
                            .attr("fill", "#fff")
                            .attr("stroke", "#555")
                            .attr(
                                "stroke-width",
                                1.5
                            );

                        marker
                            .append("text")
                            .attr(
                                "text-anchor",
                                "middle"
                            )
                            .attr(
                                "dy",
                                "0.35em"
                            )
                            .attr(
                                "font-size",
                                "12px"
                            )
                            .attr("fill", "#555");

                        marker.append("title");

                        return marker;
                    }
                )
                .attr(
                    "transform",
                    item =>
                        `translate(${item.x},${item.y})`
                )
                .on(
                    "click",
                    (event, item) => {
                        event.stopPropagation();

                        onNavigate(item.target.id);
                    }
                );

        markers
            .select<SVGTextElement>("text")
            .text(
                item =>
                    item.direction === "up"
                        ? "↑"
                        : "↓"
            );

        markers
            .select<SVGTitleElement>("title")
            .text(item => item.target.label);
    }

    return {
        update,

        destroy(): void {
            layer.remove();
        },
    };
}

function collectQuickNavItems(
    canvas: HTMLDivElement,
    edges: SimulationEdge[],
    causalFocusNodeIds: ReadonlySet<string>,
    causalNeighborhood: {
        upstream: Set<string>;
        downstream: Set<string>;
    },
    getPlotLabel: (
        nodeId: string
    ) => string | null
): QuickNavItem[] {
    if (causalFocusNodeIds.size === 0) {
        return [];
    }

   const svg =
    canvas.querySelector("svg");

const svgTop =
    svg
        ? svg.getBoundingClientRect().top -
            canvas.getBoundingClientRect().top +
            canvas.scrollTop
        : 0;

const top = canvas.scrollTop;

const bottom =
    top +
    canvas.clientHeight -
    svgTop;

    const byKey =
        new Map<string, QuickNavItem>();

    for (const edge of edges) {
        if (
            !isCausalEdge(
                edge,
                causalFocusNodeIds,
                causalNeighborhood
            )
        ) {
            continue;
        }

        const source = edge.sourceNode;
        const target = edge.targetNode;

        if (!source || !target) {
            continue;
        }

        const sourceVisible =
            isVisible(source, top, bottom);

        const targetVisible =
            isVisible(target, top, bottom);

        if (sourceVisible === targetVisible) {
            continue;
        }

        const direction =
            sourceVisible
                ? target.y < top
                    ? "up"
                    : "down"
                : source.y < top
                    ? "up"
                    : "down";

        const boundaryY =
            direction === "up"
                ? top + 12
                : bottom - 12;

        const intersection =
            findViewportIntersection(
                source,
                target,
                boundaryY,
                sourceVisible
            );

        if (!intersection) {
            continue;
        }

        const semanticLinks =
            edge.semanticLinks ?? [];

        for (const link of semanticLinks) {
            const destinationId =
                sourceVisible
                    ? link.targetId
                    : link.sourceId;

            const label =
                getPlotLabel(destinationId);

            if (!label) {
                continue;
            }

            const key =
                `${direction}:${destinationId}`;

            if (byKey.has(key)) {
                continue;
            }

            byKey.set(key, {
                key,
                target: {
                    id: destinationId,
                    label,
                },
                direction,
                x: intersection.x,
                y: intersection.y,
            });
        }
    }

    return [...byKey.values()];
}

function isVisible(
    node: SimulationNode,
    top: number,
    bottom: number
): boolean {
    return (
        node.y >= top &&
        node.y <= bottom
    );
}

function findViewportIntersection(
    source: SimulationNode,
    target: SimulationNode,
    boundaryY: number,
    sourceVisible: boolean
): Point | null {
    const curve =
        createEdgeCurve(source, target);

    const crossings: number[] = [];
    const steps = 80;

    let previousT = 0;
    let previous =
        cubicBezierPoint(
            curve,
            previousT
        );

    for (
        let index = 1;
        index <= steps;
        index++
    ) {
        const currentT =
            index / steps;

        const current =
            cubicBezierPoint(
                curve,
                currentT
            );

        if (
            crossesBoundary(
                previous.y,
                current.y,
                boundaryY
            )
        ) {
            crossings.push(
                refineIntersection(
                    curve,
                    previousT,
                    currentT,
                    boundaryY
                )
            );
        }

        previousT = currentT;
        previous = current;
    }

    if (crossings.length === 0) {
        return null;
    }

    const t =
        sourceVisible
            ? crossings[0]
            : crossings[crossings.length - 1];

    return cubicBezierPoint(curve, t);
}

function crossesBoundary(
    firstY: number,
    secondY: number,
    boundaryY: number
): boolean {
    return (
        (firstY <= boundaryY &&
            secondY >= boundaryY) ||
        (firstY >= boundaryY &&
            secondY <= boundaryY)
    );
}

function refineIntersection(
    curve: EdgeCurve,
    startT: number,
    endT: number,
    boundaryY: number
): number {
    let low = startT;
    let high = endT;

    const lowY =
        cubicBezierPoint(curve, low).y;

    for (
        let iteration = 0;
        iteration < 18;
        iteration++
    ) {
        const middle =
            (low + high) / 2;

        const middleY =
            cubicBezierPoint(curve, middle).y;

        if (
            (lowY <= boundaryY &&
                middleY <= boundaryY) ||
            (lowY >= boundaryY &&
                middleY >= boundaryY)
        ) {
            low = middle;
        } else {
            high = middle;
        }
    }

    return (low + high) / 2;
}

function createEdgeCurve(
    source: SimulationNode,
    target: SimulationNode
): EdgeCurve {
    const dx = target.x - source.x;
    const dy = target.y - source.y;

    const curve =
        Math.max(
            35,
            Math.abs(dx) * 0.35
        );

    const direction =
        dx >= 0 ? 1 : -1;

    const targetRadius =
        target.node.type === "aggregate"
            ? 14
            : 7;

    return {
        p0: {
            x: source.x,
            y: source.y,
        },
        p1: {
            x:
                source.x +
                direction * curve,
            y: source.y,
        },
        p2: {
            x: target.x,
            y:
                target.y -
                Math.sign(dy) * curve,
        },
        p3: {
            x: target.x,
            y:
                target.y -
                Math.sign(dy) *
                    targetRadius,
        },
    };
}

function cubicBezierPoint(
    curve: EdgeCurve,
    t: number
): Point {
    const u = 1 - t;

    return {
        x:
            u * u * u * curve.p0.x +
            3 *
                u *
                u *
                t *
                curve.p1.x +
            3 *
                u *
                t *
                t *
                curve.p2.x +
            t *
                t *
                t *
                curve.p3.x,

        y:
            u * u * u * curve.p0.y +
            3 *
                u *
                u *
                t *
                curve.p1.y +
            3 *
                u *
                t *
                t *
                curve.p2.y +
            t *
                t *
                t *
                curve.p3.y,
    };
}